// The drawing of Stack the castle: the scenery that falls away as the camera rises, the pieces, what holds the
// swinging one, the crumbs that fall off, and the flag or the builder on top. Sizes are in canvas pixels.

/** Overhang trimmed off a piece: the [cut] (in the round's widths), [height] tall at world height [bottom], cut at round time [born]. */
internal class Crumble(val cut: StackPiece, val bottom: Float, val height: Float, val seed: Int, val born: Float)

/**
 * The sky, the far band and the ground with the camera risen by [camera]. The far band and the clouds move slower
 * than the tower, so climbing feels like climbing. [t] is the scene clock.
 */
internal fun DrawScope.drawStackScenery(look: StackLook, layout: StackLayout, camera: Float, t: Float) {
    val w = size.width
    val h = size.height
    drawRect(Brush.verticalGradient(listOf(look.skyTop, look.skyBottom), 0f, h))
    // Clouds drift by at different heights.
    for (k in 0 until 5) {
        val p = 0.35f + 0.08f * k
        val y = layout.y(h * (0.55f + 0.42f * k), camera, p)
        if (y < -h * 0.2f || y > h * 1.1f) continue
        val x = w * ((noise(k * 13 + 5) + t * (2 + k)) % 1f) * 1.3f - w * 0.15f
        val r = layout.piece * (0.9f + 0.5f * noise(k * 7 + 1))
        val white = Color.White.copy(alpha = 0.8f)
        drawCircle(white, r, Offset(x, y))
        drawCircle(white, r * 0.75f, Offset(x - r * 1.05f, y + r * 0.25f))
        drawCircle(white, r * 0.8f, Offset(x + r * 1.1f, y + r * 0.2f))
        drawRoundRect(white, Offset(x - r * 1.7f, y), Size(r * 3.5f, r * 0.85f), CornerRadius(r * 0.42f))
    }
    val far = layout.y(layout.piece * 2.4f, camera, 0.6f)
    when (look.kind) {
        StackKind.SAND -> {
            // The sun, and the sea from the horizon down behind the beach.
            drawGlow(Offset(w * 0.82f, layout.y(h * 0.78f, camera, 0.15f)), layout.piece * 2.6f, Color(0xFFFFF4B8).copy(alpha = 0.9f))
            drawCircle(Color(0xFFFFE680), layout.piece * 0.9f, Offset(w * 0.82f, layout.y(h * 0.78f, camera, 0.15f)))
            drawRect(Brush.verticalGradient(listOf(look.farLight, look.far), far, far + layout.piece * 3f), Offset(0f, far), Size(w, h - far + camera))
            for (k in 0 until 4) {
                val y = far + layout.piece * (0.5f + 0.6f * k)
                val shift = swing(t, 30 + 6 * k) * w * 0.02f
                drawLine(Color.White.copy(alpha = 0.35f - 0.06f * k), Offset(w * (0.1f + 0.2f * k) + shift, y), Offset(w * (0.3f + 0.2f * k) + shift, y), layout.piece * 0.08f, StrokeCap.Round)
            }
        }
        StackKind.BRICKS -> {
            // A town of far blocks with windows, behind the site.
            var x = -w * 0.05f
            var k = 0
            while (x < w) {
                val bw = w * (0.12f + 0.08f * noise(k * 5 + 2))
                val bh = layout.piece * (2.2f + 4.5f * noise(k * 11 + 3))
                drawRect(look.far, Offset(x, far - bh), Size(bw - w * 0.012f, h - far + bh + camera))
                drawRect(look.farLight, Offset(x, far - bh), Size(bw - w * 0.012f, layout.piece * 0.12f))
                val win = layout.piece * 0.28f
                var wy = far - bh + win
                while (wy < far + layout.piece) {
                    var wx = x + win * 0.7f
                    while (wx + win < x + bw - w * 0.02f) {
                        if (noise((wx * 3 + wy).toInt()) > 0.35f) drawRect(look.farLight.copy(alpha = 0.7f), Offset(wx, wy), Size(win * 0.7f, win * 0.8f))
                        wx += win * 1.4f
                    }
                    wy += win * 1.6f
                }
                x += bw
                k++
            }
        }
    }
    val ground = layout.y(0f, camera)
    if (ground < h) {
        drawRect(Brush.verticalGradient(listOf(look.groundLight, look.ground), ground, ground + layout.piece * 2f), Offset(0f, ground), Size(w, h - ground))
        drawRect(look.groundShade.copy(alpha = 0.5f), Offset(0f, ground), Size(w, layout.piece * 0.08f))
        for (k in 0 until 26) {
            val px = w * noise(k * 3 + 1)
            val py = ground + layout.piece * (0.3f + 1.4f * noise(k * 5 + 2))
            drawCircle(look.groundShade.copy(alpha = 0.6f), layout.piece * (0.03f + 0.05f * noise(k + 9)), Offset(px, py))
        }
        if (look.kind == StackKind.SAND) {
            // The foam line where the waves come up the sand.
            val foam = ground - layout.piece * 0.02f
            drawLine(Color.White.copy(alpha = 0.7f), Offset(0f, foam), Offset(w, foam), layout.piece * 0.1f)
        }
    }
}

/** A scaffold behind the tower on the Building Site, one floor a piece: it shows how high the stack has climbed. */
internal fun DrawScope.drawScaffold(look: StackLook, layout: StackLayout, camera: Float, floors: Int) {
    if (look.kind != StackKind.BRICKS) return
    val pole = look.holderDark.copy(alpha = 0.55f)
    val l = layout.x(0.5f - StackTower.FOUNDATION_WIDTH / 2 - 0.04f)
    val r = layout.x(0.5f + StackTower.FOUNDATION_WIDTH / 2 + 0.04f)
    val top = layout.y(layout.bottomOf(floors + 3), camera)
    val ground = layout.y(0f, camera)
    val wPole = layout.piece * 0.12f
    for (x in listOf(l, r)) drawLine(pole, Offset(x, ground), Offset(x, top), wPole)
    for (i in 1..floors + 2) {
        val y = layout.y(layout.bottomOf(i), camera)
        drawLine(pole, Offset(l, y), Offset(r, y), wPole * 0.7f)
        if (i % 2 == 1) drawLine(pole.copy(alpha = 0.3f), Offset(l, y), Offset(r, layout.y(layout.bottomOf(i + 1), camera)), wPole * 0.5f)
    }
}

/** The keepsake standing on the ground by the foundation: the little sandcastle, or the builder before he climbs. */
internal fun DrawScope.drawGroundKeepsake(look: StackLook, grade: SceneGrade, layout: StackLayout, camera: Float, t: Float, alpha: Float) {
    if (alpha <= 0.01f) return
    val s = layout.piece * 2.6f
    val left = if (look.kind == StackKind.SAND) layout.x(0.5f - StackTower.FOUNDATION_WIDTH / 2) - s * 1.02f else layout.x(0.5f + StackTower.FOUNDATION_WIDTH / 2) + s * 0.02f
    val bottom = layout.y(0f, camera) + s * 0.04f
    val unit = s / 100f
    translate(left, bottom - s) {
        scale(unit, unit, Offset.Zero) {
            drawKeepsakeFaded(alpha) { drawKeepsake(look.arena, 3, t, grade) }
        }
    }
}

private inline fun DrawScope.drawKeepsakeFaded(alpha: Float, art: DrawScope.() -> Unit) {
    if (alpha >= 0.99f) {
        art()
    } else {
        // Shrinks away rather than fading, so the art's layers never show through each other.
        scale(alpha, alpha, Offset(50f, 96f)) { art() }
    }
}

/** One piece from [l] to [r], [top] to [bottom] on screen; [seed] varies its grains or its bricks. */
internal fun DrawScope.drawBlock(look: StackLook, l: Float, top: Float, r: Float, bottom: Float, seed: Int, alpha: Float = 1f) {
    when (look.kind) {
        StackKind.SAND -> drawSandBlock(look, l, top, r, bottom, seed, alpha)
        StackKind.BRICKS -> drawBrickBlock(look, l, top, r, bottom, seed, alpha)
    }
}

/** A block of sand fresh out of the bucket: a lit face, the mold's ribs, a lip at the top and a few specks. */
private fun DrawScope.drawSandBlock(look: StackLook, l: Float, top: Float, r: Float, bottom: Float, seed: Int, alpha: Float) {
    val w = r - l
    val h = bottom - top
    if (w <= 0f || h <= 0f) return
    val corner = CornerRadius(min(h * 0.24f, w * 0.2f))
    drawRoundRect(look.shade.copy(alpha = alpha), Offset(l, top + h * 0.08f), Size(w, h * 0.92f), corner)
    drawRoundRect(
        Brush.verticalGradient(listOf(look.light.copy(alpha = alpha), look.block.copy(alpha = alpha)), top, bottom),
        Offset(l, top),
        Size(w, h * 0.88f),
        corner,
    )
    drawRoundRect(look.shade.copy(alpha = 0.4f * alpha), Offset(r - w * 0.12f, top + h * 0.04f), Size(w * 0.12f, h * 0.84f), corner)
    val ribs = max(3, (w / (h * 0.7f)).toInt())
    for (k in 1 until ribs) {
        val x = l + w * k / ribs
        drawLine(look.shade.copy(alpha = 0.45f * alpha), Offset(x, top + h * 0.26f), Offset(x, bottom - h * 0.2f), h * 0.05f, StrokeCap.Round)
    }
    drawLine(Color.White.copy(alpha = 0.4f * alpha), Offset(l + w * 0.08f, top + h * 0.12f), Offset(r - w * 0.2f, top + h * 0.12f), h * 0.08f, StrokeCap.Round)
    for (k in 0 until 4) {
        val p = Offset(l + w * (0.1f + 0.8f * noise(seed * 7 + k)), top + h * (0.3f + 0.5f * noise(seed * 11 + k * 3)))
        drawCircle(look.dark.copy(alpha = 0.45f * alpha), h * (0.03f + 0.025f * noise(seed + k)), p)
    }
}

/** A pallet of bricks: two courses in running bond on a wooden pallet, mortar showing between them. */
private fun DrawScope.drawBrickBlock(look: StackLook, l: Float, top: Float, r: Float, bottom: Float, seed: Int, alpha: Float) {
    val w = r - l
    val h = bottom - top
    if (w <= 0f || h <= 0f) return
    val pallet = h * 0.2f
    val m = h * 0.055f
    // The pallet: two boards with dark gaps and blocks between them.
    drawRoundRect(look.woodDark.copy(alpha = alpha), Offset(l, bottom - pallet), Size(w, pallet), CornerRadius(pallet * 0.25f))
    drawRect(look.wood.copy(alpha = alpha), Offset(l, bottom - pallet), Size(w, pallet * 0.38f))
    drawRect(look.wood.copy(alpha = alpha), Offset(l, bottom - pallet * 0.32f), Size(w, pallet * 0.32f))
    val blocks = max(2, (w / (h * 0.9f)).toInt())
    for (k in 0..blocks) {
        val x = l + (w - pallet * 0.8f) * k / blocks
        drawRect(look.wood.copy(alpha = alpha), Offset(x, bottom - pallet), Size(pallet * 0.8f, pallet))
    }
    // The bricks, mortar behind them.
    val wall = bottom - pallet
    drawRoundRect(look.mortar.copy(alpha = alpha), Offset(l, top), Size(w, wall - top), CornerRadius(m))
    val course = (wall - top - 3 * m) / 2
    val length = course * 2.3f
    for (row in 0 until 2) {
        val y = top + m + row * (course + m)
        val offset = ((seed + row) % 2) * (length + m) / 2
        var x = l + m - offset
        var k = 0
        while (x < r - m) {
            val bl = max(x, l + m)
            val br = min(x + length, r - m)
            if (br - bl > m) {
                val v = noise(seed * 17 + row * 5 + k)
                val face = lerp(look.block, if (v > 0.5f) look.light else look.shade, (v - 0.5f).let { it * it } * 1.6f)
                drawRoundRect(look.dark.copy(alpha = alpha), Offset(bl, y + course * 0.12f), Size(br - bl, course * 0.88f), CornerRadius(m * 0.6f))
                drawRoundRect(face.copy(alpha = alpha), Offset(bl, y), Size(br - bl, course * 0.84f), CornerRadius(m * 0.6f))
                drawRect(Color.White.copy(alpha = 0.22f * alpha), Offset(bl + m * 0.5f, y + course * 0.1f), Size((br - bl) - m, course * 0.12f))
            }
            x += length + m
            k++
        }
    }
}

/** The tower: every piece from the foundation up, with the camera risen by [camera]. */
internal fun DrawScope.drawTower(look: StackLook, layout: StackLayout, tower: StackTower, camera: Float, landedAt: Float, now: Float) {
    // A soft shadow where the foundation meets the ground.
    val f = tower.pieces[0]
    val ground = layout.y(0f, camera)
    drawOval(Color.Black.copy(alpha = 0.18f), Offset(layout.x(f.left) - layout.piece * 0.3f, ground - layout.piece * 0.18f), Size(f.width * layout.span + layout.piece * 0.6f, layout.piece * 0.36f))
    tower.pieces.forEachIndexed { i, p ->
        var top = layout.y(layout.bottomOf(i) + layout.heightOf(i), camera)
        val bottom = layout.y(layout.bottomOf(i), camera)
        // The newest piece squashes a touch as it lands.
        if (i == tower.pieces.lastIndex && i > 0) {
            val a = ((now - landedAt) / SQUASH_S).coerceIn(0f, 1f)
            top += (bottom - top) * 0.12f * sin(a * PI.toFloat())
        }
        drawBlock(look, layout.x(p.left), top, layout.x(p.right), bottom, i)
    }
}

/**
 * What holds the swinging piece, at [x] (screen) with its top at [top]: an upturned beach bucket on a rope from the
 * sky, or the crane's hook on a cable from the trolley on the jib above. [width] is the piece's width in pixels; the
 * piece itself is drawn by the caller, [loaded] says whether there is one.
 */
internal fun DrawScope.drawHolder(look: StackLook, layout: StackLayout, x: Float, top: Float, width: Float, loaded: Boolean) {
    val ph = layout.piece
    val anchorX = size.width / 2 + (x - size.width / 2) * if (look.kind == StackKind.SAND) 0.35f else 0.8f
    when (look.kind) {
        StackKind.SAND -> {
            // The bucket upside down over the sand, its rim at the block's top, a rope tied to its handle.
            val rimW = width * 1.08f + ph * 0.2f
            val baseW = rimW * 0.78f
            val bh = ph * 1.05f
            val rim = top + ph * 0.18f
            val handleTop = rim - bh - ph * 0.55f
            drawLine(look.line, Offset(anchorX, 0f), Offset(x, handleTop), ph * 0.07f, StrokeCap.Round)
            drawArc(look.holderDark, 200f, 140f, false, Offset(x - rimW * 0.5f, handleTop), Size(rimW, bh * 1.5f), style = Stroke(ph * 0.08f, cap = StrokeCap.Round))
            val body = Path().apply {
                moveTo(x - baseW / 2, rim - bh)
                lineTo(x + baseW / 2, rim - bh)
                lineTo(x + rimW / 2, rim)
                lineTo(x - rimW / 2, rim)
                close()
            }
            drawPath(body, Brush.horizontalGradient(listOf(look.holderLight, look.holder, look.holderDark), x - rimW / 2, x + rimW / 2))
            drawRoundRect(look.holderDark, Offset(x - rimW / 2 - ph * 0.06f, rim - ph * 0.22f), Size(rimW + ph * 0.12f, ph * 0.26f), CornerRadius(ph * 0.1f))
            drawRoundRect(look.holderDark, Offset(x - baseW / 2, rim - bh - ph * 0.04f), Size(baseW, ph * 0.12f), CornerRadius(ph * 0.06f))
            drawLine(Color.White.copy(alpha = 0.45f), Offset(x - baseW * 0.3f, rim - bh * 0.8f), Offset(x - rimW * 0.32f, rim - bh * 0.25f), ph * 0.09f, StrokeCap.Round)
            if (!loaded) {
                // Inside the empty bucket, a shadow where the sand was.
                drawRect(Color.Black.copy(alpha = 0.18f), Offset(x - rimW / 2 + ph * 0.1f, rim - ph * 0.08f), Size(rimW - ph * 0.2f, ph * 0.08f))
            }
        }
        StackKind.BRICKS -> {
            val hookY = top - ph * 1.25f
            val jib = jibY(layout)
            drawLine(look.line, Offset(anchorX - ph * 0.1f, jib + ph * 0.3f), Offset(x - ph * 0.08f, hookY - ph * 0.3f), ph * 0.06f)
            drawLine(look.line, Offset(anchorX + ph * 0.1f, jib + ph * 0.3f), Offset(x + ph * 0.08f, hookY - ph * 0.3f), ph * 0.06f)
            // The trolley riding the jib.
            drawRoundRect(look.holderDark, Offset(anchorX - ph * 0.45f, jib - ph * 0.05f), Size(ph * 0.9f, ph * 0.4f), CornerRadius(ph * 0.1f))
            drawCircle(look.line, ph * 0.1f, Offset(anchorX - ph * 0.25f, jib))
            drawCircle(look.line, ph * 0.1f, Offset(anchorX + ph * 0.25f, jib))
            // The hook block and its hook.
            drawRoundRect(look.holderDark, Offset(x - ph * 0.34f, hookY - ph * 0.42f), Size(ph * 0.68f, ph * 0.52f), CornerRadius(ph * 0.14f))
            drawRoundRect(look.holder, Offset(x - ph * 0.3f, hookY - ph * 0.44f), Size(ph * 0.6f, ph * 0.44f), CornerRadius(ph * 0.12f))
            drawRect(look.line.copy(alpha = 0.7f), Offset(x - ph * 0.3f, hookY - ph * 0.2f), Size(ph * 0.6f, ph * 0.08f))
            val hook = Path().apply {
                moveTo(x, hookY + ph * 0.08f)
                lineTo(x, hookY + ph * 0.32f)
                quadraticBezierTo(x, hookY + ph * 0.55f, x + ph * 0.2f, hookY + ph * 0.5f)
                quadraticBezierTo(x + ph * 0.32f, hookY + ph * 0.42f, x + ph * 0.26f, hookY + ph * 0.3f)
            }
            drawPath(hook, look.line, style = Stroke(ph * 0.1f, cap = StrokeCap.Round))
            if (loaded) {
                // Two straps from the hook down to the pallet's corners.
                val strap = look.flag
                val ring = Offset(x + ph * 0.08f, hookY + ph * 0.5f)
                val inset = width * 0.12f
                drawLine(strap, ring, Offset(x - width / 2 + inset, top + ph * 0.06f), ph * 0.09f, StrokeCap.Round)
                drawLine(strap, ring, Offset(x + width / 2 - inset, top + ph * 0.06f), ph * 0.09f, StrokeCap.Round)
            }
        }
    }
}

/** Where the crane's jib runs across the top. */
private fun jibY(layout: StackLayout): Float = layout.hangTop * 0.22f

/** The crane's jib on the Building Site: a yellow lattice truss across the top of the play area. */
internal fun DrawScope.drawJib(look: StackLook, layout: StackLayout) {
    if (look.kind != StackKind.BRICKS) return
    val ph = layout.piece
    val y = jibY(layout)
    val hgt = ph * 0.7f
    val w = size.width
    drawRect(Color.Black.copy(alpha = 0.12f), Offset(0f, y - hgt + ph * 0.12f), Size(w, hgt))
    drawRect(look.holderDark, Offset(0f, y - ph * 0.05f), Size(w, ph * 0.14f))
    drawRect(look.holder, Offset(0f, y - hgt), Size(w, ph * 0.14f))
    val step = hgt * 1.1f
    var x = -step * 0.5f
    while (x < w) {
        drawLine(look.holder, Offset(x, y), Offset(x + step / 2, y - hgt), ph * 0.09f)
        drawLine(look.holder, Offset(x + step / 2, y - hgt), Offset(x + step, y), ph * 0.09f)
        x += step
    }
    drawRect(look.holder, Offset(0f, y - ph * 0.08f), Size(w, ph * 0.12f))
    drawRect(look.holderLight.copy(alpha = 0.7f), Offset(0f, y - hgt), Size(w, ph * 0.05f))
}

/** Overhang crumbling away [age] seconds after it was cut: sand trickling down, or brick chips tumbling. */
internal fun DrawScope.drawCrumble(look: StackLook, layout: StackLayout, c: Crumble, camera: Float, age: Float) {
    if (age < 0f || age > CRUMBLE_S) return
    val ph = layout.piece
    val l = layout.x(c.cut.left)
    val r = layout.x(c.cut.right)
    val top0 = layout.y(c.bottom + c.height, camera)
    val bottom0 = layout.y(c.bottom, camera)
    val side = if (c.cut.center < 0.5f) -1f else 1f
    val fall = GRAVITY * ph * age * age
    val fade = (1f - age / CRUMBLE_S).coerceIn(0f, 1f)
    when (look.kind) {
        StackKind.SAND -> {
            // The lump sags and softens away while its sand trickles down in a fan.
            val lump = (1f - age / 0.35f).coerceIn(0f, 1f)
            if (lump > 0f) {
                rotate(side * 18f * (1f - lump), Offset(if (side < 0) r else l, bottom0)) {
                    drawBlock(look, l, top0 + fall * 0.6f, r, bottom0 + fall * 0.6f, c.seed, lump)
                }
            }
            val n = ((r - l) / (ph * 0.1f)).toInt().coerceIn(8, 36)
            for (k in 0 until n) {
                val u = noise(c.seed * 31 + k)
                val v = noise(c.seed * 17 + k * 7)
                val delay = v * 0.25f
                val a = age - delay
                if (a < 0f) continue
                val x = l + (r - l) * u + side * ph * (0.4f + 1.4f * v) * a
                val y = top0 + (bottom0 - top0) * (0.2f + 0.8f * v) + GRAVITY * ph * a * a
                val color = when (k % 3) {
                    0 -> look.light
                    1 -> look.block
                    else -> look.shade
                }
                drawCircle(color.copy(alpha = fade), ph * (0.05f + 0.05f * u), Offset(x, y))
            }
        }
        StackKind.BRICKS -> {
            val n = ((r - l) / (ph * 0.45f)).toInt().coerceIn(2, 7)
            val chipW = ((r - l) / n).coerceAtMost(ph * 0.7f)
            for (k in 0 until n) {
                val v = noise(c.seed * 13 + k * 5)
                val x = l + (r - l) * (k + 0.5f) / n + side * ph * (0.6f + 1.2f * v) * age
                val y = (top0 + bottom0) / 2 + (v - 0.5f) * (bottom0 - top0) * 0.6f + fall * (0.8f + 0.4f * v)
                rotate(side * (120f + 240f * v) * age, Offset(x, y)) {
                    val cw = chipW * (0.6f + 0.3f * v)
                    val ch = ph * (0.22f + 0.14f * v)
                    drawRoundRect(look.dark.copy(alpha = fade), Offset(x - cw / 2, y - ch / 2 + ch * 0.12f), Size(cw, ch), CornerRadius(ch * 0.25f))
                    drawRoundRect(look.block.copy(alpha = fade), Offset(x - cw / 2, y - ch / 2), Size(cw, ch * 0.86f), CornerRadius(ch * 0.25f))
                }
                // A puff of mortar dust.
                drawCircle(look.mortar.copy(alpha = 0.5f * fade), ph * (0.08f + 0.2f * age), Offset(x - side * ph * 0.3f, y - ph * 0.1f))
            }
        }
    }
}

/** A ring of sparkles and a glow over a perfect drop at [c], as [b] goes from 0 to 1. */
internal fun DrawScope.drawPerfect(c: Offset, ph: Float, b: Float) {
    if (b <= 0f || b >= 1f) return
    drawGlow(c, ph * (1.2f + 2.2f * b), Color(0xFFFFF2B0).copy(alpha = 0.85f * (1f - b)))
    sparkleBurst(c, ph * 2.6f, b)
}

/**
 * The finish on top of the tower, [f] from 0 to 1: crenels and a flag going up on the sandcastle, or the builder
 * popping up on the top floor to wave. [top] is the screen position of the middle of the tower's top.
 */
internal fun DrawScope.drawTopper(look: StackLook, grade: SceneGrade, layout: StackLayout, top: Offset, width: Float, f: Float, t: Float) {
    if (f <= 0f) return
    val ph = layout.piece
    when (look.kind) {
        StackKind.SAND -> {
            // Crenels pop up along the top, then the flag climbs its pole.
            val crenel = (f / 0.4f).coerceIn(0f, 1f)
            val cw = width / 5
            for (k in 0..2) {
                val l = top.x - width / 2 + k * 2 * cw
                val hgt = ph * 0.55f * crenel
                drawRoundRect(look.shade, Offset(l, top.y - hgt), Size(cw, hgt + ph * 0.1f), CornerRadius(ph * 0.1f))
                drawRoundRect(look.light, Offset(l, top.y - hgt), Size(cw * 0.82f, hgt + ph * 0.06f), CornerRadius(ph * 0.1f))
            }
            val rise = ((f - 0.3f) / 0.7f).coerceIn(0f, 1f)
            if (rise > 0f) {
                val poleTop = top.y - ph * (0.5f + 2.4f * rise)
                drawLine(look.dark, Offset(top.x, top.y), Offset(top.x, poleTop), ph * 0.09f, StrokeCap.Round)
                drawCircle(look.holderLight, ph * 0.1f, Offset(top.x, poleTop))
                val wave = swing(t, 50) * 0.2f
                val flag = Path().apply {
                    moveTo(top.x, poleTop + ph * 0.1f)
                    quadraticBezierTo(top.x + ph * 0.6f, poleTop + ph * (0.1f + wave), top.x + ph * 1.2f, poleTop + ph * 0.42f)
                    quadraticBezierTo(top.x + ph * 0.6f, poleTop + ph * (0.6f - wave), top.x, poleTop + ph * 0.8f)
                    close()
                }
                drawPath(flag, look.flag)
                drawPath(flag, Color.White.copy(alpha = 0.2f), style = Stroke(ph * 0.05f))
            }
        }
        StackKind.BRICKS -> {
            val s = ph * 3f
            val pop = (f / 0.5f).coerceIn(0f, 1f)
            val bounce = pop + sin(pop * PI.toFloat()) * 0.15f
            val unit = s * bounce / 100f
            translate(top.x - 50f * unit, top.y - 96f * unit) {
                scale(unit, unit, Offset.Zero) { drawKeepsake(Arena.BUILDING_SITE, 3, t, grade) }
            }
        }
    }
}

/** A gentle hint under the swinging piece: a dotted line down to the tower, lit when it is right over the middle. */
internal fun DrawScope.drawAim(x: Float, from: Float, to: Float, ph: Float, centered: Boolean) {
    if (to <= from) return
    val color = if (centered) Color(0xFFFFF2B0).copy(alpha = 0.95f) else Color.White.copy(alpha = 0.45f)
    val step = ph * 0.45f
    var y = from + step * 0.5f
    while (y < to) {
        drawCircle(color, ph * if (centered) 0.08f else 0.055f, Offset(x, y))
        y += step
    }
}

/** How long a cut-off bit takes to crumble away, in seconds. */
internal const val CRUMBLE_S = 1.3f

/** How long the newest piece squashes as it lands. */
internal const val SQUASH_S = 0.22f

/** How fast crumbs fall, in piece heights per second squared. */
private const val GRAVITY = 14f

/** A smooth step from 0 to 1 as [x] goes from 0 to 1. */
internal fun stackEase(x: Float): Float {
    val c = x.coerceIn(0f, 1f)
    return c * c * (3 - 2 * c)
}
