/**
 * The picker's page for the Custom palette: the color wheel, the harmony to keep, and a way back. [onChange]
 * gets every step of a drag with `save = false` and the final scheme with `save = true`.
 */
@Composable
fun CustomColorsEditor(
    scheme: CustomScheme,
    compact: Boolean,
    onChange: (scheme: CustomScheme, save: Boolean) -> Unit,
    onBack: () -> Unit,
    onDone: () -> Unit,
) {
    val palette = LocalPalette.current
    // Done sits up here so the card stays short and more of the board shows above it.
    val title = @Composable {
        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
            TextButton(onClick = onBack, contentPadding = PaddingValues(horizontal = 8.dp)) { Text("\u2039 All", fontSize = 15.sp) }
            Text("Custom", fontSize = 20.sp, fontWeight = FontWeight.Bold, color = palette.accent)
            Spacer(Modifier.weight(1f))
            Button(onClick = onDone) { Text("Done") }
        }
    }
    val chips = @Composable {
        for (harmony in Harmony.entries) {
            HarmonyChip(harmony, isCurrent = harmony == scheme.harmony) {
                onChange(scheme.copy(harmony = harmony), true)
            }
        }
    }
    val controls = @Composable {
        Text(
            "Drag a dot: the others turn along. Toward the rim is more vivid, toward the middle calmer.",
            color = palette.dimText,
            fontSize = 12.sp,
            lineHeight = 16.sp,
        )
        // Beside the wheel there is only room for the chips one under another.
        if (compact) {
            Column(verticalArrangement = Arrangement.spacedBy(6.dp)) { chips() }
        } else {
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) { chips() }
        }
    }
    if (compact) {
        // Short windows (landscape phones): the wheel beside the controls, so it all fits without much scrolling.
        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
            title()
            Row(horizontalArrangement = Arrangement.spacedBy(16.dp), verticalAlignment = Alignment.CenterVertically) {
                ColorWheel(scheme, onChange, Modifier.size(200.dp))
                Column(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(10.dp)) { controls() }
            }
        }
    } else {
        Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
            title()
            BoxWithConstraints(Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) {
                ColorWheel(scheme, onChange, Modifier.size(minOf(maxWidth, WHEEL_SIZE)))
            }
            controls()
        }
    }
}

private val WHEEL_SIZE: Dp = 216.dp

@Composable
private fun HarmonyChip(harmony: Harmony, isCurrent: Boolean, onClick: () -> Unit) {
    val palette = LocalPalette.current
    Surface(
        onClick = onClick,
        modifier = Modifier.semantics { selected = isCurrent },
        shape = RoundedCornerShape(50),
        color = if (isCurrent) palette.accent else palette.surface,
        contentColor = if (isCurrent) palette.onAccent else palette.text,
        border = BorderStroke(1.dp, if (isCurrent) palette.accent else palette.glassOutline),
    ) {
        Row(Modifier.padding(horizontal = 12.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {
            HarmonyIcon(harmony, if (isCurrent) palette.onAccent else palette.text)
            Spacer(Modifier.width(6.dp))
            Text(harmony.label, fontSize = 14.sp)
        }
    }
}

/** A tiny circle with the harmony's nine hue positions as dots. */
@Composable
private fun HarmonyIcon(harmony: Harmony, color: Color) {
    Canvas(Modifier.size(16.dp)) {
        val r = size.minDimension / 2
        drawCircle(color.copy(alpha = 0.35f), r - 1.dp.toPx(), style = Stroke(1.dp.toPx()))
        for (offset in harmony.offsets) {
            val a = (offset - 90f) * PI / 180
            drawCircle(color, 1.6.dp.toPx(), center + Offset((cos(a) * (r - 1.dp.toPx())).toFloat(), (sin(a) * (r - 1.dp.toPx())).toFloat()))
        }
    }
}

/**
 * Where things sit on a wheel of [size]: hue runs clockwise with hue 0 at 12 o'clock, saturation runs from
 * the inner edge of the ring ([inner]) to its outer edge ([outer]), and the neutral sands live in the hub.
 */
internal class WheelGeometry(size: Size, dotRadius: Float) {
    val center = Offset(size.width / 2, size.height / 2)
    val outer = size.minDimension / 2 - dotRadius - 2f
    val inner = outer * 0.6f
    val hub = outer * 0.36f

    fun position(hue: Float, saturation: Float): Offset {
        val a = (hue - 90f) * PI / 180
        val r = inner + saturation * (outer - inner)
        return center + Offset((cos(a) * r).toFloat(), (sin(a) * r).toFloat())
    }

    fun hueAt(p: Offset): Float = (atan2(p.y - center.y, p.x - center.x) * 180 / PI).toFloat() + 90f

    fun radiusAt(p: Offset): Float = ((distance(p) - inner) / (outer - inner)).coerceIn(0f, 1f)

    fun distance(p: Offset): Float = hypot(p.x - center.x, p.y - center.y)

    /** The dot nearest to [p], or null when [p] is in the hub (where nothing can be dragged). */
    fun nearestSlot(scheme: CustomScheme, p: Offset): Int? {
        if (distance(p) < hub) return null
        val s = scheme.saturation / 100f
        return CustomScheme.CHROMATIC.indices.minByOrNull { (position(scheme.hueOf(it), s) - p).getDistance() }
    }
}

/**
 * One drag of the dot in [slot], starting from [start]. It remembers the last scheme it produced, so the scheme
 * saved on release is the one the pointer last showed, even if the screen hasn't recomposed with it yet.
 */
internal class WheelDrag(start: CustomScheme, private val slot: Int) {
    var current: CustomScheme = start
        private set

    fun moveTo(angle: Float, radius: Float): CustomScheme = current.drag(slot, angle, radius).also { current = it }
}

/** Holder for the wheel's newest scheme; see [ColorWheel]. */
private class WheelLatest(var scheme: CustomScheme)

/** Arrow-key and screen-reader steps on the wheel. */
private const val HUE_STEP = 10
private const val SATURATION_STEP = 10

/**
 * The color wheel. Every colorful sand is a dot at its hue and the shared saturation; pressing anywhere on the
 * ring picks up the nearest dot, and moving it turns the whole harmony (see [CustomScheme.drag]). Lines join
 * the sands of equal lightness, which always form triangles, so the harmony's shape is visible at a glance.
 */
@Composable
private fun ColorWheel(scheme: CustomScheme, onChange: (CustomScheme, Boolean) -> Unit, modifier: Modifier) {
    val palette = LocalPalette.current
    val colors = remember(scheme) { scheme.palette() }
    // The newest scheme this wheel has seen: what it last reported, or what came back in through [scheme].
    // Gestures and key presses build on it rather than on [scheme], which only catches up on recomposition,
    // so quick key presses or a release right after a move never start from a stale value.
    val latest = remember { WheelLatest(scheme) }
    SideEffect { latest.scheme = scheme }
    val report by rememberUpdatedState(onChange)
    var held by remember { mutableIntStateOf(-1) }
    // The rim's hues, a little lighter than the sand so the dots stand out on it.
    val rim = remember { List(37) { oklch(0.78f, 0.16f, it * 10f) } }
    var focused by remember { mutableStateOf(false) }
    val focus = remember { FocusRequester() }
    // Keyboard and screen readers step the same scheme the dots show and save each step at once.
    fun step(hueBy: Int = 0, saturationBy: Int = 0): Boolean {
        val next = latest.scheme.nudge(hueBy, saturationBy)
        latest.scheme = next
        report(next, true)
        return true
    }
    Canvas(
        modifier
            .semantics {
                contentDescription = "Color wheel"
                stateDescription = "${scheme.harmony.label}, hue ${scheme.hue} degrees, saturation ${scheme.saturation} percent"
                customActions = listOf(
                    CustomAccessibilityAction("Turn colors left") { step(hueBy = -HUE_STEP) },
                    CustomAccessibilityAction("Turn colors right") { step(hueBy = HUE_STEP) },
                    CustomAccessibilityAction("More vivid") { step(saturationBy = SATURATION_STEP) },
                    CustomAccessibilityAction("Calmer") { step(saturationBy = -SATURATION_STEP) },
                )
            }
            .focusRequester(focus)
            .onFocusChanged { focused = it.isFocused }
            .onKeyEvent {
                if (it.type != KeyEventType.KeyDown) return@onKeyEvent false
                when (it.key) {
                    Key.DirectionLeft -> step(hueBy = -HUE_STEP)
                    Key.DirectionRight -> step(hueBy = HUE_STEP)
                    Key.DirectionUp -> step(saturationBy = SATURATION_STEP)
                    Key.DirectionDown -> step(saturationBy = -SATURATION_STEP)
                    else -> false
                }
            }
            .focusable()
            .pointerInput(Unit) {
                val dot = DOT_RADIUS.toPx()
                awaitEachGesture {
                    val down = awaitFirstDown(requireUnconsumed = false)
                    val geo = WheelGeometry(Size(size.width.toFloat(), size.height.toFloat()), dot)
                    if (geo.distance(down.position) > geo.outer + dot * 2) return@awaitEachGesture
                    val slot = geo.nearestSlot(latest.scheme, down.position) ?: return@awaitEachGesture
                    down.consume()
                    // Grabbing a dot also lets the arrow keys take over from there.
                    focus.requestFocus()
                    held = slot
                    val drag = WheelDrag(latest.scheme, slot)
                    fun follow(p: Offset) {
                        latest.scheme = drag.moveTo(geo.hueAt(p), geo.radiusAt(p))
                        report(latest.scheme, false)
                    }
                    follow(down.position)
                    while (true) {
                        val change = awaitPointerEvent().changes.firstOrNull { it.id == down.id } ?: break
                        if (!change.pressed) break
                        if (change.positionChanged()) {
                            change.consume()
                            follow(change.position)
                        }
                    }
                    held = -1
                    report(drag.current, true)
                }
            },
    ) {
        val dot = DOT_RADIUS.toPx()
        val geo = WheelGeometry(size, dot)
        // Ring: hue around, washed toward gray on the inside.
        val ringWidth = geo.outer - geo.inner + dot * 1.4f
        val ringMid = (geo.outer + geo.inner) / 2
        drawCircle(
            Brush.sweepGradient(rim.indices.map { rim[(it + 9) % 36] }, geo.center),
            radius = ringMid,
            center = geo.center,
            style = Stroke(ringWidth),
        )
        drawCircle(
            Brush.radialGradient(
                0f to palette.surface,
                (geo.inner - dot * 0.7f) / (geo.outer + dot * 0.7f) to palette.surface.copy(alpha = 0.7f),
                1f to Color.Transparent,
                center = geo.center,
                radius = geo.outer + dot * 0.7f,
            ),
            radius = ringMid,
            center = geo.center,
            style = Stroke(ringWidth),
        )
        val s = scheme.saturation / 100f
        val guide = palette.text.copy(alpha = 0.35f)
        drawCircle(guide, geo.inner + s * (geo.outer - geo.inner), geo.center, style = Stroke(1.dp.toPx()))
        val points = CustomScheme.CHROMATIC.indices.map { geo.position(scheme.hueOf(it), s) }
        for (step in 0 until 3) {
            val triangle = Path().apply {
                moveTo(points[step].x, points[step].y)
                lineTo(points[step + 3].x, points[step + 3].y)
                lineTo(points[step + 6].x, points[step + 6].y)
                close()
            }
            drawPath(triangle, palette.text.copy(alpha = 0.22f), style = Stroke(1.5.dp.toPx()))
        }
        // Hub with the three neutrals, which follow along with only a faint tint.
        drawCircle(palette.surface, geo.hub, geo.center)
        drawCircle(palette.glassOutline, geo.hub, geo.center, style = Stroke(1.dp.toPx()))
        val neutrals = listOf(SandColor.BROWN, SandColor.GRAY, SandColor.WHITE)
        val small = geo.hub * 0.24f
        neutrals.forEachIndexed { i, sand ->
            val c = geo.center + Offset((i - 1) * small * 2.5f, 0f)
            drawCircle(colors.sand(sand), small, c)
            drawCircle(palette.glassOutline, small, c, style = Stroke(1.dp.toPx()))
        }
        if (focused) drawCircle(palette.highlight, geo.outer + dot * 0.7f + 3.dp.toPx(), geo.center, style = Stroke(2.dp.toPx()))
        // The dots, the held one drawn last and a little bigger.
        val order = CustomScheme.CHROMATIC.indices.sortedBy { it == held }
        for (slot in order) {
            val r = if (slot == held) dot * 1.25f else dot
            drawCircle(palette.surface, r + 3.dp.toPx(), points[slot])
            drawCircle(colors.sand(CustomScheme.CHROMATIC[slot]), r, points[slot])
            if (slot == held) drawCircle(palette.selected, r + 3.dp.toPx(), points[slot], style = Stroke(2.dp.toPx()))
        }
    }
}

private val DOT_RADIUS = 13.dp
