/**
 * Stack the castle: a calm stacker. A piece swings gently over the tower (a block of sand in an upturned bucket on
 * the Beach, a pallet of bricks on the crane's hook on the Building Site); tap and it drops. Whatever hangs over the
 * edge crumbles away, but the next piece never comes in narrower than a minimum, so there is no failing (see
 * [StackTower]). A perfect drop sparkles and widens the next piece a little. The camera rises with the tower; after
 * ten pieces a flag goes up on the sandcastle, or the builder waves from the top floor, and the round calls
 * [onFinished]. Enter, Space or a screen reader's tap drop the piece; "Drop when centered" waits for the moment it
 * is right over the middle. [seed] picks where the swing starts.
 */
@Composable
fun StackGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { StackLook.of(arena, grade) }
    val swing = remember(seed) { StackSwing.of(seed) }
    val sim = remember(seed) { StackMotion() }
    var tower by remember(seed) { mutableStateOf(StackTower()) }
    var status by remember(seed) { mutableStateOf(StackStatus.START) }
    var helper by remember(seed) { mutableStateOf(false) }
    var frame by remember(seed) { mutableStateOf(0) }
    val clock = rememberSceneClock()
    val focus = remember { FocusRequester() }
    // Keys go to the game straight away, so Enter and Space drop without tabbing to it first.
    LaunchedEffect(focus) { runCatching { focus.requestFocus() } }

    fun drop(center: Float) {
        if (!sim.ready(tower)) return
        sim.fall = StackFall(center, tower.next, sim.time, sim.hangTopWorld(swing.lean(sim.time)))
        feedback.play(Sounds.click)
    }
    fun dropNow() = drop(swing.x(sim.time))
    fun waitForMiddle() {
        if (tower.isDone || helper) return
        helper = true
        feedback.play(Sounds.click)
    }
    fun land(fall: StackFall) {
        val landing = tower.landing(fall.center)
        val index = tower.pieces.size
        tower = tower.drop(fall.center)
        sim.fall = null
        sim.landedAt = sim.time
        sim.refillAt = sim.time
        for ((k, cut) in landing.cuts.withIndex()) sim.crumbles += Crumble(cut, sim.bottomOf(index), sim.heightOf(index), index * 7 + k, sim.time)
        feedback.play(Sounds.land)
        feedback.tick()
        if (landing.perfect) {
            sim.perfectAt = sim.time
            feedback.play(Sounds.chime(tower.perfects.coerceIn(1, 6)))
            feedback.confirm()
        }
        status = when {
            tower.isDone -> StackStatus.DONE
            landing.perfect -> StackStatus.PERFECT
            landing.cuts.isNotEmpty() -> StackStatus.TRIMMED
            else -> StackStatus.NICE
        }
        if (tower.isDone) sim.finaleAt = sim.time + FINALE_DELAY_S
    }

    LaunchedEffect(sim) {
        var last = -1L
        var finished = false
        while (true) {
            withFrameNanos { now ->
                val dt = if (last < 0) 0f else ((now - last) / 1_000_000_000f).coerceAtMost(0.25f)
                last = now
                sim.time += dt
                val x = swing.x(sim.time)
                if (helper && sim.ready(tower) && StackSwing.passes(sim.lastX, x, tower.top.center)) {
                    helper = false
                    drop(tower.top.center)
                }
                sim.lastX = x
                sim.fall?.let { if (sim.time - it.start >= FALL_S) land(it) }
                sim.crumbles.removeAll { sim.time - it.born > CRUMBLE_S }
                sim.follow(tower, dt)
                val finale = sim.finaleAt
                if (finale != null && !sim.chimedFinale && sim.time >= finale) {
                    sim.chimedFinale = true
                    feedback.play(Sounds.chime(6))
                }
                if (!finished && finale != null && sim.time - finale >= TOPPER_S + FINISH_HOLD_S) {
                    finished = true
                    onFinished()
                }
                frame++
            }
        }
    }

    val counter = "${tower.placed}/${tower.goal}"
    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        Canvas(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .clip(RoundedCornerShape(28.dp))
                .semantics {
                    contentDescription = "A ${look.piece} swinging over the tower"
                    stateDescription = "${tower.placed} of ${tower.goal} stacked" + if (helper) ", waiting for the middle" else ""
                    onClick(label = DROP) { dropNow(); true }
                    customActions = listOf(
                        CustomAccessibilityAction(DROP) { dropNow(); true },
                        CustomAccessibilityAction(DROP_CENTERED) { waitForMiddle(); true },
                    )
                }
                .onKeyEvent { event ->
                    val press = event.key == Key.Enter || event.key == Key.Spacebar || event.key == Key.NumPadEnter
                    if (press && event.type == KeyEventType.KeyDown) dropNow()
                    press
                }
                .focusRequester(focus)
                .focusable()
                .pointerInput(sim) {
                    detectTapGestures(onPress = { dropNow() })
                },
        ) {
            if (frame < 0) return@Canvas
            val layout = StackLayout(size.width, size.height)
            sim.layout = layout
            drawStack(look, grade, layout, sim, swing, tower, clock.value)
        }
        Spacer(Modifier.height(10.dp))
        Row(
            Modifier
                .widthIn(max = 460.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Text(
                if (helper && !tower.isDone) "Waiting for the middle…" else status.text(look),
                color = palette.text,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center,
                maxLines = 1,
                modifier = Modifier.weight(1f, fill = false).semantics { liveRegion = LiveRegionMode.Polite },
            )
            Text(counter, color = palette.accent, fontSize = 16.sp, fontWeight = FontWeight.Black, maxLines = 1)
        }
        Spacer(Modifier.height(10.dp))
        val style = if (helper) ButtonStyle.accent(palette) else ButtonStyle.bright(palette)
        GameButton(
            onClick = ::waitForMiddle,
            style = style,
            enabled = !tower.isDone,
            lip = 4.dp,
            label = if (helper) "Waiting for the middle" else DROP_CENTERED,
            modifier = Modifier.size(width = 230.dp, height = 46.dp),
        ) {
            Text(
                if (helper) "Waiting…" else DROP_CENTERED,
                color = style.content,
                fontSize = 17.sp,
                fontWeight = FontWeight.ExtraBold,
                modifier = Modifier.align(Alignment.Center).clearAndSetSemantics { },
            )
        }
    }
}

/** A piece on its way down: dropped at [center], [width] wide, at round time [start], from world height [from]. */
private class StackFall(val center: Float, val width: Float, val start: Float, val from: Float)

/** The moving parts of a round that change every frame: the clock, the falling piece, the crumbs and the camera. */
private class StackMotion {
    var time = 0f
    var lastX = 0.5f
    var fall: StackFall? = null
    var landedAt = -10f
    var refillAt = -10f
    var perfectAt = -10f
    var finaleAt: Float? = null
    var chimedFinale = false
    var camera = 0f
    val crumbles = mutableListOf<Crumble>()

    /** The last layout drawn: where the pieces hang and land. Null before the first frame. */
    var layout: StackLayout? = null

    /** Whether a new piece can drop: none is falling, the next one is in place, and the tower isn't finished. */
    fun ready(tower: StackTower): Boolean =
        layout != null && fall == null && !tower.isDone && time - refillAt >= REFILL_S

    /** How far along bringing in the next piece is, 0 to 1. */
    fun refill(): Float = ((time - refillAt) / REFILL_S).coerceIn(0f, 1f)

    /** The world height of the swinging piece's top while it leans by [lean] (see [hangTop]). */
    fun hangTopWorld(lean: Float): Float = layout?.let { it.groundY + camera - hangTop(it, hang, lean) } ?: 0f

    /** Where the swinging piece hangs on screen, easing along as the tower grows. */
    var hang = Float.NaN

    fun bottomOf(index: Int): Float = layout?.bottomOf(index) ?: 0f
    fun heightOf(index: Int): Float = layout?.heightOf(index) ?: 0f

    /** Eases the camera toward keeping the tower's top in view (and room for what goes on top at the end). */
    fun follow(tower: StackTower, dt: Float) {
        val l = layout ?: return
        val top = l.bottomOf(tower.pieces.size)
        val target = if (tower.isDone) l.cameraFor(top + l.piece * 2.2f, l.height * 0.5f) else l.cameraFor(top)
        camera += (target - camera) * (dt * 2.6f).coerceAtMost(1f)
        val over = l.hangOver(l.y(top, camera))
        hang = if (hang.isNaN()) over else hang + (over - hang) * (dt * 3f).coerceAtMost(1f)
    }
}

/** The whole round at this frame. */
private fun DrawScope.drawStack(
    look: StackLook,
    grade: SceneGrade,
    layout: StackLayout,
    sim: StackMotion,
    swing: StackSwing,
    tower: StackTower,
    t: Float,
) {
    val now = sim.time
    val camera = sim.camera
    val ph = layout.piece
    val finale = sim.finaleAt?.let { ((now - it) / TOPPER_S).coerceIn(0f, 1f) } ?: 0f
    drawStackScenery(look, layout, camera, t)
    drawScaffold(look, layout, camera, tower.placed)
    drawGroundKeepsake(look, grade, layout, camera, t, if (look.kind == StackKind.BRICKS) 1f - (finale * 3f).coerceAtMost(1f) else 1f)
    drawTower(look, layout, tower, camera, sim.landedAt, now)
    for (c in sim.crumbles) drawCrumble(look, layout, c, camera, now - c.born)
    val topIndex = tower.pieces.lastIndex
    val topY = layout.y(layout.bottomOf(topIndex) + layout.heightOf(topIndex), camera)
    drawTopper(look, grade, layout, Offset(layout.x(tower.top.center), topY), tower.top.width * layout.span, finale, t)
    drawPerfect(Offset(layout.x(tower.top.center), topY), ph, (now - sim.perfectAt) / 0.8f)

    // The piece on its way down.
    sim.fall?.let { f ->
        val a = ((now - f.start) / FALL_S).coerceIn(0f, 1f)
        val endTop = layout.bottomOf(tower.pieces.size) + ph
        val worldTop = f.from + (endTop - f.from) * a * a
        val top = layout.y(worldTop, camera)
        drawBlock(look, layout.x(f.center - f.width / 2), top, layout.x(f.center + f.width / 2), top + ph, tower.pieces.size)
    }

    // What holds the next piece, swinging; it lifts away once the tower is done.
    val lean = swing.lean(now)
    val x = layout.x(swing.x(now))
    val away = stackEase(finale * 1.4f) * layout.height * 0.6f
    var hang = hangTop(layout, sim.hang, lean) - away
    val refill = sim.refill()
    val loaded = sim.fall == null && !tower.isDone
    var grow = 1f
    if (look.kind == StackKind.BRICKS) {
        // The empty hook goes up out of view and comes back down with the next pallet.
        val lift = if (refill < 0.5f) stackEase(refill * 2f) else stackEase((1f - refill) * 2f)
        if (refill < 1f) hang -= lift * (hang + ph * 2f)
    } else {
        grow = stackEase((refill - 0.15f) / 0.85f)
    }
    val showPiece = loaded && (look.kind == StackKind.SAND || refill >= 0.5f)
    val width = tower.next * layout.span
    if (showPiece && sim.ready(tower)) {
        drawAim(x, hang + ph, topY - ph * 0.2f, ph, tower.isCentered(swing.x(now)))
    }
    drawJib(look, layout)
    if (showPiece && grow > 0f) {
        drawBlock(look, x - width / 2, hang, x + width / 2, hang + ph * grow, tower.pieces.size)
    }
    drawHolder(look, layout, x, hang, width, showPiece && grow > 0.5f)
    // A thin white rim on the play area, like the other games' panels.
    drawRoundRect(Color.White.copy(alpha = 0.5f), style = Stroke(1.5.dp.toPx()), cornerRadius = CornerRadius(28.dp.toPx()))
}

/** Where the swinging piece's top hangs on screen: a little higher at the ends of its swing, like a pendulum. */
private fun hangTop(layout: StackLayout, hang: Float, lean: Float): Float =
    (if (hang.isNaN()) layout.hangTop else hang) - layout.piece * 0.35f * lean * lean

/** What the line under the tower says after the last drop. */
private enum class StackStatus {
    START, PERFECT, TRIMMED, NICE, DONE;

    fun text(look: StackLook): String = when (this) {
        START -> look.start
        PERFECT -> look.perfect
        TRIMMED -> look.trimmed
        NICE -> "Nice and steady!"
        DONE -> look.done
    }
}

private const val DROP = "Drop"
private const val DROP_CENTERED = "Drop when centered"

/** How long a dropped piece takes to land, in seconds. */
private const val FALL_S = 0.34f

/** How long the next piece takes to come in after a drop lands. */
private const val REFILL_S = 0.7f

/** How long after the last piece lands the flag or the builder appear. */
private const val FINALE_DELAY_S = 0.5f

/** How long the flag or the builder take to go up. */
private const val TOPPER_S = 1.4f

/** How long the finished tower stands before the result card. */
private const val FINISH_HOLD_S = 1.1f
