package io.colorsand.ui.minigame

import io.colorsand.core.Arena

/** What one square of a Sand flow cross-section is. */
enum class FlowCell {
    /** Packed sand: the finger carves it open. */
    SAND,

    /** A rock: it can't be dug, and water pools around it. */
    ROCK,

    /** Carved out, or open from the start: water runs through it. */
    OPEN,

    /** Open sky over the ground: water runs through it too, but it is drawn as air. */
    AIR,

    /** The duck's tub or the oasis pool: water that runs in fills it. */
    TARGET,
}

/**
 * A hand-made Sand flow level: one string per row, top first, every row as long. `#` packed sand, `R` rock,
 * `.` open, `A` sky, `T` the target, `W` open with water in it from the start, and `S` the spring or pipe mouth
 * that keeps the water coming (open, and full at the start).
 */
class FlowLevel(val rows: List<String>) {
    init {
        require(rows.isNotEmpty() && rows.all { it.length == rows[0].length }) { "Rows must be the same length" }
        require(rows.sumOf { r -> r.count { it == 'S' } } == 1) { "A level has exactly one source" }
        require(rows.any { 'T' in it }) { "A level needs a target" }
    }

    val columns: Int get() = rows[0].length
    val height: Int get() = rows.size

    companion object {
        /** The three levels of [arena]'s Sand flow: a sandbox for the duck, a dune for the oasis elsewhere. */
        fun of(arena: Arena): List<FlowLevel> = if (arena == Arena.DESERT) dunes else sandboxes

        /** [arena]'s level for [seed]. */
        fun pick(arena: Arena, seed: Int): FlowLevel = of(arena).let { it[seed.mod(it.size)] }

        /** The Playground: the toy pipe at the top, the duck's tub at the bottom of the sandbox. */
        val sandboxes = listOf(
            FlowLevel(
                listOf(
                    "###WSW####",
                    "###WWW####",
                    "##########",
                    "##RRRR####",
                    "##########",
                    "######RR##",
                    "##########",
                    "##RRR#####",
                    "##########",
                    "##########",
                    "###TTTT###",
                    "###TTTT###",
                    "###TTTT###",
                ),
            ),
            FlowLevel(
                listOf(
                    "#WSW######",
                    "#WWW######",
                    "##########",
                    "RRRRRRR###",
                    "##########",
                    "###RRRRRRR",
                    "##########",
                    "##RR###RR#",
                    "##########",
                    "##########",
                    "#####TTTT#",
                    "#####TTTT#",
                    "#####TTTT#",
                ),
            ),
            FlowLevel(
                listOf(
                    "######WSW#",
                    "######WWW#",
                    "##########",
                    "##R#######",
                    "#RR##RRRRR",
                    "##########",
                    "#####RR###",
                    "RRRR######",
                    "##########",
                    "#R####RRRR",
                    "#TTTT#####",
                    "#TTTT#####",
                    "#TTTT##R##",
                ),
            ),
        )

        /** The Desert: a spring up in the dune, the oasis down in a hollow under a sandstone cliff, open to the sky. */
        val dunes = listOf(
            FlowLevel(
                listOf(
                    "WSW#RAAAAA",
                    "WWW##RAAAA",
                    "#####RAAAA",
                    "RRRR#RAAAA",
                    "#####RAAAA",
                    "#RRRRRAAAA",
                    "#####RAAAA",
                    "###RRRAAAA",
                    "######TTTT",
                    "######TTTT",
                    "##R###TTTT",
                    "##########",
                    "####RR####",
                ),
            ),
            FlowLevel(
                listOf(
                    "#WSW#RAAAA",
                    "#WWW#RAAAA",
                    "#####RAAAA",
                    "##RRRRAAAA",
                    "#####RAAAA",
                    "RRR##RAAAA",
                    "#####RAAAA",
                    "#RRR#RAAAA",
                    "#R####TTTT",
                    "######TTTT",
                    "###RR#TTTT",
                    "##########",
                    "##RR######",
                ),
            ),
            FlowLevel(
                listOf(
                    "WSW##RAAAA",
                    "WWW##RAAAA",
                    "RRRR#RAAAA",
                    "#####RAAAA",
                    "#RRRRRAAAA",
                    "#####RAAAA",
                    "RRR##RAAAA",
                    "#####RAAAA",
                    "#RRR##TTTT",
                    "######TTTT",
                    "#RR###TTTT",
                    "##########",
                    "###RR#####",
                ),
            ),
        )
    }
}

/**
 * A round of Sand flow: a cross-section of [level]'s sand with water waiting at the top. The finger carves channels
 * through the sand ([carve]); every [step] the water runs down, then sideways, through open squares, pools around
 * rocks, and fills the target where it runs in. The source never runs dry, so a round can't be lost: once [need]
 * squares of water have reached the target, [isDone]. [solution] is a path that always gets it there, for the
 * keyboard and screen readers ([carveNext]).
 */
class SandFlow(val level: FlowLevel, val need: Int = NEED) {
    val columns: Int = level.columns
    val rows: Int = level.height
    val size: Int get() = columns * rows

    private val cells = Array(columns * rows) { i ->
        when (level.rows[i / columns][i % columns]) {
            'R' -> FlowCell.ROCK
            '.', 'W', 'S' -> FlowCell.OPEN
            'A' -> FlowCell.AIR
            'T' -> FlowCell.TARGET
            else -> FlowCell.SAND
        }
    }
    private val wet = BooleanArray(columns * rows) { level.rows[it / columns][it % columns] in "WS" }

    /** Each water square's way sideways: -1 left, 1 right. It keeps going until it bumps into something. */
    private val heading = IntArray(columns * rows) { if (it % 2 == 0) 1 else -1 }
    private val moved = BooleanArray(columns * rows)
    private val poured = IntArray(columns * rows) { -1 }

    /** The square the water keeps coming from. */
    val source: Int = (0 until columns * rows).first { level.rows[it / columns][it % columns] == 'S' }

    /** How much water has reached the target so far. */
    var filled: Int = 0
        private set

    /** Steps run so far. */
    var ticks: Int = 0
        private set

    /** How full the target is, 0 to 1. */
    val fill: Float get() = (filled.toFloat() / need).coerceAtMost(1f)

    val isDone: Boolean get() = filled >= need

    /** The squares to carve, in order from the source down, that lead the water to the target. */
    val solution: List<Int> = findPath()

    fun cell(index: Int): FlowCell = cells[index]

    fun cell(x: Int, y: Int): FlowCell = cells[y * columns + x]

    /** Whether there is water in square [index]. */
    fun isWet(index: Int): Boolean = wet[index]

    /** How many squares hold water now. */
    val water: Int get() = wet.count { it }

    /** Carves square [index] open if it is sand. Returns whether it did. */
    fun carve(index: Int): Boolean {
        if (index !in cells.indices || cells[index] != FlowCell.SAND) return false
        cells[index] = FlowCell.OPEN
        return true
    }

    /** Carves the next [count] squares of sand along the [solution]. Returns the squares carved. */
    fun carveNext(count: Int = NEXT_BIT): List<Int> = solution.filter { cells[it] == FlowCell.SAND }.take(count).onEach { carve(it) }

    /** How many squares of the [solution] are still sand. */
    val solutionLeft: Int get() = solution.count { cells[it] == FlowCell.SAND }

    /** Lets the water run on by one step. Returns how much of it reached the target in this step. */
    fun step(): Int {
        if (isDone) return 0
        moved.fill(false)
        val before = filled
        // Bottom up, so a column of water falls together; the sweep turns each step so neither side is favored.
        val leftToRight = ticks % 2 == 0
        for (y in rows - 1 downTo 0) {
            for (k in 0 until columns) {
                val x = if (leftToRight) k else columns - 1 - k
                val i = y * columns + x
                if (wet[i] && !moved[i]) flow(x, y)
            }
        }
        if (!wet[source]) wet[source] = true
        ticks++
        return filled - before
    }

    private fun isOpen(x: Int, y: Int): Boolean =
        x in 0 until columns && y in 0 until rows && cells[y * columns + x].let { it == FlowCell.OPEN || it == FlowCell.AIR }

    private fun isTarget(x: Int, y: Int): Boolean = x in 0 until columns && y in 0 until rows && cells[y * columns + x] == FlowCell.TARGET

    /** Moves the water at ([x], [y]) one square: down if it can, else down and to its side, else along its side. */
    private fun flow(x: Int, y: Int) {
        val i = y * columns + x
        val d = heading[i]
        if (isTarget(x, y + 1)) return sink(i, i + columns)
        if (isOpen(x, y + 1) && !wet[i + columns]) return move(i, i + columns, d)
        for (side in intArrayOf(d, -d)) {
            if (isOpen(x + side, y) && !wet[i + side] && isOpen(x + side, y + 1) && !wet[i + side + columns]) return move(i, i + side + columns, side)
        }
        if (isTarget(x + d, y)) return sink(i, i + d)
        if (isOpen(x + d, y) && !wet[i + d]) return move(i, i + d, d)
        // Bumped into something: turn around and try that way next time.
        heading[i] = -d
    }

    private fun move(from: Int, to: Int, heading: Int) {
        wet[from] = false
        wet[to] = true
        moved[to] = true
        this.heading[to] = heading
    }

    private fun sink(from: Int, into: Int) {
        wet[from] = false
        poured[into] = ticks
        filled++
    }

    /** Steps since water last ran into target square [index], or null if it never has. */
    fun sincePour(index: Int): Int? = poured[index].takeIf { it >= 0 }?.let { ticks - it }

    /**
     * The cheapest way from the source to the target that only goes down and sideways, so water follows it: carving
     * a square of sand costs more than passing an open one, and rocks can't be passed.
     */
    private fun findPath(): List<Int> {
        val n = columns * rows
        val cost = IntArray(n) { Int.MAX_VALUE }
        val from = IntArray(n) { -1 }
        val done = BooleanArray(n)
        cost[source] = 0
        while (true) {
            var best = -1
            for (i in 0 until n) if (!done[i] && cost[i] != Int.MAX_VALUE && (best < 0 || cost[i] < cost[best])) best = i
            if (best < 0) break
            done[best] = true
            if (cells[best] == FlowCell.TARGET) {
                val path = mutableListOf<Int>()
                var at = from[best]
                while (at >= 0 && at != source) {
                    path += at
                    at = from[at]
                }
                return path.reversed().filter { cells[it] == FlowCell.SAND }
            }
            val x = best % columns
            val y = best / columns
            for ((dx, dy) in STEPS) {
                val nx = x + dx
                val ny = y + dy
                if (nx !in 0 until columns || ny !in 0 until rows) continue
                val next = ny * columns + nx
                val price = when (cells[next]) {
                    FlowCell.ROCK -> continue
                    FlowCell.SAND -> CARVE_COST
                    else -> 1
                }
                if (cost[best] + price < cost[next]) {
                    cost[next] = cost[best] + price
                    from[next] = best
                }
            }
        }
        error("Level has no way from the source to the target")
    }

    companion object {
        /** Squares of water it takes to fill the target. */
        const val NEED = 80

        /** Squares a "carve the next bit" carves. */
        const val NEXT_BIT = 2

        /** Steps per second the water runs at. */
        const val STEPS_PER_SECOND = 24f

        private const val CARVE_COST = 10
        private val STEPS = listOf(0 to 1, -1 to 0, 1 to 0)
    }
}
