package io.colorsand.ui.minigame

import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.sin
import kotlin.random.Random

/** One piece of the tower: its [center] and [width], as fractions of the play area's width (0 to 1). */
data class StackPiece(val center: Float, val width: Float) {
    val left: Float get() = center - width / 2
    val right: Float get() = center + width / 2

    companion object {
        /** The piece from [left] to [right]. */
        fun between(left: Float, right: Float): StackPiece = StackPiece((left + right) / 2, right - left)
    }
}

/**
 * What one drop did: the piece as it was [dropped], the part of it that stays on the tower ([placed]), whether it
 * was [perfect], and the overhang that crumbles away ([cuts], none, one or two bits at the sides).
 */
data class StackLanding(val dropped: StackPiece, val placed: StackPiece, val perfect: Boolean, val cuts: List<StackPiece>)

/**
 * A round of Stack the castle: a tower of [pieces], the foundation first, with the next piece [next] wide swinging
 * over it. Each drop lands the piece on top; whatever hangs over the edge is trimmed off. There is no way to fail:
 * the part that stays is never narrower than [MIN_WIDTH] (a piece that misses slides onto the edge instead), so the
 * next piece always comes in at least that wide. A [perfect] drop keeps the whole piece and widens the next one a
 * little, up to [START_WIDTH]. The round is done after [goal] pieces. Immutable; [drop] returns the next state.
 */
data class StackTower(
    val pieces: List<StackPiece> = listOf(StackPiece(0.5f, FOUNDATION_WIDTH)),
    val next: Float = START_WIDTH,
    val goal: Int = GOAL,
    /** How many drops were perfect so far. */
    val perfects: Int = 0,
) {
    val top: StackPiece get() = pieces.last()

    /** Pieces dropped so far, the foundation not counted. */
    val placed: Int get() = pieces.size - 1

    val isDone: Boolean get() = placed >= goal

    /** Where the next piece lands when dropped with its center at [center]: see [StackLanding]. */
    fun landing(center: Float): StackLanding {
        val dropped = StackPiece(center, next)
        if (abs(center - top.center) <= PERFECT) {
            // Snapped straight on top; a wider piece than the top still keeps all of itself.
            return StackLanding(dropped, StackPiece(top.center, next), true, emptyList())
        }
        val left = maxOf(dropped.left, top.left)
        val right = minOf(dropped.right, top.right)
        val kept = if (right - left >= MIN_WIDTH) {
            StackPiece.between(left, right)
        } else {
            // Too little overlap: a minimum-width piece slides onto the top's edge nearest the drop.
            val half = MIN_WIDTH / 2
            val c = center.coerceIn(top.left + half, maxOf(top.left + half, top.right - half))
            StackPiece(c, MIN_WIDTH)
        }
        val cuts = buildList {
            if (dropped.left < kept.left) add(StackPiece.between(dropped.left, minOf(kept.left, dropped.right)))
            if (dropped.right > kept.right) add(StackPiece.between(maxOf(kept.right, dropped.left), dropped.right))
        }.filter { it.width > 0.0005f }
        return StackLanding(dropped, kept, false, cuts)
    }

    /** The tower after dropping the next piece at [center]. Dropping on a finished tower does nothing. */
    fun drop(center: Float): StackTower {
        if (isDone) return this
        val land = landing(center)
        val width = if (land.perfect) minOf(land.placed.width + BONUS, maxOf(START_WIDTH, land.placed.width)) else land.placed.width
        return copy(
            pieces = pieces + land.placed,
            next = width.coerceAtLeast(MIN_WIDTH),
            perfects = perfects + if (land.perfect) 1 else 0,
        )
    }

    /** Whether a drop at [center] would be perfect. */
    fun isCentered(center: Float): Boolean = abs(center - top.center) <= PERFECT

    companion object {
        /** Pieces in a tower. */
        const val GOAL = 10

        /** The foundation's width. */
        const val FOUNDATION_WIDTH = 0.5f

        /** The first piece's width, and the widest a perfect drop brings a piece back to. */
        const val START_WIDTH = 0.44f

        /** The narrowest a piece ever gets. */
        const val MIN_WIDTH = 0.15f

        /** How near the top's center a drop has to be to count as perfect. */
        const val PERFECT = 0.03f

        /** How much wider a perfect drop makes the next piece. */
        const val BONUS = 0.04f
    }
}

/**
 * The swing of the piece waiting to drop: side to side around the middle, [amplitude] each way, one full sweep
 * there and back every [period] seconds, starting at [phase] (0 to 1 of a sweep).
 */
data class StackSwing(val amplitude: Float = AMPLITUDE, val period: Float = PERIOD, val phase: Float = 0f) {
    /** The piece's center at [time] seconds. */
    fun x(time: Float): Float = 0.5f + amplitude * sin(2 * PI.toFloat() * (time / period + phase))

    /** How far it leans at [time]: -1 (left) to 1 (right), for the rope's angle. */
    fun lean(time: Float): Float = sin(2 * PI.toFloat() * (time / period + phase))

    companion object {
        const val AMPLITUDE = 0.23f
        const val PERIOD = 3.2f

        /** A swing for [seed]: the same calm sweep, starting at a different point. */
        fun of(seed: Int): StackSwing = StackSwing(phase = Random(seed).nextFloat())

        /**
         * Whether a swing moving from [from] to [to] in one frame passes [target] (or touches it): the moment the
         * "Drop when centered" helper waits for, found the same at any frame rate.
         */
        fun passes(from: Float, to: Float, target: Float): Boolean = target in minOf(from, to)..maxOf(from, to)
    }
}
