package io.colorsand.ui.arena

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.PointMode
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.translate
import io.colorsand.core.Arena
import kotlin.math.PI
import kotlin.math.sin
import kotlin.random.Random

/**
 * The grain of one arena's sand, drawn over each layer of sand in a tube so it reads as sand rather than paint:
 * coarse damp grains and pebbles at the Playground, fine pale flecks, shell bits and sparkles at the Beach, pale
 * grains with shell specks and bubbles on the Sea Floor, silky grains with gold glints at the Desert, coarse gray
 * grit with chips of gravel at the Building Site, rusty dust with basalt specks and metal glints on Mars. Each
 * layer's grains are worked out once per tube size from the layer's
 * seed and kept, so they stay still from frame to frame and cost a handful of draw calls. Keep one per tube.
 */
internal class SandTexture(val arena: Arena) {
    private var width = -1f
    private var unit = -1f
    private val looks = HashMap<Int, LayerLook>()

    internal fun look(seed: Int, width: Float, unit: Float): LayerLook {
        if (width != this.width || unit != this.unit) {
            looks.clear()
            this.width = width
            this.unit = unit
        }
        return looks.getOrPut(seed) { layerLook(arena, seed, width, unit) }
    }
}

/**
 * Draws the grains of the layer with [seed] over the full width of the drawing area, from [top] down one unit
 * of sand, [height]. A layer that is still filling up is drawn whole and clipped, so its grains don't move.
 */
internal fun DrawScope.drawSandTexture(texture: SandTexture, top: Float, height: Float, seed: Int) {
    val look = texture.look(seed, size.width, height)
    translate(top = top) {
        look.tint?.let { drawRect(it, size = Size(size.width, height)) }
        for (g in look.grains) {
            drawPoints(g.points, PointMode.Points, g.color, strokeWidth = g.size, cap = if (g.round) StrokeCap.Round else StrokeCap.Square)
        }
        look.extras(this)
    }
}

/**
 * Gives the sand in a tube depth: it darkens toward the glass at both sides (more on the right, away from the
 * light) and the top surface catches the light. The sand runs from [surface] down to the bottom of the area, in
 * the band from [left] to [right]; [unit] is the height of one unit of sand.
 */
internal fun DrawScope.drawSandDepth(arena: Arena, left: Float, right: Float, surface: Float, unit: Float) {
    if (surface >= size.height) return
    val width = right - left
    drawRect(
        Brush.horizontalGradient(
            0f to Color.Black.copy(alpha = 0.22f),
            0.24f to Color.Transparent,
            0.68f to Color.Transparent,
            1f to Color.Black.copy(alpha = 0.3f),
            startX = left,
            endX = right,
        ),
        topLeft = Offset(left, surface),
        size = Size(width, size.height - surface),
    )
    val glow = unit * 0.28f
    val shine = if (arena == Arena.PLAYGROUND) 0.2f else 0.28f
    val light = if (arena == Arena.SEA_FLOOR) SEA_GLINT else Color.White
    drawRect(
        Brush.verticalGradient(listOf(light.copy(alpha = shine), Color.Transparent), startY = surface, endY = surface + glow),
        topLeft = Offset(left, surface),
        size = Size(width, glow),
    )
    drawLine(
        light.copy(alpha = shine + 0.12f),
        Offset(left + width * 0.12f, surface + size.width * 0.012f),
        Offset(right - width * 0.12f, surface + size.width * 0.012f),
        strokeWidth = size.width * 0.022f,
        cap = StrokeCap.Round,
    )
}

/** The Desert's dune ripple: how deep, peak to peak, the wave between two differently colored layers is. */
internal fun rippleDepth(width: Float, unit: Float): Float = minOf(width * 0.17f, unit * 0.22f)

/**
 * Everything above a dune ripple centered on [y] across [width], [depth] deep peak to peak, for the layer with
 * [seed] (its shape is the layer's own, so it stays put). Clip the upper layer to it; the lower layer reaches up
 * by half the depth to fill the crests, so on average both layers keep their exact height.
 */
internal fun ripplePath(width: Float, y: Float, depth: Float, seed: Int): Path {
    val r = Random(seed * 92821 + 7)
    val phase = r.nextFloat()
    val phase2 = r.nextFloat()
    val waves = 1.4f + r.nextFloat() * 0.6f
    val half = depth / 2
    return Path().apply {
        moveTo(0f, y - 4 * width)
        lineTo(width, y - 4 * width)
        val steps = 24
        for (s in steps downTo 0) {
            val x = width * s / steps
            lineTo(x, y + half * ripple(x / width, waves, phase, phase2))
        }
        close()
    }
}

/** A dune ripple's shape at [x] (0..1 across): gentle troughs and sharper crests, within -1..1. */
internal fun ripple(x: Float, waves: Float, phase: Float, phase2: Float): Float {
    val a = 2 * PI.toFloat() * (x * waves + phase)
    return (0.72f * sin(a) + 0.28f * sin(2 * a + 2 * PI.toFloat() * phase2)).coerceIn(-1f, 1f)
}

/** Grains of one size and color, drawn in one call. */
internal class Grains(val color: Color, val size: Float, val round: Boolean, val points: List<Offset>)

/** How one layer of sand looks, worked out once: a tint over the layer, grains, and a few bigger bits. */
internal class LayerLook(val tint: Color?, val grains: List<Grains>, val extras: DrawScope.() -> Unit)

private fun layerLook(arena: Arena, seed: Int, w: Float, u: Float): LayerLook {
    val rnd = Random(seed * 7919 + arena.ordinal * 104729 + 1)
    fun grains(n: Int, color: Color, size: Float, round: Boolean) =
        Grains(color, size, round, List(n) { Offset(rnd.nextFloat() * w, rnd.nextFloat() * u) })
    fun spot(margin: Float) = Offset(w * (0.18f + rnd.nextFloat() * 0.64f), u * (margin + rnd.nextFloat() * (1 - 2 * margin)))
    val white = Color.White
    val black = Color.Black
    return when (arena) {
        // Coarse, chunky and a little damp, with the odd pebble.
        Arena.PLAYGROUND -> {
            val grains = listOf(
                grains(26, black.copy(alpha = 0.15f), w * 0.05f, true),
                grains(40, black.copy(alpha = 0.11f), w * 0.036f, false),
                grains(30, white.copy(alpha = 0.2f), w * 0.03f, false),
                grains(10, white.copy(alpha = 0.12f), w * 0.045f, false),
            )
            val pebbles = List(listOf(0, 0, 1, 1, 2)[rnd.nextInt(5)]) {
                Pebble(spot(0.2f), w * (0.09f + rnd.nextFloat() * 0.05f), PEBBLES[rnd.nextInt(PEBBLES.size)], rnd.nextFloat() * 0.3f)
            }
            LayerLook(black.copy(alpha = 0.05f), grains) { pebbles.forEach { drawPebble(it) } }
        }
        // Coarse grey building sand: grit in several sizes, a gray cast and angular bits of gravel.
        Arena.BUILDING_SITE -> {
            val grains = listOf(
                grains(30, black.copy(alpha = 0.17f), w * 0.04f, false),
                grains(44, GRIT.copy(alpha = 0.3f), w * 0.03f, false),
                grains(34, white.copy(alpha = 0.26f), w * 0.026f, false),
                grains(12, black.copy(alpha = 0.1f), w * 0.058f, true),
            )
            val gravel = List(listOf(1, 1, 2, 2, 3)[rnd.nextInt(5)]) {
                gravel(spot(0.18f), w * (0.07f + rnd.nextFloat() * 0.05f), STONES[rnd.nextInt(STONES.size)], rnd)
            }
            LayerLook(GRIT.copy(alpha = 0.14f), grains) { gravel.forEach { drawGravel(it) } }
        }
        // Fine and pale-flecked, with bits of shell and a few sparkles.
        Arena.BEACH -> {
            val grains = listOf(
                grains(64, white.copy(alpha = 0.42f), w * 0.022f, false),
                grains(32, black.copy(alpha = 0.13f), w * 0.02f, false),
                grains(10, white.copy(alpha = 0.22f), w * 0.034f, true),
            )
            val shells = List(listOf(0, 0, 1, 1, 2)[rnd.nextInt(5)]) { Shell(spot(0.25f), w * (0.055f + rnd.nextFloat() * 0.025f), rnd.nextFloat() * 50f - 25f) }
            val sparkles = List(rnd.nextInt(2)) { spot(0.1f) to w * (0.045f + rnd.nextFloat() * 0.03f) }
            LayerLook(white.copy(alpha = 0.05f), grains) {
                shells.forEach { drawShell(it) }
                sparkles.forEach { (at, r) -> drawSparkle(at, r, white, 0.85f) }
            }
        }
        // Fine pale grains with specks of shell, tiny trapped bubbles and a cool glint.
        Arena.SEA_FLOOR -> {
            val grains = listOf(
                grains(60, white.copy(alpha = 0.38f), w * 0.02f, false),
                grains(28, black.copy(alpha = 0.11f), w * 0.019f, false),
                grains(14, SEA_GLINT.copy(alpha = 0.3f), w * 0.028f, true),
            )
            val bits = List(rnd.nextInt(3)) { Triple(spot(0.2f), w * (0.035f + rnd.nextFloat() * 0.02f), SHELL_BITS[rnd.nextInt(SHELL_BITS.size)]) }
            val bubbles = List(listOf(0, 1, 1, 2)[rnd.nextInt(4)]) { spot(0.2f) to w * (0.03f + rnd.nextFloat() * 0.025f) }
            val sparkles = List(rnd.nextInt(2)) { spot(0.1f) to w * (0.04f + rnd.nextFloat() * 0.025f) }
            LayerLook(SEA_GLINT.copy(alpha = 0.05f), grains) {
                bits.forEach { (at, r, color) -> drawOval(color, Offset(at.x - r, at.y - r * 0.45f), Size(2 * r, r * 0.9f)) }
                bubbles.forEach { (at, r) -> drawBubble(at, r) }
                sparkles.forEach { (at, r) -> drawSparkle(at, r, SEA_GLINT, 0.8f) }
            }
        }
        // Silky fine grains, faint streaks along the dunes and gold glints.
        Arena.DESERT -> {
            val grains = listOf(
                grains(56, white.copy(alpha = 0.2f), w * 0.017f, false),
                grains(44, black.copy(alpha = 0.1f), w * 0.016f, false),
                grains(9, GOLD.copy(alpha = 0.85f), w * 0.024f, true),
            )
            val streaks = List(2) { k ->
                val y = u * (0.3f + 0.4f * k + rnd.nextFloat() * 0.1f)
                val phase = rnd.nextFloat()
                Path().apply {
                    moveTo(0f, y)
                    for (s in 1..12) {
                        val x = w * s / 12
                        lineTo(x, y + u * 0.04f * ripple(x / w, 1.3f, phase, phase))
                    }
                }
            }
            val glints = List(listOf(0, 0, 1)[rnd.nextInt(3)]) { spot(0.15f) to w * (0.035f + rnd.nextFloat() * 0.02f) }
            LayerLook(null, grains) {
                streaks.forEach { drawPath(it, white.copy(alpha = 0.08f), style = Stroke(width = w * 0.022f)) }
                glints.forEach { (at, r) -> drawSparkle(at, r, GOLD, 0.8f) }
            }
        }
        // Rusty iron-oxide dust: a red cast, dark basalt specks and now and then a metallic glint.
        Arena.MARS -> {
            val grains = listOf(
                grains(48, RUST.copy(alpha = 0.22f), w * 0.022f, false),
                grains(40, white.copy(alpha = 0.16f), w * 0.016f, false),
                grains(22, BASALT.copy(alpha = 0.5f), w * 0.026f, true),
                grains(6, BASALT.copy(alpha = 0.35f), w * 0.04f, true),
            )
            val glints = List(listOf(0, 1, 1)[rnd.nextInt(3)]) { spot(0.15f) to w * (0.035f + rnd.nextFloat() * 0.02f) }
            LayerLook(RUST.copy(alpha = 0.07f), grains) {
                glints.forEach { (at, r) -> drawSparkle(at, r, METAL, 0.85f) }
            }
        }
    }
}

private val GOLD = Color(0xFFFFE9A6)
private val SEA_GLINT = Color(0xFFD8F4FF)
private val SHELL_BITS = listOf(Color(0xCCFFF1E6), Color(0xB3FFC9C2), Color(0xB3F2E4FF))
private val RUST = Color(0xFF9C3A1C)
private val BASALT = Color(0xFF2E2224)
private val METAL = Color(0xFFE6ECF2)
private val PEBBLES = listOf(Color(0xFF8D8478), Color(0xFFA89A88), Color(0xFF757079), Color(0xFFB9A588), Color(0xFF9C8A7A))

private class Pebble(val at: Offset, val size: Float, val color: Color, val tilt: Float)

private fun DrawScope.drawPebble(p: Pebble) {
    val w = p.size
    val h = w * (0.7f + p.tilt)
    // Half sunk in the sand: a dark rim below, a lighter cap, a small dull highlight.
    drawOval(Color.Black.copy(alpha = 0.28f), Offset(p.at.x - w * 0.52f, p.at.y - h * 0.4f), Size(w * 1.04f, h * 0.98f))
    drawOval(p.color, Offset(p.at.x - w / 2, p.at.y - h / 2), Size(w, h * 0.9f))
    drawOval(Color.White.copy(alpha = 0.18f), Offset(p.at.x - w * 0.4f, p.at.y - h * 0.45f), Size(w * 0.7f, h * 0.45f))
    drawOval(Color.White.copy(alpha = 0.3f), Offset(p.at.x - w * 0.25f, p.at.y - h * 0.34f), Size(w * 0.22f, h * 0.16f))
}

private val GRIT = Color(0xFF85878A)
private val STONES = listOf(Color(0xFF8E9196), Color(0xFFA7A39C), Color(0xFF6F7177), Color(0xFFB4ADA3), Color(0xFF7D7A76))

/** A chip of crushed stone: an angular [shape] and a lit [facet] on top of it. */
private class Gravel(val shape: Path, val facet: Path, val color: Color, val size: Float)

private fun gravel(at: Offset, size: Float, color: Color, rnd: Random): Gravel {
    val corners = 5 + rnd.nextInt(2)
    val start = rnd.nextFloat() * 2 * PI.toFloat()
    fun outline(scale: Float, shift: Offset) = Path().apply {
        for (k in 0 until corners) {
            val a = start + 2 * PI.toFloat() * k / corners
            val r = size * 0.5f * scale * (0.8f + 0.2f * ((k * 7 + corners) % 3) / 2f)
            val p = at + shift + Offset(kotlin.math.cos(a) * r, sin(a) * r * 0.78f)
            if (k == 0) moveTo(p.x, p.y) else lineTo(p.x, p.y)
        }
        close()
    }
    return Gravel(outline(1f, Offset.Zero), outline(0.55f, Offset(-size * 0.1f, -size * 0.1f)), color, size)
}

private fun DrawScope.drawGravel(g: Gravel) {
    translate(g.size * 0.05f, g.size * 0.08f) { drawPath(g.shape, Color.Black.copy(alpha = 0.3f)) }
    drawPath(g.shape, g.color)
    drawPath(g.facet, Color.White.copy(alpha = 0.22f))
}

private class Shell(val at: Offset, val size: Float, val tilt: Float)

/** A little fan shell: a half disc with ridges. */
private fun DrawScope.drawShell(s: Shell) {
    val r = s.size
    val topLeft = Offset(s.at.x - r, s.at.y - r)
    drawArc(Color(0xFFFFF4EA), 180f + s.tilt, 180f, useCenter = true, topLeft = topLeft, size = Size(2 * r, 2 * r))
    drawArc(Color(0xFFF0B9A5), 180f + s.tilt, 180f, useCenter = false, topLeft = topLeft, size = Size(2 * r, 2 * r), style = Stroke(r * 0.18f))
    for (k in 1..3) {
        val a = (180f + s.tilt + 45f * k) * PI.toFloat() / 180f
        drawLine(Color(0xFFE9AE9A), s.at, s.at + Offset(kotlin.math.cos(a), sin(a)) * r * 0.9f, strokeWidth = r * 0.12f)
    }
}

/** A tiny air bubble trapped in the sand: a clear ring with a bright spot. */
private fun DrawScope.drawBubble(at: Offset, r: Float) {
    drawCircle(SEA_GLINT.copy(alpha = 0.18f), r, at)
    drawCircle(Color.White.copy(alpha = 0.55f), r, at, style = Stroke(r * 0.22f))
    drawCircle(Color.White.copy(alpha = 0.85f), r * 0.28f, at + Offset(-r * 0.35f, -r * 0.35f))
}

/** A four-pointed glint of light at [at], [r] from its center to a tip. */
internal fun DrawScope.drawSparkle(at: Offset, r: Float, color: Color, alpha: Float = 1f) {
    if (alpha <= 0f) return
    drawCircle(color.copy(alpha = 0.28f * alpha), r * 0.55f, at)
    val thin = r * 0.26f
    drawLine(color.copy(alpha = alpha), at - Offset(r, 0f), at + Offset(r, 0f), thin, StrokeCap.Round)
    drawLine(color.copy(alpha = alpha), at - Offset(0f, r), at + Offset(0f, r), thin, StrokeCap.Round)
    drawCircle(Color.White.copy(alpha = alpha), thin * 1.1f, at)
}
