/**
 * Level [level]'s keepsake game, full screen over the arena's scenery: its title and twist at the top with a close
 * button, the game below, and once it is played to the end a result card. Finishing it earns the level its
 * keepsake star (see [GameController.finishKeepsakeGame]); playing again is just for fun.
 */
@OptIn(ExperimentalComposeUiApi::class)
@Composable
fun MinigameOverlay(level: Int, game: GameController, feedback: Feedback, onClose: () -> Unit) {
    DismissOnBack(onBack = onClose)
    val keepsake = remember(level) { KeepsakeGame.forLevel(level) }
    var round by remember(level) { mutableStateOf(0) }
    var result by remember(level) { mutableStateOf<MinigameOutcome?>(null) }
    val enter = remember(level) { Animatable(0f) }
    LaunchedEffect(level) { enter.animateTo(1f, spring(dampingRatio = 0.75f, stiffness = Spring.StiffnessLow)) }
    Box(
        Modifier
            .fillMaxSize()
            // Keep keyboard focus inside the game: Tab never reaches the level underneath.
            .focusProperties { exit = { FocusRequester.Cancel } }
            .focusGroup()
            // Swallow taps so nothing underneath reacts, without taking keyboard focus from the game.
            .focusProperties { canFocus = false }
            .clickable(remember { MutableInteractionSource() }, indication = null) {}
            .graphicsLayer { alpha = enter.value.coerceIn(0f, 1f) }
            .background(Brush.verticalGradient(listOf(Color.Black.copy(alpha = 0.04f), Color.Black.copy(alpha = 0.22f)))),
    ) {
        WithHudLook {
            Column(
                Modifier
                    .fillMaxSize()
                    .windowInsetsPadding(WindowInsets.safeDrawing)
                    .padding(16.dp)
                    .graphicsLayer { translationY = (1f - enter.value) * 48.dp.toPx() },
                horizontalAlignment = Alignment.CenterHorizontally,
            ) {
                MinigameTitle(keepsake, earned = level in game.keepsakeStars, onClose = onClose)
                Spacer(Modifier.height(14.dp))
                key(round) {
                    MinigameContent(
                        keepsake,
                        seed = level * 1000 + round,
                        feedback = feedback,
                        onFinished = {
                            val cleared = game.isCleared(level)
                            val earned = game.finishKeepsakeGame(level)
                            feedback.play(Sounds.solved)
                            feedback.confirm()
                            result = when {
                                earned -> MinigameOutcome.NEW_STAR
                                cleared -> MinigameOutcome.REPLAY
                                else -> MinigameOutcome.NOT_CLEARED
                            }
                        },
                        modifier = Modifier.weight(1f).widthIn(max = 560.dp).fillMaxWidth(),
                    )
                }
            }
            result?.let { outcome ->
                MinigameResult(
                    keepsake,
                    level,
                    outcome,
                    seed = level * 1000 + round,
                    onAgain = { round++; result = null },
                    onDone = onClose,
                )
            }
        }
    }
}

/** The bar over a keepsake game: the keepsake's badge, the game's title and twist, and a close button. */
@Composable
private fun MinigameTitle(keepsake: KeepsakeGame, earned: Boolean, onClose: () -> Unit) {
    val palette = LocalPalette.current
    Row(
        Modifier
            .widthIn(max = 560.dp)
            .fillMaxWidth()
            .frosted(palette, RoundedCornerShape(26.dp))
            .padding(start = 10.dp, end = 8.dp, top = 8.dp, bottom = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        // The keepsake star this game earns: an empty slot until it does.
        KeepsakeBadge(keepsake.arena, keepsake.stage, earned, Modifier.size(50.dp))
        Spacer(Modifier.width(10.dp))
        Column(Modifier.weight(1f)) {
            Text(
                keepsake.game.title,
                color = palette.accent,
                fontSize = 24.sp,
                fontWeight = FontWeight.Black,
                maxLines = 1,
                style = LocalTextStyle.current.withTitleShadow(palette),
                modifier = Modifier.semantics { heading() },
            )
            Text(
                keepsake.twist,
                color = palette.dimText,
                fontSize = 14.sp,
                lineHeight = 17.sp,
                fontWeight = FontWeight.Bold,
                maxLines = 2,
            )
        }
        Spacer(Modifier.width(8.dp))
        RoundIconButton(HudIcons.Close, "Close", onClose, ButtonStyle.accent(palette), size = 42.dp)
    }
}

/** How a keepsake game ended: it earned the level its keepsake star, it was a replay, or the level isn't cleared yet. */
internal enum class MinigameOutcome { NEW_STAR, REPLAY, NOT_CLEARED }
