/**
 * Sand gem match, a gentle match-three: a 7 x 7 board of glossy gems (the treasure chest's pearls, sea glass, coral
 * gems, blue drops and gold stars on the Sea Floor; the flag's red crystals, meteor stones, violet and ice crystals
 * and dust topaz in Mars's red dusk). Swap two neighbors, by a swipe or a tap on each, to line up three or more of a
 * kind: they burst into sand that pours down, the gems above fall and new ones drop in, sometimes in cascades. No
 * move limit, nothing to lose; a board with no move left is gently reshuffled, and a hint glows after a while.
 * Filling the meter ([GemMatch.GOAL] gems) calls [onFinished]. Every gem is focusable: arrow keys move between them,
 * Enter or Space picks one and an arrow then swaps it that way, and a "Make a match" action (or the H key) plays any
 * good swap.
 */
@Composable
fun GemMatchGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { GemLook.of(arena, grade) }
    var round by remember(seed) { mutableStateOf(GemMatch.start(seed)) }
    // The board as drawn, which runs a step behind the round while a turn plays out.
    var shown by remember(seed) { mutableStateOf(round.board) }
    var busy by remember(seed) { mutableStateOf(false) }
    var done by remember(seed) { mutableStateOf(false) }
    var selected by remember(seed) { mutableStateOf<Int?>(null) }
    var focused by remember(seed) { mutableStateOf<Int?>(null) }
    var keyboard by remember { mutableStateOf(false) }
    var filled by remember(seed) { mutableStateOf(0) }
    var status by remember(seed) { mutableStateOf(look.hello) }
    var swap by remember(seed) { mutableStateOf<GemMove?>(null) }
    var bursting by remember(seed) { mutableStateOf<Set<Int>>(emptySet()) }
    var falls by remember(seed) { mutableStateOf<Map<Int, Float>>(emptyMap()) }
    val swapAnim = remember(seed) { Animatable(0f) }
    val burstAnim = remember(seed) { Animatable(0f) }
    val fallAnim = remember(seed) { Animatable(1f) }
    val shuffleAnim = remember(seed) { Animatable(0f) }
    val finale = remember(seed) { Animatable(0f) }
    val grains = remember(seed) { mutableListOf<SandGrain>() }
    val sparks = remember(seed) { Random(seed) }
    // Seconds since the game opened, and when the player last did something (for the hint).
    var now by remember(seed) { mutableStateOf(0f) }
    val lastAction = remember(seed) { floatArrayOf(0f) }
    val requesters = remember { List(GemMatch.SIZE * GemMatch.SIZE) { FocusRequester() } }
    val sceneClock = rememberSceneClock()
    val scope = rememberCoroutineScope()
    val meter by animateFloatAsState((filled.toFloat() / round.goal).coerceIn(0f, 1f), tween(600, easing = FastOutSlowInEasing), label = "meter")

    LaunchedEffect(seed) {
        var start = -1L
        while (true) {
            withFrameNanos { t ->
                if (start < 0) start = t
                now = (t - start) / 1_000_000_000f
                grains.removeAll { now - it.born > SandGrain.LIFE }
            }
        }
    }

    fun pour(cells: Set<Int>) {
        for (cell in cells) {
            val style = look.gems.getOrNull(shown[cell]) ?: continue
            repeat(GRAINS_PER_GEM) {
                grains += SandGrain(
                    x = cell % shown.size + 0.5f + (sparks.nextFloat() - 0.5f) * 0.6f,
                    y = cell / shown.size + 0.5f + (sparks.nextFloat() - 0.5f) * 0.6f,
                    vx = (sparks.nextFloat() - 0.5f) * 1.6f,
                    vy = -0.6f - sparks.nextFloat() * 1.4f,
                    color = if (sparks.nextFloat() < 0.5f) style.mid else style.light,
                    size = 0.035f + sparks.nextFloat() * 0.03f,
                    born = now,
                )
            }
        }
    }

    fun trySwap(a: Int, b: Int) {
        if (busy || done || !round.board.adjacent(a, b)) return
        selected = null
        lastAction[0] = now
        val turn = round.swap(a, b)
        busy = true
        scope.launch {
            swap = GemMove(a, b)
            swapAnim.snapTo(0f)
            feedback.play(Sounds.pick)
            feedback.tick()
            swapAnim.animateTo(1f, tween(SWAP_MS, easing = FastOutSlowInEasing))
            if (turn == null) {
                status = "No line there. Try another swap!"
                swapAnim.animateTo(0f, tween(SWAP_MS, easing = FastOutSlowInEasing))
                swap = null
                busy = false
                return@launch
            }
            shown = shown.swapped(a, b)
            swap = null
            turn.cascades.forEachIndexed { wave, cascade ->
                val n = cascade.matched.size
                status = when {
                    wave >= 1 -> "Cascade! The sand pours on."
                    n >= 5 -> "Wow, $n gems at once!"
                    n == 4 -> "Four in a row!"
                    else -> "A line of three!"
                }
                feedback.play(Sounds.chime(wave + if (n > 3) 2 else 1))
                feedback.tick()
                bursting = cascade.matched
                pour(cascade.matched)
                burstAnim.snapTo(0f)
                burstAnim.animateTo(1f, tween(BURST_MS, easing = LinearEasing))
                filled = minOf(filled + n, round.goal)
                val drops = cascade.falls.associate { it.cell to (it.cell / shown.size - it.fromRow).toFloat() }
                falls = drops
                fallAnim.snapTo(0f)
                shown = cascade.board
                bursting = emptySet()
                val longest = drops.values.maxOrNull() ?: 1f
                fallAnim.animateTo(1f, tween((FALL_MS * sqrt(longest)).toInt(), easing = LinearEasing))
                falls = emptyMap()
                feedback.play(Sounds.land)
            }
            val after = turn.after
            if (after.isDone) {
                status = look.done
            } else if (turn.reshuffled != null) {
                status = "No moves left, so a gentle shuffle."
                shuffleAnim.snapTo(0f)
                shuffleAnim.animateTo(0.5f, tween(SHUFFLE_MS, easing = FastOutSlowInEasing))
                shown = turn.reshuffled
                feedback.play(Sounds.pour)
                shuffleAnim.animateTo(1f, tween(SHUFFLE_MS, easing = FastOutSlowInEasing))
                shuffleAnim.snapTo(0f)
            } else if (after.goal - after.cleared <= 10) {
                status = "Almost full!"
            }
            round = after
            shown = after.board
            lastAction[0] = now
            busy = false
            if (after.isDone) done = true
        }
    }

    fun tapCell(cell: Int) {
        if (busy || done) return
        lastAction[0] = now
        val sel = selected
        when {
            sel == null -> {
                selected = cell
                status = "Now swap it with a neighbor."
                feedback.play(Sounds.click)
            }
            sel == cell -> selected = null
            round.board.adjacent(sel, cell) -> trySwap(sel, cell)
            else -> {
                selected = cell
                feedback.play(Sounds.click)
            }
        }
    }

    fun makeMatch() {
        round.anyMove()?.let { trySwap(it.a, it.b) }
    }

    LaunchedEffect(done) {
        if (done) {
            feedback.confirm()
            finale.animateTo(1f, tween(FINALE_MS, easing = LinearEasing))
            onFinished()
        }
    }

    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        BoxWithConstraints(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .semantics {
                    contentDescription = "A board of gems, ${GemMatch.SIZE} by ${GemMatch.SIZE}"
                    stateDescription = "$filled of ${round.goal} gems matched"
                    customActions = listOf(CustomAccessibilityAction(MAKE_MATCH) { makeMatch(); true })
                }
                // The focus ring shows only while playing by keyboard, not after a tap.
                .onPreviewKeyEvent { keyboard = true; false }
                .pointerInput(seed) {
                    awaitEachGesture {
                        val down = awaitFirstDown()
                        keyboard = false
                        val grid = GemGrid(size.width.toFloat(), size.height.toFloat(), GemMatch.SIZE)
                        val start = grid.cellAt(down.position) ?: return@awaitEachGesture
                        var swiped = false
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            if (!change.pressed) break
                            val d = change.position - down.position
                            if (!swiped && max(abs(d.x), abs(d.y)) > grid.cell * 0.35f) {
                                swiped = true
                                val next = if (abs(d.x) > abs(d.y)) round.board.neighbor(start, 0, sign(d.x).toInt())
                                else round.board.neighbor(start, sign(d.y).toInt(), 0)
                                if (next != null) trySwap(start, next)
                            }
                            change.consume()
                        }
                        if (!swiped) tapCell(start)
                    }
                },
        ) {
            val dpGrid = GemGrid(maxWidth.value, maxHeight.value, GemMatch.SIZE)
            // The keyboard starts in the middle of the board (its ring shows once a key is pressed). Here, inside the
            // board's own composition, the gems' buttons are in place to take it.
            LaunchedEffect(Unit) { runCatching { requesters[requesters.size / 2].requestFocus() } }
            Canvas(Modifier.fillMaxSize()) {
                val t = now
                val grid = GemGrid(size.width, size.height, GemMatch.SIZE)
                drawGemBoard(look, grid, t)
                val r = grid.cell * 0.4f
                // The hint: a move glows once the player has been still for a while.
                val hint = if (!busy && !done && t - lastAction[0] > HINT_S) round.anyMove() else null
                val pulse = 0.5f + 0.5f * sin(t * 4f)
                if (hint != null) for (c in listOf(hint.a, hint.b)) drawGemRing(grid.center(c), grid.cell, Color(0xFFFFF3B0), pulse)
                selected?.let { drawGemRing(grid.center(it), grid.cell, Color.White, pulse) }
                val shuffle = shuffleAnim.value
                val shrink = if (shuffle > 0f) abs(1f - 2f * shuffle) else 1f
                clipRect(grid.well.left, grid.well.top, grid.well.right, grid.well.bottom) {
                    for (cell in 0 until shown.cells) {
                        val kind = shown[cell]
                        if (kind == GemBoard.EMPTY) continue
                        val row = cell / shown.size
                        val column = cell % shown.size
                        val drop = falls[cell]
                        val p = fallAnim.value
                        var at = if (drop != null) grid.center(row - drop * (1f - p * p), column) else grid.center(cell)
                        val s = swap
                        if (s != null && (cell == s.a || cell == s.b)) {
                            val other = grid.center(if (cell == s.a) s.b else s.a)
                            at += (other - at) * swapAnim.value
                        }
                        var scaleBy = shrink
                        if (cell in bursting) {
                            val b = burstAnim.value
                            scaleBy *= (1f - b) * (1f + 0.35f * sin(b * PI.toFloat()))
                            if (b < 0.6f) drawGemRing(at, grid.cell * (1f + 0.4f * b), Color.White.copy(alpha = 0.6f * (1f - b)), 0f)
                        }
                        // A little squash as a fallen gem lands.
                        val land = if (drop != null && p > 0.85f) sin((p - 0.85f) / 0.15f * PI.toFloat()) * 0.08f else 0f
                        if (cell == selected) at += Offset(0f, -grid.cell * 0.05f * pulse)
                        val glint = ((finale.value * 1.8f - (row + column) * 0.06f)).let { if (it in 0f..1f) it else 0f }
                        if (scaleBy > 0.01f) {
                            scale(scaleBy * (1f + land), scaleBy * (1f - land), at) {
                                rotate(if (shuffle > 0f) (1f - shrink) * 90f else 0f, at) {
                                    drawGem(look.gems[kind], at, r, glint)
                                }
                            }
                        }
                    }
                }
                // Sand pouring down from the bursts.
                for (g in grains) {
                    val age = t - g.born
                    val x = g.x + g.vx * age
                    val y = g.y + g.vy * age + 0.5f * SandGrain.GRAVITY * age * age
                    val alpha = (1f - age / SandGrain.LIFE).coerceIn(0f, 1f)
                    val at = Offset(grid.origin.x + grid.pad + x * grid.cell, grid.origin.y + grid.pad + y * grid.cell)
                    if (at.y > grid.origin.y + grid.side) continue
                    drawCircle(g.color.copy(alpha = alpha), g.size * grid.cell, at)
                }
                if (keyboard) focused?.let { drawGemFocus(grid.center(it), grid.cell, palette.accent) }
            }
            // One focusable button over each gem, for keyboards and screen readers.
            for (cell in 0 until GemMatch.SIZE * GemMatch.SIZE) {
                val c = dpGrid.center(cell)
                val half = dpGrid.cell / 2f
                val kind = shown[cell]
                val name = look.gems.getOrNull(kind)?.name ?: "empty"
                val row = cell / GemMatch.SIZE + 1
                val column = cell % GemMatch.SIZE + 1
                val sel = selected
                Box(
                    Modifier
                        .offset((c.x - half).dp, (c.y - half).dp)
                        .size(dpGrid.cell.dp)
                        .focusRequester(requesters[cell])
                        .onFocusChanged { if (it.isFocused) focused = cell else if (focused == cell) focused = null }
                        .onKeyEvent { event ->
                            val pressed = event.type == KeyEventType.KeyDown
                            val dir = when (event.key) {
                                Key.DirectionLeft -> 0 to -1
                                Key.DirectionRight -> 0 to 1
                                Key.DirectionUp -> -1 to 0
                                Key.DirectionDown -> 1 to 0
                                else -> null
                            }
                            when {
                                dir != null -> {
                                    if (pressed) {
                                        val next = round.board.neighbor(cell, dir.first, dir.second)
                                        if (next != null) {
                                            if (selected == cell) trySwap(cell, next) else runCatching { requesters[next].requestFocus() }
                                        }
                                    }
                                    true
                                }
                                event.key == Key.Enter || event.key == Key.Spacebar || event.key == Key.NumPadEnter -> {
                                    if (pressed) tapCell(cell)
                                    true
                                }
                                // H asks the helper for a match, like the screen readers' action.
                                event.key == Key.H -> {
                                    if (pressed) makeMatch()
                                    true
                                }
                                event.key == Key.Escape && selected != null -> {
                                    if (pressed) selected = null
                                    true
                                }
                                else -> false
                            }
                        }
                        .focusable()
                        .semantics {
                            contentDescription = "Row $row, column $column, $name" + if (sel == cell) ", picked" else ""
                            role = Role.Button
                            val label = when {
                                sel == null -> "Pick"
                                sel == cell -> "Put back"
                                round.board.adjacent(sel, cell) -> "Swap with the picked gem"
                                else -> "Pick"
                            }
                            onClick(label = label) { tapCell(cell); true }
                            customActions = listOf(CustomAccessibilityAction(MAKE_MATCH) { makeMatch(); true })
                        },
                )
            }
        }
        Spacer(Modifier.height(12.dp))
        Row(
            Modifier
                .widthIn(max = 460.dp)
                .fillMaxWidth()
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(start = 8.dp, end = 18.dp, top = 6.dp, bottom = 6.dp)
                .clearAndSetSemantics { contentDescription = "${look.meterName}: $filled of ${round.goal} gems" },
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Canvas(Modifier.size(40.dp)) {
                val unit = size.minDimension / 100f
                scale(unit, unit, Offset.Zero) { drawKeepsake(look.arena, look.stage, sceneClock.value, grade) }
            }
            Box(
                Modifier
                    .weight(1f)
                    .height(18.dp)
                    .clip(RoundedCornerShape(50)),
            ) {
                Canvas(Modifier.fillMaxSize()) {
                    val h = size.height
                    drawRoundRect(Color.Black.copy(alpha = 0.12f), cornerRadius = CornerRadius(h / 2))
                    val w = size.width * meter
                    if (w > 0f) {
                        drawRoundRect(
                            Brush.verticalGradient(listOf(look.meterLight, look.meterDark)),
                            size = Size(max(w, h), h),
                            cornerRadius = CornerRadius(h / 2),
                        )
                        // Grains glinting in the sand.
                        for (k in 0 until (w / (h * 0.6f)).toInt()) {
                            val x = h * 0.4f + k * h * 0.6f
                            drawCircle(Color.White.copy(alpha = 0.35f), h * 0.07f, Offset(x, h * (0.3f + 0.4f * ((k * 7) % 3) / 2f)))
                        }
                        drawRoundRect(Color.White.copy(alpha = 0.4f), Offset(h * 0.3f, h * 0.18f), Size(max(w - h * 0.6f, 0f), h * 0.18f), CornerRadius(h * 0.09f))
                    }
                }
            }
            Text("$filled/${round.goal}", color = palette.accent, fontSize = 16.sp, fontWeight = FontWeight.Black, maxLines = 1)
        }
        Spacer(Modifier.height(10.dp))
        Text(
            status,
            color = palette.text,
            fontSize = 16.sp,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center,
            maxLines = 1,
            modifier = Modifier
                .widthIn(max = 420.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp)
                .semantics { liveRegion = LiveRegionMode.Polite },
        )
    }
}

/**
 * A grain of sand from a burst gem, in board cells: thrown from ([x], [y]) at ([vx], [vy]) cells a second at [born]
 * seconds, then falling.
 */
private class SandGrain(val x: Float, val y: Float, val vx: Float, val vy: Float, val color: Color, val size: Float, val born: Float) {
    companion object {
        const val LIFE = 1.3f
        const val GRAVITY = 9f
    }
}

/** What screen readers call the helper that plays any good swap. */
private const val MAKE_MATCH = "Make a match"

private const val GRAINS_PER_GEM = 9

/** How long a swap slides, in milliseconds. */
private const val SWAP_MS = 170

/** How long matched gems take to burst. */
private const val BURST_MS = 280

/** How long a gem takes to fall one row; longer falls take longer, as if under gravity. */
private const val FALL_MS = 190f

/** Each half of a reshuffle. */
private const val SHUFFLE_MS = 380

/** Seconds of stillness before a hint glows. */
private const val HINT_S = 7f

/** The closing glint across the board before the result card. */
private const val FINALE_MS = 1400
