/**
 * Sort: a pile of fifteen mixed things in the middle (shells in three colors and three shapes on the Beach; gravel
 * stones, sand sacks and bricks on the Building Site) and three labelled bins along the bottom, each with a sample
 * on its front (woven baskets, or metal skips). Drag each thing to its bin: a right drop pops in with a chime, a
 * wrong one gently slides back. Tapping a thing and then a bin sorts it too. When the pile is empty the bins hop
 * and the round calls [onFinished]. Every thing in the pile and every bin is its own focusable button: pick a thing
 * with Enter or Space, then a bin; screen readers also get a "Sort into ..." action per bin on every thing.
 * [seed] mixes the pile.
 */
@Composable
fun SortGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { SortLook.of(arena, grade) }
    var round by remember(seed) { mutableStateOf(SortRound.start(seed)) }
    var selected by remember(seed) { mutableStateOf<Int?>(null) }
    var drag by remember(seed) { mutableStateOf<SortDrag?>(null) }
    val motions = remember(seed) { mutableStateMapOf<Int, SortMotion>() }
    val landed = remember(seed) { mutableStateListOf<Int>() }
    val hops = remember(seed) { List(SortRound.KINDS) { Animatable(1f) } }
    val wobbles = remember(seed) { List(SortRound.KINDS) { Animatable(1f) } }
    var status by remember(seed) { mutableStateOf(look.start) }
    var keyboard by remember { mutableStateOf(false) }
    var focusedItem by remember { mutableStateOf<Int?>(null) }
    var focusedBin by remember { mutableStateOf<Int?>(null) }
    var focusNext by remember(seed) { mutableStateOf<Int?>(null) }
    val itemFocus = remember(seed) { List(round.items.size) { FocusRequester() } }
    val binFocus = remember { List(SortRound.KINDS) { FocusRequester() } }
    // Reading order for the keyboard: top to bottom, left to right.
    val order = remember(seed) { round.items.indices.sortedWith(compareBy({ (round.items[it].y * 5).toInt() }, { round.items[it].x })) }
    val clock = rememberSceneClock()
    val scope = rememberCoroutineScope()
    val bin = if (look.theme == SortTheme.SHELLS) "basket" else "bin"

    LaunchedEffect(seed) { runCatching { itemFocus[order.first()].requestFocus() } }
    LaunchedEffect(focusNext) {
        val next = focusNext ?: return@LaunchedEffect
        delay(30)
        runCatching { itemFocus[next].requestFocus() }
        focusNext = null
    }
    LaunchedEffect(round.isDone) {
        if (!round.isDone) return@LaunchedEffect
        // Once the last one has landed, the bins hop one after another.
        delay(FLY_MS + 250L)
        feedback.play(Sounds.chime(6))
        feedback.confirm()
        for (h in hops) {
            launch {
                h.snapTo(0f)
                h.animateTo(1f, tween(HOP_MS, easing = LinearEasing))
                h.snapTo(0f)
                h.animateTo(1f, tween(HOP_MS, easing = LinearEasing))
            }
            delay(140)
        }
        delay(HOP_MS * 2L + 300L)
        onFinished()
    }

    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        BoxWithConstraints(Modifier.weight(1f).fillMaxWidth().clip(RoundedCornerShape(28.dp))) {
            val layout = remember(maxWidth, maxHeight) { SortLayout(maxWidth.value, maxHeight.value) }
            fun home(i: Int): Offset = layout.at(round.items[i].x, round.items[i].y)

            fun select(i: Int) {
                if (round.isSorted(i) || i in motions) return
                selected = if (selected == i) null else i
                feedback.play(Sounds.pick)
                feedback.tick()
                status = if (selected != null) "Now tap the $bin it goes in!" else look.start
            }

            fun attempt(i: Int, b: Int, from: Offset, dragged: Boolean) {
                when (round.resultOf(i, b)) {
                    SortResult.RIGHT -> {
                        val wasFocused = focusedItem == i || focusedBin != null
                        round = round.sort(i, b)
                        selected = null
                        val motion = SortMotion(SortMove.FLY, from, b)
                        motions[i] = motion
                        feedback.play(Sounds.pick)
                        status = if (round.isDone) look.done else "Into the ${look.kinds[b].bin}!"
                        scope.launch {
                            motion.anim.animateTo(1f, tween(FLY_MS, easing = FastOutSlowInEasing))
                            landed += i
                            motions.remove(i)
                            feedback.play(Sounds.chime(round.countIn(b).coerceIn(1, 5)))
                            feedback.tick()
                            hops[b].snapTo(0f)
                            hops[b].animateTo(1f, tween(HOP_MS, easing = LinearEasing))
                        }
                        if (wasFocused && keyboard) order.firstOrNull { !round.isSorted(it) }?.let { focusNext = it }
                    }
                    SortResult.WRONG -> {
                        val motion = SortMotion(if (dragged) SortMove.BACK else SortMove.NUDGE, from, b)
                        motions[i] = motion
                        feedback.play(Sounds.invalid)
                        val right = look.kinds[round.items[i].kind]
                        status = "That one goes in the ${right.bin}!"
                        scope.launch {
                            motion.anim.animateTo(1f, tween(if (dragged) BACK_MS else NUDGE_MS, easing = FastOutSlowInEasing))
                            motions.remove(i)
                        }
                        scope.launch {
                            wobbles[b].snapTo(0f)
                            wobbles[b].animateTo(1f, tween(450, easing = LinearEasing))
                        }
                    }
                    SortResult.IGNORED -> Unit
                }
            }

            fun tapBin(b: Int) {
                val s = selected
                if (s == null) {
                    status = if (look.theme == SortTheme.SHELLS) "Pick a shell first, then its basket." else "Pick one first, then its bin."
                    return
                }
                attempt(s, b, home(s), dragged = false)
            }

            fun itemUnder(p: Offset): Int? {
                val pile = layout.pile
                val r = layout.item * 0.45f
                val hit = round.itemAt((p.x - pile.left) / pile.width, (p.y - pile.top) / pile.height, r / pile.width, r / pile.height)
                return hit?.takeIf { it !in motions }
            }

            Box(
                Modifier
                    .fillMaxSize()
                    // The focus ring shows only while playing by keyboard, not after a tap.
                    .onPreviewKeyEvent { keyboard = true; false }
                    .pointerInput(Unit) {
                        awaitPointerEventScope {
                            while (true) {
                                // Only a real press, not the hover events a mouse resting nearby keeps sending.
                                if (awaitPointerEvent(PointerEventPass.Initial).type == PointerEventType.Press) keyboard = false
                            }
                        }
                    }
                    .pointerInput(layout) {
                        awaitEachGesture {
                            val down = awaitFirstDown()
                            val p = down.position / density
                            val hit = itemUnder(p)
                            if (hit == null) {
                                val b = layout.binAt(p)
                                if (b != null) tapBin(b) else if (selected != null) { selected = null; status = look.start }
                                return@awaitEachGesture
                            }
                            val grab = p - home(hit)
                            var moved = false
                            var last = p
                            while (true) {
                                val event = awaitPointerEvent()
                                val change = event.changes.firstOrNull { it.id == down.id } ?: break
                                if (!change.pressed) break
                                last = change.position / density
                                if (!moved && (last - p).getDistance() > DRAG_SLOP) {
                                    moved = true
                                    selected = null
                                    feedback.play(Sounds.pick)
                                }
                                if (moved) {
                                    drag = SortDrag(hit, last - grab)
                                    change.consume()
                                }
                            }
                            val held = drag
                            drag = null
                            if (!moved || held == null) {
                                select(hit)
                            } else {
                                val b = layout.binAt(held.at) ?: layout.binAt(last)
                                if (b != null) {
                                    attempt(hit, b, held.at, dragged = true)
                                } else {
                                    val motion = SortMotion(SortMove.BACK, held.at, 0)
                                    motions[hit] = motion
                                    scope.launch {
                                        motion.anim.animateTo(1f, tween(BACK_MS, easing = FastOutSlowInEasing))
                                        motions.remove(hit)
                                    }
                                }
                            }
                        }
                    },
            ) {
                Canvas(Modifier.fillMaxSize()) {
                    scale(density, density, Offset.Zero) {
                        val t = clock.value
                        drawSortGround(look, layout, t)
                        val s = layout.item
                        val held = drag?.item
                        for (i in round.items.indices) {
                            if (round.isSorted(i) || i == held || i in motions) continue
                            val c = home(i)
                            if (i == selected) {
                                drawGlow(c, s * 0.85f, Color(0xFFFFF2B0).copy(alpha = 0.8f))
                                drawSortItem(look, round.items[i], c, s, lift = 1f, extraTilt = 6f * sin(t * 2 * PI.toFloat() * 90))
                            } else {
                                drawSortItem(look, round.items[i], c, s)
                            }
                        }
                        val over = drag?.let { layout.binAt(it.at) }
                        for (b in 0 until SortRound.KINDS) {
                            val inside = landed.filter { round.sorted[it] == b }.map { round.items[it] }
                            drawBin(look, b, layout.bins[b], inside, hops[b].value, wobbles[b].value, if (over == b) 1f else 0f)
                        }
                        // Things on the move, and the one held, over everything.
                        for ((i, m) in motions) {
                            val p = m.anim.value
                            val mouth = layout.mouth(m.bin)
                            when (m.move) {
                                SortMove.FLY -> {
                                    val e = p
                                    val c = m.from + (mouth - m.from) * e - Offset(0f, sin(e * PI.toFloat()) * s * 0.9f)
                                    drawSortItem(look, round.items[i], c, s + (layout.binWidth * 0.36f - s) * e, lift = 1f - e)
                                }
                                SortMove.BACK -> {
                                    val home = home(i)
                                    drawSortItem(look, round.items[i], m.from + (home - m.from) * p, s, lift = 1f - p)
                                }
                                SortMove.NUDGE -> {
                                    val home = home(i)
                                    val a = sin(p * PI.toFloat())
                                    drawSortItem(look, round.items[i], home + (mouth - home) * (0.32f * a), s, lift = a)
                                }
                            }
                        }
                        drag?.let { d -> drawSortItem(look, round.items[d.item], d.at, s, lift = 1f) }
                        if (keyboard) {
                            focusedItem?.takeIf { !round.isSorted(it) }?.let {
                                val c = home(it)
                                drawSortFocus(Rect(c - Offset(s / 2, s / 2), Size(s, s)), palette.accent, s * 0.3f)
                            }
                            focusedBin?.let { drawSortFocus(layout.bins[it], palette.accent, layout.binWidth * 0.15f) }
                        }
                        drawRoundRect(Color.White.copy(alpha = 0.55f), Offset.Zero, Size(layout.width, size.height / density), CornerRadius(28f), style = Stroke(1.5f))
                    }
                }
                // One focusable button per thing in the pile, in reading order, over its place.
                for (i in order) {
                    if (round.isSorted(i)) continue
                    key(i) {
                        val item = round.items[i]
                        val c = home(i)
                        val s = layout.item
                        val name = look.nameOf(item)
                        Box(
                            Modifier
                                .offset((c.x - s / 2).dp, (c.y - s / 2).dp)
                                .size(s.dp)
                                .focusRequester(itemFocus[i])
                                .onFocusChanged { if (it.isFocused) focusedItem = i else if (focusedItem == i) focusedItem = null }
                                .onKeyEvent { event ->
                                    val press = event.key == Key.Enter || event.key == Key.Spacebar || event.key == Key.NumPadEnter
                                    if (press && event.type == KeyEventType.KeyUp) select(i)
                                    press
                                }
                                .semantics {
                                    role = Role.Button
                                    contentDescription = name
                                    this.selected = selected == i
                                    onClick(label = if (selected == i) "Put down" else "Pick up") { select(i); true }
                                    customActions = look.kinds.mapIndexed { b, k ->
                                        CustomAccessibilityAction("Sort into the ${k.bin}") { attempt(i, b, home(i), dragged = false); true }
                                    }
                                }
                                .focusable(),
                        )
                    }
                }
                for (b in 0 until SortRound.KINDS) {
                    val r = layout.bins[b]
                    val k = look.kinds[b]
                    val count = round.countIn(b)
                    Box(
                        Modifier
                            .offset(r.left.dp, r.top.dp)
                            .size(r.width.dp, r.height.dp)
                            .focusRequester(binFocus[b])
                            .onFocusChanged { if (it.isFocused) focusedBin = b else if (focusedBin == b) focusedBin = null }
                            .onKeyEvent { event ->
                                val press = event.key == Key.Enter || event.key == Key.Spacebar || event.key == Key.NumPadEnter
                                if (press && event.type == KeyEventType.KeyUp) tapBin(b)
                                press
                            }
                            .semantics {
                                role = Role.Button
                                contentDescription = "${k.bin.replaceFirstChar { it.uppercase() }}, $count in it"
                                val s = selected
                                onClick(label = if (s != null) "Put the ${look.nameOf(round.items[s])} here" else "Pick something first") { tapBin(b); true }
                            }
                            .focusable(),
                        contentAlignment = Alignment.BottomCenter,
                    ) {
                        Text(
                            k.name.replaceFirstChar { it.uppercase() },
                            color = palette.text,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.ExtraBold,
                            maxLines = 1,
                            modifier = Modifier
                                .padding(bottom = (r.height * 0.06f).dp)
                                .frosted(palette, RoundedCornerShape(50), elevation = 2.dp)
                                .padding(horizontal = 10.dp, vertical = 2.dp)
                                .clearAndSetSemantics { },
                        )
                    }
                }
            }
        }
        Spacer(Modifier.height(10.dp))
        Row(
            Modifier
                .widthIn(max = 460.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Text(
                status,
                color = palette.text,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center,
                maxLines = 1,
                modifier = Modifier.weight(1f, fill = false).semantics { liveRegion = LiveRegionMode.Polite },
            )
            Text(
                "${round.sorted.size}/${round.items.size}",
                color = palette.accent,
                fontSize = 16.sp,
                fontWeight = FontWeight.Black,
                maxLines = 1,
            )
        }
    }
}

/** Item [item] held by a finger at [at] (dp). */
private class SortDrag(val item: Int, val at: Offset)

/** How a thing is moving: into a bin, back to the pile after a drag, or a little way toward a wrong bin and back. */
private enum class SortMove { FLY, BACK, NUDGE }

/** A thing on the move from [from] (dp), with bin [bin] as the goal or the wrong bin it tried. */
private class SortMotion(val move: SortMove, val from: Offset, val bin: Int) {
    val anim = Animatable(0f)
}

/** How far a press has to move before it counts as a drag, in dp. */
private const val DRAG_SLOP = 8f

private const val FLY_MS = 420
private const val BACK_MS = 380
private const val NUDGE_MS = 520
private const val HOP_MS = 360
