package io.colorsand.ui.arena

import androidx.compose.foundation.layout.Spacer
import androidx.compose.runtime.Composable
import androidx.compose.runtime.State
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.drawWithCache
import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.PathEffect
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.clipPath
import androidx.compose.ui.graphics.drawscope.scale
import androidx.compose.ui.graphics.drawscope.translate
import androidx.compose.ui.graphics.lerp
import kotlin.math.abs
import kotlin.math.cos
import kotlin.math.max
import kotlin.math.min
import kotlin.math.sin

/**
 * Mars: late afternoon on the red planet. A butterscotch sky darkening to a dusky top with the first stars, a
 * small pale sun with a cool blue halo, Earth as a blue evening star, Phobos crossing slowly and Deimos hanging still, far mesas and crater
 * rims, a glass dome habitat with a blinking beacon on the horizon, rust-red plains with craters and dark
 * rocks, dust devils wandering over the plain and haze drifting low.
 */
@Composable
internal fun MarsScene(grade: SceneGrade, modifier: Modifier = Modifier) {
    val clock = rememberSceneClock()
    Spacer(
        modifier.drawWithCache {
            val art = MarsArt(size, grade)
            onDrawBehind { art.draw(this, clock) }
        },
    )
}

/** Everything Mars draws, built once per size and grade; [draw] only moves it. */
private class MarsArt(size: Size, private val g: SceneGrade) {
    private val w = size.width
    private val h = size.height
    private val u = min(w, h * 0.6f)

    private val horizonY = h * 0.75f
    private val haze = Color(0xFFF1C7A0)
    private fun far(c: Long, amount: Float) = g(lerp(Color(c), haze, amount))

    private val sky = Brush.verticalGradient(
        0f to g(0xFF2B2140), 0.14f to g(0xFF4A2F52), 0.32f to g(0xFF8E525E), 0.5f to g(0xFFC98066),
        0.65f to g(0xFFE7AB7E), 0.75f to g(haze),
        startY = 0f, endY = h,
    )

    private class Star(val at: Offset, val radius: Float, val bright: Float, val cycles: Int, val phase: Float)

    private val stars = SceneRandom(131).let { r ->
        List(40) {
            val f = r.next()
            val y = h * 0.28f * f * f
            Star(Offset(w * r.next(), y), u * r.next(0.002f, 0.005f), 1f - y / (h * 0.3f), 20 + (r.next() * 40).toInt(), r.next())
        }
    }
    private val starColor = g(0xFFFFF4EC)

    // Earth: a small blue evening star.
    private val earthAt = Offset(w * 0.62f, h * 0.2f)
    private val earth = g(0xFF9CC8FF)

    // The small, pale sun with the blue halo of a Martian sunset.
    private val sunCenter = Offset(w * 0.84f, h * 0.7f)
    private val sunWarm = g(0xFFF8D6B0)
    private val sunBlue = g(0xFFC9DDE6)
    private val sunDisk = Brush.radialGradient(
        0f to g(0xFFFFFEF8), 0.7f to g(0xFFF6F8F4), 1f to g(Color(0x00F6F8F4)), center = Offset.Zero, radius = u * 0.03f,
    )

    // Thin, high ice clouds drifting in the upper sky.
    private class Cloud(val path: Path, val y: Float, val width: Float, val start: Float)

    private val clouds = SceneRandom(141).let { r ->
        List(3) { k ->
            val width = u * r.next(0.5f, 0.8f)
            val path = Path().apply {
                repeat(4) {
                    val x = width * r.next(-0.5f, 0.3f)
                    val y = u * r.next(-0.012f, 0.012f)
                    val len = width * r.next(0.35f, 0.6f)
                    moveTo(x, y)
                    quadraticTo(x + len * 0.5f, y - u * 0.01f, x + len, y + u * 0.003f)
                }
            }
            Cloud(path, h * (0.2f + 0.08f * k), width, r.next())
        }
    }
    private val cloudColor = g(0xFFF4E6EE)

    // Phobos crosses the sky once a loop; Deimos hangs still.
    private val phobos = blob(SceneRandom(137), 10, 1f)
    private val deimos = blob(SceneRandom(139), 8, 1f)
    private val moonLit = g(0xFFD9C3B0)
    private val moonShade = g(0xFF7E6460)
    private val moonCrater = g(0xFF9C8379)

    // Far ranges and mesas fading into the haze.
    private val range = Ridge(w, horizonY, u * 0.05f, 1.3f, 0.12f).fill(horizonY + 2f)
    private val rangeColor = far(0xFFB27474, 0.55f)
    private val mesas = Path().apply {
        for ((a, b, height) in listOf(Triple(0.4f, 0.58f, 0.055f), Triple(0.82f, 1.05f, 0.04f), Triple(-0.08f, 0.06f, 0.035f))) {
            val x0 = w * a
            val x1 = w * b
            val top = horizonY - u * height
            moveTo(x0 - u * 0.04f, horizonY + 1f)
            cubicTo(x0 - u * 0.01f, horizonY - u * height * 0.2f, x0, top + u * height * 0.3f, x0 + u * 0.012f, top)
            lineTo(x1 - u * 0.012f, top)
            cubicTo(x1, top + u * height * 0.3f, x1 + u * 0.01f, horizonY - u * height * 0.2f, x1 + u * 0.04f, horizonY + 1f)
            close()
        }
    }
    private val mesaColor = far(0xFFA45A52, 0.35f)
    private val mesaShade = far(0xFF7A3E42, 0.3f)
    private val horizonHaze = Brush.verticalGradient(
        0f to Color.Transparent, 0.6f to g(haze.copy(alpha = 0.5f)), 1f to Color.Transparent,
        startY = horizonY - u * 0.04f, endY = horizonY + u * 0.02f,
    )

    // The dome habitat on the horizon.
    private val domeAt = Offset(w * 0.2f, horizonY + u * 0.012f)
    private val domeSize = u * 0.09f
    private val domeGlass = Brush.verticalGradient(
        0f to far(0xFFD8F0F6, 0.15f), 1f to far(0xFF8FB9C9, 0.15f), startY = domeAt.y - domeSize, endY = domeAt.y,
    )
    private val domeRib = far(0xFF6E8C99, 0.2f)
    private val hull = far(0xFFE4DDD6, 0.2f)
    private val hullShade = far(0xFFA79C98, 0.2f)
    private val window = g(0xFFFFE08A)
    private val beacon = g(0xFFFF5A4A)

    // Plains: a lighter middle distance, a darker, nearer stretch.
    private val midPlain = Ridge(w, h * 0.79f, u * 0.02f, 1.6f, 0.4f).fill(h)
    private val midBrush = Brush.verticalGradient(
        0f to far(0xFFDA8A5E, 0.25f), 1f to far(0xFFC86E48, 0.1f), startY = h * 0.76f, endY = h * 0.88f,
    )
    private val nearRidge = Ridge(w, h * 0.865f, u * 0.025f, 1.1f, 0.72f)
    private val nearPlain = nearRidge.fill(h)
    private val nearBrush = Brush.verticalGradient(
        0f to g(0xFFC9653C), 0.4f to g(0xFFB95733), 1f to g(0xFF9E472B), startY = h * 0.84f, endY = h,
    )
    private val nearRim = nearRidge.line()
    private val rimColor = g(0xFFE69A6C)

    private class Crater(val at: Offset, val width: Float)

    private val craters = listOf(
        Crater(Offset(w * 0.64f, h * 0.815f), u * 0.16f),
        Crater(Offset(w * 0.1f, h * 0.905f), u * 0.17f),
        Crater(Offset(w * 0.86f, h * 0.95f), u * 0.2f),
    )
    private val craterInside = g(0xFF8E3F27)
    private val craterLight = g(0xFFE8996A)

    private class Rock(val at: Offset, val size: Float, val path: Path)

    private val rocks = SceneRandom(149).let { r ->
        listOf(
            Offset(w * 0.04f, h * 0.84f) to 0.05f, Offset(w * 0.32f, h * 0.805f) to 0.022f, Offset(w * 0.93f, h * 0.845f) to 0.045f,
            Offset(w * 0.78f, h * 0.81f) to 0.02f, Offset(w * 0.45f, h * 0.975f) to 0.03f, Offset(w * 0.24f, h * 0.955f) to 0.018f,
        ).map { (at, s) -> Rock(at, u * s, blob(r, 9, 0.55f)) }
    }
    private val rockLit = g(0xFF7A4A3C)
    private val rockShade = g(0xFF4A2C28)
    private val pebbles = SceneRandom(151).let { r ->
        List(14) { Offset(w * r.next(), h * r.next(0.88f, 0.995f)) to u * r.next(0.004f, 0.008f) }
    }

    // Dust devils wandering over the middle distance.
    private class Devil(val laps: Int, val start: Float, val height: Float, val toRight: Boolean)

    private val devils = listOf(Devil(1, 0.35f, u * 0.2f, true), Devil(1, 0.8f, u * 0.13f, false))
    private val dust = g(0xFFF4C29A)
    private val devilDust = g(0xFFA9573A)

    private class Haze(val y: Float, val length: Float, val laps: Int, val start: Float)

    private val hazes = SceneRandom(157).let { r ->
        List(5) { Haze(h * r.next(0.78f, 0.9f), u * r.next(0.3f, 0.6f), 1 + (r.next() * 2).toInt(), r.next()) }
    }

    // Rover tracks curving in from the left across the near plain.
    private val tracks = Path().apply {
        for (dy in listOf(0f, u * 0.025f)) {
            moveTo(-u * 0.05f, h * 0.9f + dy)
            cubicTo(w * 0.25f, h * 0.875f + dy, w * 0.45f, h * 0.88f + dy * 0.8f, w * 0.68f, h * 0.865f + dy * 0.6f)
        }
    }
    private val trackStroke = Stroke(u * 0.009f, cap = StrokeCap.Round)
    private val treadStroke = Stroke(u * 0.006f, pathEffect = PathEffect.dashPathEffect(floatArrayOf(u * 0.003f, u * 0.006f)))
    private val trackColor = g(0xFF7E3520)

    private val shade = vignette(w, h, g(Color(0x52301018)))

    fun draw(scope: DrawScope, clock: State<Float>) = with(scope) {
        val t = clock.value
        drawRect(sky)
        for (s in stars) {
            val twinkle = 0.55f + 0.45f * swing(t, s.cycles, s.phase)
            drawCircle(starColor.copy(alpha = (s.bright * twinkle).coerceIn(0f, 1f)), s.radius, s.at)
            if (s.radius > u * 0.0042f) {
                val l = s.radius * 3.2f * twinkle
                val c = starColor.copy(alpha = s.bright * twinkle * 0.6f)
                drawLine(c, s.at - Offset(l, 0f), s.at + Offset(l, 0f), s.radius * 0.5f)
                drawLine(c, s.at - Offset(0f, l), s.at + Offset(0f, l), s.radius * 0.5f)
            }
        }
        drawGlow(earthAt, u * 0.025f, earth.copy(alpha = 0.5f + 0.15f * swing(t, 30)))
        drawCircle(earth, u * 0.0045f, earthAt)
        drawMoons(t)

        for (c in clouds) {
            val x = -c.width + drift(t, 1, c.start) * (w + 2 * c.width)
            translate(x, c.y) {
                drawPath(c.path, cloudColor, alpha = 0.1f, style = Stroke(u * 0.024f, cap = StrokeCap.Round))
                drawPath(c.path, cloudColor, alpha = 0.16f, style = Stroke(u * 0.008f, cap = StrokeCap.Round))
            }
        }
        drawGlow(sunCenter, u * 1.1f, sunWarm.copy(alpha = 0.55f))
        drawGlow(sunCenter, u * 0.3f, sunBlue.copy(alpha = 0.9f))
        translate(sunCenter.x, sunCenter.y) { drawCircle(sunDisk, u * 0.03f, Offset.Zero) }

        drawPath(range, rangeColor)
        drawRect(horizonHaze, Offset(0f, horizonY - u * 0.04f), Size(w, u * 0.06f))
        drawPath(mesas, mesaColor)
        clipPath(mesas) { translate(u * 0.025f, 0f) { drawPath(mesas, mesaShade, alpha = 0.55f) } }
        drawDome(t)

        drawPath(midPlain, midBrush)
        drawCrater(craters[0], far = true)
        for (d in devils) drawDevil(t, d)
        drawPath(nearPlain, nearBrush)
        drawPath(nearRim, rimColor, alpha = 0.45f, style = Stroke(u * 0.004f, cap = StrokeCap.Round))
        drawPath(tracks, trackColor, alpha = 0.14f, style = trackStroke)
        drawPath(tracks, trackColor, alpha = 0.14f, style = treadStroke)
        drawCrater(craters[1], far = false)
        drawCrater(craters[2], far = false)
        for ((at, r) in pebbles) drawCircle(rockShade.copy(alpha = 0.6f), r, at)
        for (rock in rocks) drawRock(rock)
        drawHaze(t)
        drawRect(shade)
    }

    private fun DrawScope.drawMoons(t: Float) {
        val s = u * 0.032f
        val p = drift(t, 1, 0.3f)
        val at = Offset(-s * 2 + p * (w + s * 4), h * 0.15f - u * 0.06f * sin(PI_F * p))
        drawMoon(at, s, phobos)
        drawMoon(Offset(w * 0.2f, h * 0.085f), u * 0.013f, deimos)
    }

    /** A potato-shaped moon lit from the low sun, below and to the right. */
    private fun DrawScope.drawMoon(at: Offset, s: Float, shape: Path) {
        drawGlow(at, s * 2.2f, moonLit.copy(alpha = 0.18f))
        translate(at.x, at.y) {
            scale(s, s * 0.82f, Offset.Zero) {
                drawPath(shape, moonLit)
                clipPath(shape) {
                    translate(-0.35f, -0.3f) { drawPath(shape, moonShade, alpha = 0.75f) }
                    drawCircle(moonCrater, 0.18f, Offset(0.25f, 0.2f))
                    drawCircle(moonCrater, 0.1f, Offset(-0.1f, 0.45f))
                }
            }
        }
    }

    private fun DrawScope.drawDome(t: Float) {
        val s = domeSize
        val base = domeAt
        drawOval(Color.Black.copy(alpha = 0.12f), Offset(base.x - s * 1.4f, base.y - s * 0.08f), Size(s * 3.2f, s * 0.22f))
        // A module and a tunnel on the right.
        drawRoundRect(hullShade, Offset(base.x + s * 0.8f, base.y - s * 0.32f), Size(s * 0.5f, s * 0.22f), CornerRadius(s * 0.1f))
        drawRoundRect(hull, Offset(base.x + s * 1.2f, base.y - s * 0.55f), Size(s * 0.7f, s * 0.55f), CornerRadius(s * 0.18f))
        drawRoundRect(hullShade, Offset(base.x + s * 1.2f, base.y - s * 0.2f), Size(s * 0.7f, s * 0.2f), CornerRadius(s * 0.1f))
        for (k in 0..1) drawCircle(window, s * 0.06f, Offset(base.x + s * (1.4f + 0.28f * k), base.y - s * 0.34f))
        // The mast with its blinking beacon.
        val mastTop = Offset(base.x - s * 0.7f, base.y - s * 1.45f)
        drawLine(hullShade, Offset(mastTop.x, base.y - s * 0.3f), mastTop, s * 0.05f)
        drawLine(hullShade, mastTop + Offset(-s * 0.12f, s * 0.2f), mastTop + Offset(s * 0.12f, s * 0.2f), s * 0.04f)
        val blink = max(0f, swing(t, 50))
        drawGlow(mastTop, s * 0.35f, beacon.copy(alpha = 0.7f * blink))
        drawCircle(beacon, s * 0.05f, mastTop)
        // The dome: glass over a ring of hull.
        drawArc(domeGlass, 180f, 180f, true, Offset(base.x - s, base.y - s), Size(s * 2, s * 2))
        for (a in listOf(-0.5f, 0f, 0.5f)) {
            drawArc(domeRib, 180f, 180f, false, Offset(base.x - s * abs(a) * 1.6f - s * 0.001f, base.y - s), Size(s * abs(a) * 3.2f + s * 0.002f, s * 2), style = Stroke(s * 0.03f))
        }
        drawLine(domeRib, Offset(base.x - s * 0.87f, base.y - s * 0.5f), Offset(base.x + s * 0.87f, base.y - s * 0.5f), s * 0.03f)
        drawArc(Color.White.copy(alpha = 0.55f), 200f, 50f, false, Offset(base.x - s * 0.8f, base.y - s * 0.8f), Size(s * 1.6f, s * 1.6f), style = Stroke(s * 0.07f, cap = StrokeCap.Round))
        drawRoundRect(hull, Offset(base.x - s * 1.05f, base.y - s * 0.14f), Size(s * 2.1f, s * 0.16f), CornerRadius(s * 0.06f))
    }

    private fun DrawScope.drawCrater(c: Crater, far: Boolean) {
        val cw = c.width
        val ch = cw * 0.26f
        val a = if (far) 0.45f else 0.7f
        // A raised rim lit from the sun on the right, a shaded bowl inside.
        drawOval(craterLight.copy(alpha = 0.35f * a), Offset(c.at.x - cw * 0.58f, c.at.y - ch * 0.62f), Size(cw * 1.16f, ch * 1.24f))
        drawOval(craterInside.copy(alpha = 0.55f * a), Offset(c.at.x - cw / 2, c.at.y - ch / 2), Size(cw, ch))
        drawArc(craterLight.copy(alpha = 0.7f * a), 20f, 140f, false, Offset(c.at.x - cw / 2, c.at.y - ch / 2), Size(cw, ch), style = Stroke(cw * 0.025f, cap = StrokeCap.Round))
        drawArc(craterInside.copy(alpha = 0.6f * a), 200f, 140f, false, Offset(c.at.x - cw * 0.47f, c.at.y - ch * 0.45f), Size(cw * 0.94f, ch * 0.9f), style = Stroke(cw * 0.03f, cap = StrokeCap.Round))
    }

    private fun DrawScope.drawRock(r: Rock) {
        drawOval(Color.Black.copy(alpha = 0.16f), Offset(r.at.x - r.size * 0.4f, r.at.y - r.size * 0.12f), Size(r.size * 2f, r.size * 0.3f))
        translate(r.at.x, r.at.y - r.size * 0.45f) {
            scale(r.size, r.size * 0.75f, Offset.Zero) {
                drawPath(r.path, rockLit)
                clipPath(r.path) { translate(-0.25f, 0.25f) { drawPath(r.path, rockShade) } }
                drawCircle(Color.White.copy(alpha = 0.12f), 0.3f, Offset(0.25f, -0.35f))
            }
        }
    }

    /** A twisting funnel of dust: stacked puffs widening upward, swaying, fading in and out as it crosses. */
    private fun DrawScope.drawDevil(t: Float, d: Devil) {
        val p = drift(t, d.laps, d.start)
        val span = d.height * 0.5f
        val x0 = if (d.toRight) -span + p * (w + 2 * span) else w + span - p * (w + 2 * span)
        val ground = h * 0.79f + d.height * 0.06f
        val fade = (0.5f - 0.5f * cos(TAU * p)).coerceIn(0f, 1f)
        if (fade < 0.02f) return
        drawOval(devilDust.copy(alpha = 0.2f * fade), Offset(x0 - d.height * 0.22f, ground - d.height * 0.05f), Size(d.height * 0.44f, d.height * 0.1f))
        val puffs = 14
        for (k in 0 until puffs) {
            val f = k / (puffs - 1f)
            val y = ground - d.height * f
            val half = d.height * (0.05f + 0.2f * f * f)
            val x = x0 + d.height * 0.12f * f * swing(t, 24, d.start + f * 0.3f)
            drawOval(devilDust.copy(alpha = (0.14f - 0.09f * f) * fade), Offset(x - half, y - d.height * 0.11f), Size(half * 2, d.height * 0.22f))
        }
    }

    private fun DrawScope.drawHaze(t: Float) {
        for (hz in hazes) {
            val p = drift(t, hz.laps, hz.start)
            val x = -hz.length + p * (w + 2 * hz.length)
            val a = (0.5f - 0.5f * cos(TAU * p)) * 0.22f
            drawOval(
                Brush.horizontalGradient(0f to Color.Transparent, 0.5f to dust.copy(alpha = a), 1f to Color.Transparent, startX = x, endX = x + hz.length),
                Offset(x, hz.y - u * 0.01f),
                Size(hz.length, u * 0.02f),
            )
        }
    }
}

private const val PI_F = kotlin.math.PI.toFloat()
