/**
 * Dig deeper: a cross-section of [arena]'s ground that scrolls down as the digger goes, under the pyramid in the
 * Desert (loose sand, packed sand, clay, old rock, with gems, pottery and fossils) or the excavator on the Building
 * Site (topsoil, gravel, clay crossed by old pipes, bedrock, with coins, marbles and a toy car). Tap or drag to dig:
 * below the digger digs down, beside it digs sideways. Hard tiles take two or three taps and crack as they go. Finds
 * along the way go in the tray; breaking into the bottom row opens the glowing chamber (a golden scarab, or the time
 * capsule) and calls [onFinished]. Arrow keys dig left, right and down; Enter, Space and a screen reader's "Dig down"
 * dig down. [seed] lays out the ground.
 */
@Composable
fun DigDeeperGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { DeepLook.of(arena, grade) }
    var round by remember(seed, arena) { mutableStateOf(DigDeeper.start(seed, slabs = true)) }
    var status by remember(seed, arena) { mutableStateOf(look.start) }
    var doneAt by remember(seed, arena) { mutableStateOf<Float?>(null) }
    var layout by remember(seed, arena) { mutableStateOf<DeepLayout?>(null) }
    var frame by remember(seed, arena) { mutableStateOf(0) }
    val view = remember(seed, arena) { DeepView(round.x.toFloat()) }
    val focus = remember { FocusRequester() }
    LaunchedEffect(focus) { runCatching { focus.requestFocus() } }

    fun dig(way: DigWay) {
        val (next, event) = round.dig(way)
        if (event == DeepEvent.NONE) return
        val before = round
        round = next
        if (way.dx != 0) view.facing = way.dx
        if (event == DeepEvent.WALK) {
            feedback.play(Sounds.click)
            return
        }
        view.swingAt = view.time
        val tx = before.x + way.dx
        val ty = before.y + way.dy
        val layer = look.layers[before.tile(tx, ty).layer]
        layout?.let { l ->
            val c = Offset(l.left(tx) + l.cell / 2, l.top(ty.toFloat(), view.camera) + l.cell * 0.4f)
            val n = if (event == DeepEvent.CRACK) 4 else 8
            for (k in 0 until n) {
                val r = noise(tx * 13 + ty * 7 + k + before.hits.sum())
                view.chips += Chip(c.x, c.y, (r - 0.5f) * l.cell * 5f, -l.cell * (1.5f + 2f * noise(k + ty)), if (k % 2 == 0) layer.base else layer.dark)
            }
        }
        feedback.tick()
        when (event) {
            DeepEvent.CRACK -> {
                feedback.play(Sounds.pick)
                status = layer.name
            }
            DeepEvent.BREAK -> {
                feedback.play(Sounds.land)
                status = layer.name
            }
            DeepEvent.FIND -> {
                val find = next.found.last()
                view.pops += Pop(find, tx, ty, view.time)
                feedback.play(Sounds.chime(next.found.size.coerceAtMost(5)))
                feedback.confirm()
                status = "You found a ${look.finds[find].name}!"
            }
            DeepEvent.CHAMBER -> {
                feedback.play(Sounds.land)
                feedback.play(Sounds.chime(6))
                feedback.confirm()
                doneAt = view.time
                status = look.found
            }
            else -> Unit
        }
    }
    /** Digs toward the tile at world ([col], [row]): down if it is lower than the digger, else to its side. */
    fun digToward(col: Int, row: Int) {
        if (round.isDone) return
        when {
            row > round.y && (col == round.x || row > round.y + 1 || round.y < 0) -> dig(DigWay.DOWN)
            col < round.x -> dig(DigWay.LEFT)
            col > round.x -> dig(DigWay.RIGHT)
            else -> dig(DigWay.DOWN)
        }
    }

    LaunchedEffect(view) {
        var last = -1L
        while (true) {
            withFrameNanos { now ->
                val dt = if (last < 0) 0f else ((now - last) / 1_000_000_000f).coerceAtMost(0.1f)
                last = now
                view.step(dt, round, layout, doneAt != null)
                frame++
            }
        }
    }
    LaunchedEffect(doneAt != null) {
        if (doneAt != null) {
            delay(FINISH_MS)
            onFinished()
        }
    }

    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        Canvas(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .onSizeChanged { layout = DeepLayout(it.width.toFloat(), it.height.toFloat(), round.columns) }
                .semantics {
                    contentDescription = look.description
                    stateDescription = if (round.isDone) look.found else "Depth ${round.y + 1} of ${round.depth}, ${round.found.size} finds"
                    onClick(label = "Dig down") { dig(DigWay.DOWN); true }
                    customActions = listOf(
                        CustomAccessibilityAction("Dig left") { dig(DigWay.LEFT); true },
                        CustomAccessibilityAction("Dig right") { dig(DigWay.RIGHT); true },
                    )
                }
                .onKeyEvent { event ->
                    val way = when (event.key) {
                        Key.DirectionLeft -> DigWay.LEFT
                        Key.DirectionRight -> DigWay.RIGHT
                        Key.DirectionDown -> DigWay.DOWN
                        else -> null
                    }
                    val press = event.key == Key.Enter || event.key == Key.Spacebar || event.key == Key.NumPadEnter
                    when {
                        way != null -> { if (event.type == KeyEventType.KeyDown) dig(way); true }
                        press -> { if (event.type == KeyEventType.KeyUp) dig(DigWay.DOWN); true }
                        else -> false
                    }
                }
                .focusRequester(focus)
                .focusable()
                .pointerInput(seed, arena) {
                    // A tap digs toward it; a drag keeps digging as it moves onto new tiles.
                    awaitEachGesture {
                        val down = awaitFirstDown()
                        down.consume()
                        runCatching { focus.requestFocus() }
                        val l = layout ?: return@awaitEachGesture
                        var at = l.cellAt(down.position, view.camera)
                        digToward(at.first, at.second)
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            if (!change.pressed) break
                            val now = l.cellAt(change.position, view.camera)
                            if (now != at) {
                                at = now
                                digToward(now.first, now.second)
                            }
                            change.consume()
                        }
                    }
                },
        ) {
            if (frame < 0) return@Canvas
            val l = layout ?: DeepLayout(size.width, size.height, round.columns)
            val reveal = doneAt?.let { ((view.time - it) / 0.8f).coerceIn(0f, 1f) } ?: 0f
            val swing = ((view.time - view.swingAt) / SWING_S).coerceIn(0f, 1f).let { if (it >= 1f) 0f else it }
            drawDigDeeper(look, grade, l, round, view.camera, view.x, view.y, view.facing, swing, reveal, view.time, view.chips, view.pops)
        }
        Spacer(Modifier.height(10.dp))
        FindsRow(look, grade, round)
        Spacer(Modifier.height(8.dp))
        Row(
            Modifier
                .widthIn(max = 460.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Text(
                status,
                color = palette.text,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center,
                maxLines = 1,
                modifier = Modifier.weight(1f, fill = false).semantics { liveRegion = LiveRegionMode.Polite },
            )
            Text(
                "${(round.y + 1).coerceIn(0, round.depth)}/${round.depth}",
                color = palette.accent,
                fontSize = 16.sp,
                fontWeight = FontWeight.Black,
                maxLines = 1,
                modifier = Modifier.semantics { contentDescription = "Depth ${(round.y + 1).coerceIn(0, round.depth)} of ${round.depth}" },
            )
        }
    }
}

/** The finds in a row of small round slots: faint until dug up, then the find itself; with a count. */
@Composable
private fun FindsRow(look: DeepLook, grade: SceneGrade, round: DigDeeper) {
    val palette = LocalPalette.current
    Row(
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        verticalAlignment = Alignment.CenterVertically,
        modifier = Modifier.semantics(mergeDescendants = true) {
            contentDescription = "${round.found.size} of ${DigDeeper.FINDS} finds: " +
                if (round.found.isEmpty()) "none yet" else round.found.joinToString { look.finds[it].name }
        },
    ) {
        look.finds.forEachIndexed { i, find ->
            val found = i in round.found
            Box(Modifier.size(40.dp).frosted(palette, CircleShape, elevation = 3.dp), contentAlignment = Alignment.Center) {
                Canvas(Modifier.fillMaxSize().padding(5.dp)) {
                    val unit = size.minDimension / 100f
                    scale(unit, unit, Offset.Zero) {
                        if (found) find.draw(this, grade) else silhouette(Color.Black.copy(alpha = 0.16f)) { find.draw(this, grade) }
                    }
                }
            }
        }
        Text("${round.found.size}", color = palette.accent, fontSize = 18.sp, fontWeight = FontWeight.Black)
    }
}

/** The moving parts of the dig between taps: where the digger and camera are drawn, its swing, chips and pops. */
private class DeepView(var x: Float) {
    var y = -1f
    var camera = -DEEP_SKY
    var facing = 1
    var time = 0f
    var swingAt = -10f
    val chips = mutableListOf<Chip>()
    val pops = mutableListOf<Pop>()

    fun step(dt: Float, round: DigDeeper, layout: DeepLayout?, done: Boolean) {
        time += dt
        // In the chamber the digger stands on its floor, to the side of the prize.
        val tx = if (done) (if (round.x >= round.columns / 2) round.columns / 2 + 1.7f else round.columns / 2 - 1.7f) else round.x.toFloat()
        val ty = if (done) round.depth + DEEP_CHAMBER - 1.15f else round.y.toFloat()
        val follow = (dt * 12f).coerceAtMost(1f)
        x += (tx - x) * follow
        y += (ty - y) * (dt * (if (done) 4f else 12f)).coerceAtMost(1f)
        if (layout != null) {
            val target = layout.cameraFor(if (done) round.depth + DEEP_CHAMBER else y, round.depth)
            camera += (target - camera) * (dt * 5f).coerceAtMost(1f)
            val gravity = layout.cell * 14f
            for (c in chips) {
                c.age += dt
                c.vy += gravity * dt
                c.x += c.vx * dt
                c.y += c.vy * dt
            }
        }
        chips.removeAll { it.age > CHIP_S }
        pops.removeAll { time - it.at > DIG_POP_S }
    }
}

/** How long a swing of the pick or bucket takes, in seconds. */
private const val SWING_S = 0.22f

/** How long the open chamber shows before the result card, in milliseconds. */
private const val FINISH_MS = 2600L
