/**
 * Keepsake memory: twelve cards face down, six pairs of keepsakes under them (souvenirs from every arena on woven rug
 * tiles in the Desert's tent, the alien's things on riveted metal plates under Mars's stars). Tap a card and it
 * flips over; tap a second, and a pair hops and glows while a miss flips back after a moment. No move limit, no
 * timer: finding all six pairs ends with a little flourish and calls [onFinished]. [seed] deals the cards.
 * Every card is its own button, so screen readers and keyboards can play too.
 */
@Composable
fun KeepsakeMemoryGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { MemoryLook.of(arena, grade) }
    var round by remember(seed) { mutableStateOf(KeepsakeMemory.start(seed, look.faces.size)) }
    var status by remember(seed) { mutableStateOf(MemoryStatus.START) }
    var lastFace by remember(seed) { mutableStateOf<MemoryFace?>(null) }
    val hops = remember(seed) { List(round.cards) { Animatable(0f) } }
    val shakes = remember(seed) { List(round.cards) { Animatable(1f) } }
    val pops = remember(seed) { List(look.faces.size) { Animatable(0f) } }
    val finale = remember(seed) { Animatable(0f) }
    var keyboard by remember { mutableStateOf(false) }
    val clock = rememberSceneClock()
    val scope = rememberCoroutineScope()

    fun turn(card: Int) {
        val next = round.turn(card)
        if (next === round) return
        val wasPairs = round.pairsFound
        round = next
        feedback.play(Sounds.pick)
        feedback.tick()
        val face = look.faces[next.faces[card]]
        lastFace = face
        when {
            next.pairsFound > wasPairs -> {
                status = if (next.isDone) MemoryStatus.ALL_FOUND else MemoryStatus.PAIR
                val twin = next.twinOf(card)
                scope.launch {
                    // Once the second card has turned over.
                    delay(FLIP_MS.toLong())
                    feedback.play(Sounds.chime(next.pairsFound))
                    feedback.confirm()
                    launch { pops[next.faces[card]].animateTo(1f, tween(500, easing = FastOutSlowInEasing)) }
                    for (c in listOf(twin, card)) launch {
                        hops[c].snapTo(0f)
                        hops[c].animateTo(1f, tween(HOP_MS, easing = LinearEasing))
                    }
                }
            }
            next.miss != null -> {
                status = MemoryStatus.MISS
                val (a, b) = next.miss
                scope.launch {
                    delay(FLIP_MS.toLong())
                    for (c in listOf(a, b)) launch {
                        shakes[c].snapTo(0f)
                        shakes[c].animateTo(1f, tween(420, easing = LinearEasing))
                    }
                }
            }
            else -> status = MemoryStatus.FIRST
        }
    }

    // A miss stays up for a moment, then both cards turn back down.
    LaunchedEffect(round.miss) {
        if (round.miss != null) {
            delay(MISS_SHOW_MS)
            round = round.settle()
            feedback.play(Sounds.click)
        }
    }
    LaunchedEffect(round.isDone) {
        if (round.isDone) {
            delay(FLIP_MS + HOP_MS.toLong())
            feedback.play(Sounds.chime(8))
            finale.animateTo(1f, tween(FINALE_MS, easing = LinearEasing))
            onFinished()
        }
    }

    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        BoxWithConstraints(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                // The focus ring shows only while playing by keyboard, not after a tap.
                .onPreviewKeyEvent { keyboard = true; false }
                .pointerInput(Unit) {
                    awaitPointerEventScope {
                        while (true) {
                            awaitPointerEvent(PointerEventPass.Initial)
                            keyboard = false
                        }
                    }
                },
        ) {
            val pad = 14f
            // Room over the cards for the tent's valance.
            val top = pad + if (look.style == MemoryStyle.RUG) 14f else 0f
            val gap = 10f
            val layout = MemoryLayout(maxWidth.value - 2 * pad, maxHeight.value - pad - top, round.cards, gap)
            val grid = layout.bounds.translate(Offset(pad, top))
            Canvas(Modifier.fillMaxSize()) {
                val d = density
                val panel = Rect(
                    (grid.left - pad) * d, (grid.top - top) * d, (grid.right + pad) * d, (grid.bottom + pad) * d,
                )
                drawMemoryBackdrop(look, panel, 22f * d, clock.value)
            }
            for (i in 0 until round.cards) {
                val r = layout.rect(i)
                Card(
                    index = i,
                    round = round,
                    look = look,
                    grade = grade,
                    clock = clock,
                    hop = hops[i],
                    shake = shakes[i],
                    finale = finale,
                    onTurn = { turn(i) },
                    keyboard = { keyboard },
                    modifier = Modifier
                        .offset((r.left + pad).dp, (r.top + top).dp)
                        .size(r.width.dp, r.height.dp),
                )
            }
            Canvas(Modifier.fillMaxSize()) {
                val d = density
                drawFlourish(grid.center * d, grid.maxDimension * d * 0.55f, finale.value, look.glow)
            }
        }
        Spacer(Modifier.height(10.dp))
        PairsTray(look, grade, round, pops)
        Spacer(Modifier.height(10.dp))
        Text(
            status.text(look, lastFace?.name),
            color = palette.text,
            fontSize = 16.sp,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center,
            maxLines = 1,
            modifier = Modifier
                .widthIn(max = 420.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp)
                .semantics { liveRegion = LiveRegionMode.Polite },
        )
    }
}

/**
 * One card: its shadow and, once found, its glow, with the card itself flipping over in 3D on top. A found card
 * hops ([hop] from 0 to 1), a miss gives a little shake ([shake] from 0 to 1), and the [finale] sends a hop
 * rippling across all of them. A button for screen readers and keyboards (Enter or Space); it shows a focus ring
 * while the [keyboard] is in use.
 */
@Composable
private fun Card(
    index: Int,
    round: KeepsakeMemory,
    look: MemoryLook,
    grade: SceneGrade,
    clock: State<Float>,
    hop: Animatable<Float, *>,
    shake: Animatable<Float, *>,
    finale: Animatable<Float, *>,
    onTurn: () -> Unit,
    keyboard: () -> Boolean,
    modifier: Modifier,
) {
    val palette = LocalPalette.current
    val up = round.isFaceUp(index)
    val found = index in round.matched
    val face = look.faces[round.faces[index]]
    val flip by animateFloatAsState(if (up) 1f else 0f, tween(FLIP_MS, easing = FastOutSlowInEasing), label = "flip")
    var focused by remember { mutableStateOf(false) }
    val focus = remember { FocusRequester() }
    // The keyboard starts on the first card (its ring shows once a key is pressed), so Tab, Enter and Space work
    // right away.
    if (index == 0) LaunchedEffect(Unit) { runCatching { focus.requestFocus() } }
    val number = index + 1
    val label = when {
        found -> "Card $number, ${face.name}, pair found"
        up -> "Card $number, ${face.name}"
        else -> "Card $number, face down"
    }
    // How high the card is off the table now: its own hop, then the finale's wave.
    fun lift(): Float {
        val own = hop.value.let { if (it > 0f && it < 1f) sin(it * PI.toFloat()) else 0f }
        val wave = (finale.value * 1.6f - index * 0.05f).let { if (it > 0f && it < 1f) sin(it * PI.toFloat()) else 0f }
        return maxOf(own, wave)
    }
    Box(
        modifier
            .onKeyEvent { event ->
                val press = event.type == KeyEventType.KeyUp && (event.key == Key.Spacebar || event.key == Key.Enter)
                if (press) onTurn()
                press
            }
            .focusRequester(focus)
            .onFocusChanged { focused = it.isFocused }
            .clickable(remember { MutableInteractionSource() }, indication = null, role = Role.Button, onClickLabel = "Turn over") { onTurn() }
            .semantics { contentDescription = label },
    ) {
        Canvas(Modifier.fillMaxSize()) {
            val l = lift()
            translate(0f, size.height * 0.04f * l) { drawCardShadow(l) }
            if (found && flip > 0.5f) drawPairGlow(look, 0.5f + 0.5f * swing(clock.value, 60, index * 0.1f))
        }
        Canvas(
            Modifier.fillMaxSize().graphicsLayer {
                rotationY = flip * 180f
                cameraDistance = 12f * density
                val l = lift()
                translationY = -size.height * 0.16f * l
                val pop = 1f + 0.06f * l
                scaleX = pop
                scaleY = pop
                val s = shake.value
                rotationZ = if (s < 1f) sin(s * 3f * PI.toFloat()) * 4f * (1f - s) else 0f
            },
        ) {
            if (flip <= 0.5f) {
                drawCardBack(look, clock.value, index)
            } else {
                // The layer is turned past its edge, so the face is drawn mirrored to read the right way round.
                scale(-1f, 1f) { drawCardFace(look, face, grade, clock.value) }
                if (found) drawPairRim(look, 0.5f + 0.5f * swing(clock.value, 60, index * 0.1f))
            }
            if (focused && keyboard()) drawFocusRing(palette.accent)
        }
    }
}

/** A slot for every pair: a faint outline of its keepsake until the pair is found, then the keepsake itself. */
@Composable
private fun PairsTray(look: MemoryLook, grade: SceneGrade, round: KeepsakeMemory, pops: List<Animatable<Float, *>>) {
    val palette = LocalPalette.current
    val found = round.matched.map { round.faces[it] }.toSet()
    Row(
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        modifier = Modifier.semantics { contentDescription = "${round.pairsFound} of ${round.pairs} pairs found" },
    ) {
        look.faces.forEachIndexed { i, face ->
            val has = i in found
            Box(Modifier.size(40.dp).frosted(palette, CircleShape, elevation = 4.dp), contentAlignment = Alignment.Center) {
                Canvas(
                    Modifier.fillMaxSize().padding(4.dp).graphicsLayer {
                        val pop = if (has) 0.6f + 0.4f * pops[i].value + 0.25f * sin(pops[i].value * PI.toFloat()) else 1f
                        scaleX = pop
                        scaleY = pop
                    },
                ) {
                    val unit = size.minDimension / 100f
                    if (has) {
                        scale(unit, unit, Offset.Zero) { drawKeepsake(face.arena, face.stage, 0f, grade) }
                    } else {
                        silhouette(Color.Black.copy(alpha = 0.18f)) {
                            scale(unit, unit, Offset.Zero) { drawKeepsake(face.arena, face.stage, 0f, grade) }
                        }
                    }
                }
            }
        }
    }
}

/** What the line under the cards says after the last turn. */
private enum class MemoryStatus {
    START, FIRST, PAIR, MISS, ALL_FOUND;

    fun text(look: MemoryLook, face: String?): String = when (this) {
        START -> look.hello
        FIRST -> "The $face! Where is its twin?"
        PAIR -> "A pair! Both cards show the $face."
        MISS -> "Not a pair. Remember where they are!"
        ALL_FOUND -> "All pairs found! What a memory!"
    }
}

/** How long a card takes to turn over, in milliseconds. */
private const val FLIP_MS = 380

/** How long a found pair's hop takes. */
private const val HOP_MS = 560

/** How long two cards that are not a pair stay face up. */
private const val MISS_SHOW_MS = 1100L

/** How long the closing flourish runs before the result card. */
private const val FINALE_MS = 1500
