/**
 * Sand flow: a cross-section of [arena]'s sand with water waiting at the top, in a toy pipe over the Playground's
 * sandbox or a spring up in the Desert's dune. Drag a finger through the sand to carve channels; the water runs
 * down and along them, pools round rocks that can't be dug, and fills the duck's tub (the duck floats up) or the
 * oasis pool (the palm perks up green). The source never runs dry, so there is no losing. Enter, Space or a screen
 * reader's tap carve the next bit of a path that always gets there. A full target calls [onFinished]; [seed] picks
 * one of three levels.
 */
@Composable
fun SandFlowGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { FlowLook.of(arena, grade) }
    val round = remember(seed, arena) { SandFlow(FlowLevel.pick(arena, seed)) }
    val start = remember(round) { round.water }
    val crumbs = remember(round) { mutableListOf<Crumb>() }
    var frame by remember(round) { mutableStateOf(0) }
    var time by remember(round) { mutableStateOf(0f) }
    var shownFill by remember(round) { mutableStateOf(0f) }
    var doneAt by remember(round) { mutableStateOf<Float?>(null) }
    var filled by remember(round) { mutableStateOf(0) }
    var carved by remember(round) { mutableStateOf(0) }
    var flowing by remember(round) { mutableStateOf(false) }
    var lastSound by remember(round) { mutableStateOf(-1f) }
    var layout by remember(round) { mutableStateOf<FlowLayout?>(null) }
    val focus = remember { FocusRequester() }
    LaunchedEffect(focus) { runCatching { focus.requestFocus() } }

    fun carveCells(cells: List<Int>) {
        if (doneAt != null) return
        val l = layout
        var any = false
        for (cell in cells) {
            if (!round.carve(cell)) continue
            any = true
            carved++
            if (l != null) {
                val c = l.center(cell)
                for (k in 0 until 3) {
                    val n = noise(cell * 11 + k + carved)
                    crumbs += Crumb(c.x, c.y, (n - 0.5f) * l.cell * 3f, -l.cell * (0.8f + n), cell + k)
                }
            }
        }
        if (any && time - lastSound > 0.12f) {
            lastSound = time
            feedback.play(Sounds.pick)
            feedback.tick()
        }
    }
    fun carveNext() = carveCells(round.solution.filter { round.cell(it) == FlowCell.SAND }.take(SandFlow.NEXT_BIT))

    LaunchedEffect(round) {
        var last = -1L
        var pending = 0f
        while (true) {
            withFrameNanos { now ->
                val dt = if (last < 0) 0f else ((now - last) / 1_000_000_000f).coerceAtMost(0.25f)
                last = now
                time += dt
                pending += dt
                while (pending >= 1f / SandFlow.STEPS_PER_SECOND) {
                    pending -= 1f / SandFlow.STEPS_PER_SECOND
                    val before = round.filled
                    round.step()
                    if (round.filled > before) {
                        val quarter = (round.fill * 4).toInt()
                        if (before == 0) feedback.play(Sounds.chime(1))
                        else if (quarter > (before.toFloat() / round.need * 4).toInt()) feedback.play(Sounds.chime(quarter + 1))
                    }
                }
                filled = round.filled
                if (!flowing && round.water > start) flowing = true
                shownFill += (round.fill - shownFill) * (dt * 5f).coerceAtMost(1f)
                if (round.isDone && doneAt == null) {
                    doneAt = time
                    feedback.play(Sounds.chime(6))
                    feedback.confirm()
                }
                val gravity = (layout?.cell ?: 30f) * 12f
                for (c in crumbs) {
                    c.age += dt
                    c.vy += gravity * dt
                    c.x += c.vx * dt
                    c.y += c.vy * dt
                }
                crumbs.removeAll { it.age > CRUMB_S }
                frame++
            }
        }
    }
    LaunchedEffect(doneAt != null) {
        if (doneAt != null) {
            delay(FINISH_MS)
            onFinished()
        }
    }

    val percent = (round.fill * 100).toInt()
    val status = when {
        doneAt != null -> look.done
        filled > 0 -> look.filling
        flowing -> look.flowing
        else -> look.start
    }

    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        Canvas(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .onSizeChanged { layout = FlowLayout(it.width.toFloat(), it.height.toFloat(), round.columns, round.rows) }
                .semantics {
                    contentDescription = look.description
                    stateDescription = "$percent percent full" + if (round.solutionLeft == 0) ", the stream is carved" else ""
                    onClick(label = "Carve the next bit of the path") { carveNext(); true }
                }
                .onKeyEvent { event ->
                    val press = event.key == Key.Enter || event.key == Key.Spacebar || event.key == Key.NumPadEnter
                    if (press && event.type == KeyEventType.KeyUp) carveNext()
                    press
                }
                .focusRequester(focus)
                .focusable()
                .pointerInput(round) {
                    // The finger carves wherever it goes, filling in between quick moves so the channel stays whole.
                    awaitEachGesture {
                        val down = awaitFirstDown()
                        down.consume()
                        // Keep the keys here: a tap on the game shouldn't move focus to the overlay behind it.
                        runCatching { focus.requestFocus() }
                        var at = down.position
                        layout?.let { carveCells(it.brush(at)) }
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            if (!change.pressed) break
                            val l = layout
                            if (l != null) {
                                val to = change.position
                                val d = hypot(to.x - at.x, to.y - at.y)
                                val n = (d / (l.cell * 0.25f)).toInt().coerceAtLeast(1)
                                for (k in 1..n) carveCells(l.brush(at + (to - at) * (k / n.toFloat())))
                                at = to
                            }
                            change.consume()
                        }
                    }
                },
        ) {
            if (frame < 0) return@Canvas
            val l = layout ?: FlowLayout(size.width, size.height, round.columns, round.rows)
            val done = doneAt?.let { ((time - it) / (FINISH_MS / 1000f)).coerceIn(0f, 1f) }
            drawSandFlow(look, grade, l, round, shownFill, time, done, crumbs)
        }
        Spacer(Modifier.height(12.dp))
        Row(
            Modifier
                .widthIn(max = 460.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Text(
                status,
                color = palette.text,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center,
                maxLines = 1,
                modifier = Modifier.weight(1f, fill = false).semantics { liveRegion = LiveRegionMode.Polite },
            )
            Text("$percent%", color = palette.accent, fontSize = 16.sp, fontWeight = FontWeight.Black, maxLines = 1)
        }
    }
}

/** How long the full tub or pool shows before the result card, in milliseconds. */
private const val FINISH_MS = 2200L
