/**
 * The Sea Floor's kelp forest for the seahorse to hide in: two stands of swaying kelp, a big round rock, a branching
 * pink coral, an anemone, a purple sea fan, a heap of rocks with a brain coral and a clump of sea grass, under
 * slanting light with fish passing far off. Every one of them has a hiding spot.
 */
internal class SeaSeekScene(private val g: SceneGrade) : SeekScene() {
    override val props = listOf(
        SeekProp("the rock", Rect(32f, 47f, 72f, 72f), Offset(52f, 71f), Rustle.WOBBLE),
        SeekProp("the kelp", Rect(2f, 8f, 28f, 79f), Offset(14f, 78f), Rustle.SWAY),
        SeekProp("the kelp", Rect(74f, 6f, 99f, 83f), Offset(86f, 82f), Rustle.SWAY),
        SeekProp("the coral", Rect(14f, 70f, 42f, 95f), Offset(28f, 94f), Rustle.SHAKE),
        SeekProp("the anemone", Rect(48f, 78f, 76f, 99f), Offset(62f, 98f), Rustle.SWAY),
        SeekProp("the sea fan", Rect(75f, 78f, 101f, 107f), Offset(88f, 106f), Rustle.SWAY),
        SeekProp("the rocks", Rect(-2f, 96f, 32f, 117f), Offset(14f, 116f), Rustle.WOBBLE),
        SeekProp("the sea grass", Rect(34f, 100f, 62f, 120f), Offset(48f, 119f), Rustle.SWAY),
    )

    override val spots = listOf(
        SeekSpot(0, 43f, 56f, 12f, tilt = -8f, peek = true),
        SeekSpot(1, 15f, 54f, 13f),
        SeekSpot(2, 85.5f, 58f, 13f),
        SeekSpot(3, 28f, 87f, 12f, peek = true),
        SeekSpot(4, 62f, 90f, 12f, peek = true),
        SeekSpot(5, 88f, 96f, 12f, tilt = 5f, peek = true),
        SeekSpot(6, 19f, 107f, 12f, tilt = 6f, peek = true),
        SeekSpot(7, 48f, 113f, 12f, peek = true),
    )

    private val floorY = 64f

    private val waterTop = g(0xFF5CC6D4)
    private val waterMid = g(0xFF2A8FBA)
    private val waterLow = g(0xFF2479AC)
    private val rayColor = g(0xFFE6FFF4)
    private val farReef = g(0xFF3F7894)
    private val farKelp = g(0xFF3D7B8A)
    private val sandFar = g(0xFFA8CBC7)
    private val sandMid = g(0xFFE0D8BC)
    private val sandNear = g(0xFFD8CCA8)
    private val ripple = g(0xFFC6B98F)
    private val pebble = g(0xFF9AA6A0)
    private val bubble = g(0xFFF0FFFF)
    private val fishFar = g(0xFF8FD0E0)
    private val fishYellow = g(0xFFFFD447)
    private val fishBlue = g(0xFF2E7DD8)

    private val kelpStem = g(0xFF3C7A4E)
    private val kelpLeaf = g(0xFF5AA35A)
    private val kelpLeafDark = g(0xFF3E8650)
    private val kelpLight = g(0xFF86C46E)
    private val rockLit = g(0xFF6F93A2)
    private val rockShade = g(0xFF41617A)
    private val rockLight = g(0xFF9CB8C2)
    private val coral = g(0xFFFF7B8E)
    private val coralDark = g(0xFFD8566C)
    private val coralTip = g(0xFFFFB3BC)
    private val anemone = g(0xFFFF8FC7)
    private val anemoneDark = g(0xFFE068A8)
    private val anemoneBase = g(0xFFC4508E)
    private val anemoneTip = g(0xFFFFD0E8)
    private val fan = g(0xFFC070E8)
    private val fanDark = g(0xFF9050C0)
    private val brain = g(0xFFF2C14E)
    private val brainShade = g(0xFFC98A2E)
    private val seaGrass = g(0xFF5E9E62)
    private val seaGrassDark = g(0xFF437E4C)
    private val shell = g(0xFFFFD9C8)
    private val shellShade = g(0xFFE0A890)

    private val farRidge = Ridge(260f, floorY + 1f, 7f, 3f, 0.2f)
    private val pebbles = SceneRandom(31).let { r -> List(30) { Offset(r.next(-80f, 180f), r.next(floorY + 4f, 140f)) } }
    private val ripples = SceneRandom(37).let { r -> List(24) { Offset(r.next(-80f, 180f), r.next(floorY + 3f, 140f)) } }
    private val farKelps = SceneRandom(41).let { r -> List(9) { Offset(r.next(-60f, 160f), r.next(18f, 30f)) } }

    override fun DrawScope.drawScenery(view: Rect, t: Float) {
        drawRect(
            Brush.verticalGradient(0f to waterTop, 0.5f to waterMid, 1f to waterLow, startY = minOf(view.top, -10f), endY = floorY + 4f),
            Offset(view.left, view.top), Size(view.width, floorY + 6f - view.top),
        )
        // Light falling in slanting beams from the surface, breathing slowly.
        for (k in 0 until 5) {
            val x = view.left + view.width * (0.1f + k * 0.21f)
            val glow = 0.07f + 0.04f * swing(t, 6, k * 0.23f)
            val top = view.top
            val beam = polygon(x, top, x + 9f, top, x - 14f, floorY + 6f, x - 26f, floorY + 6f)
            drawPath(beam, Brush.verticalGradient(0f to rayColor.copy(alpha = glow * 1.6f), 1f to rayColor.copy(alpha = 0f), startY = top, endY = floorY + 6f))
        }
        // A far reef and faint kelp on the horizon.
        for (k in farKelps) farKelpBlade(k.x, floorY + 2f, k.y, t)
        translate(-80f, 0f) { drawPath(farRidge.fill(floorY + 8f), farReef.copy(alpha = 0.55f)) }
        // A school of little fish crossing far off.
        val schoolX = view.left - 20f + (view.width + 40f) * drift(t, 3)
        for (f in 0 until 6) {
            val fx = schoolX - (f % 3) * 4.5f - (f / 3) * 2f
            val fy = 26f + (f / 3) * 4f + (f % 3) * 1.2f + swing(t, 30, f * 0.15f) * 0.8f
            oval(fishFar.copy(alpha = 0.7f), fx, fy, 1.8f, 0.8f)
            drawPath(polygon(fx - 1.6f, fy, fx - 3f, fy - 0.9f, fx - 3f, fy + 0.9f), fishFar.copy(alpha = 0.7f))
        }
        // Two little reef fish swimming by, nearer.
        for (k in 0 until 2) {
            val dir = if (k == 0) 1f else -1f
            val p = drift(t, 4 + k, k * 0.5f)
            val fx = if (dir > 0) view.left - 8f + (view.width + 16f) * p else view.right + 8f - (view.width + 16f) * p
            val fy = 34f + k * 12f + swing(t, 24, k * 0.3f) * 1.5f
            reefFish(fx, fy, dir, if (k == 0) fishYellow else fishBlue, t)
        }
        // The sandy floor.
        drawRect(
            Brush.verticalGradient(0f to sandFar, 0.25f to sandMid, 1f to sandNear, startY = floorY, endY = 125f),
            Offset(view.left, floorY + 2f), Size(view.width, view.bottom - floorY - 2f),
        )
        for ((i, p) in ripples.withIndex()) {
            if (p.x < view.left - 8f || p.x > view.right + 8f) continue
            val s = 0.6f + (p.y - floorY) / 70f
            val arc = Path().apply {
                moveTo(p.x - 4f * s, p.y)
                quadraticTo(p.x, p.y - 1.2f * s, p.x + 4f * s, p.y)
            }
            drawPath(arc, ripple.copy(alpha = 0.6f), style = Stroke(0.5f * s, cap = StrokeCap.Round))
            if (i % 4 == 0) dot(Color.White.copy(alpha = 0.3f), p.x + 1f, p.y - 0.6f * s, 0.4f * s)
        }
        for ((i, p) in pebbles.withIndex()) {
            if (p.x < view.left - 4f || p.x > view.right + 4f) continue
            val s = 0.5f + (p.y - floorY) / 80f
            oval(pebble, p.x, p.y, (0.8f + (i % 3) * 0.4f) * s, (0.5f + (i % 2) * 0.2f) * s)
        }
        // Bubbles rising here and there.
        for (k in 0 until 7) {
            val p = drift(t, 9 + k, k * 0.31f)
            val x = view.left + view.width * (0.08f + k * 0.14f) + swing(t, 60, k * 0.2f) * 1.5f
            val y = floorY + 30f - p * (floorY + 40f - view.top)
            drawCircle(bubble.copy(alpha = 0.55f * (1f - p * 0.6f)), 0.7f + (k % 3) * 0.35f, Offset(x, y), style = Stroke(0.35f))
        }
    }

    /** A little reef fish at ([x], [y]) facing [dir] (1 right, -1 left), wagging its tail. */
    private fun DrawScope.reefFish(x: Float, y: Float, dir: Float, color: Color, t: Float) {
        scale(dir, 1f, Offset(x, y)) {
            val wag = swing(t, 200) * 0.6f
            drawPath(polygon(x - 2.4f, y, x - 4.6f, y - 1.7f + wag, x - 4.6f, y + 1.7f + wag), color)
            oval(color, x, y, 3.2f, 1.9f)
            oval(Color.White.copy(alpha = 0.35f), x + 0.4f, y - 0.8f, 1.6f, 0.5f)
            dot(Color.White, x + 1.8f, y - 0.4f, 0.65f)
            dot(Color(0xFF1E2A3A), x + 1.95f, y - 0.4f, 0.38f)
        }
    }

    private fun DrawScope.farKelpBlade(x: Float, base: Float, height: Float, t: Float) {
        val path = Path().apply {
            moveTo(x, base)
            val sway = swing(t, 8, x / 100f) * 2f
            quadraticTo(x + sway, base - height * 0.5f, x + sway * 1.8f, base - height)
        }
        drawPath(path, farKelp.copy(alpha = 0.45f), style = Stroke(1.6f, cap = StrokeCap.Round))
    }

    override fun DrawScope.drawBack(prop: Int, t: Float) {
        when (prop) {
            1 -> kelp(14f, 78f, t, 0f, front = false)
            2 -> kelp(86f, 82f, t, 0.4f, front = false)
            3 -> coralBack()
            4 -> anemoneTentacles(t, front = false)
            5 -> oval(Color.Black.copy(alpha = 0.12f), 88f, 106f, 10f, 1.6f)
            7 -> seaGrassBlades(t, front = false)
        }
    }

    override fun DrawScope.drawFront(prop: Int, t: Float) {
        when (prop) {
            0 -> bigRock()
            1 -> kelp(14f, 78f, t, 0f, front = true)
            2 -> kelp(86f, 82f, t, 0.4f, front = true)
            3 -> coralFront()
            4 -> anemoneFront(t)
            5 -> seaFan(t)
            6 -> rockPile()
            7 -> seaGrassFront(t)
        }
    }

    /**
     * A stand of kelp at ([x], [base]): long stems with leaves along them, swaying with the water. The back stems are
     * drawn behind what hides in it, the front stems over it.
     */
    private fun DrawScope.kelp(x: Float, base: Float, t: Float, phase: Float, front: Boolean) {
        if (!front) oval(Color.Black.copy(alpha = 0.12f), x, base, 10f, 1.6f)
        val stems = if (front) floatArrayOf(-4.5f, 4f) else floatArrayOf(-7.5f, -1f, 7f)
        val heights = if (front) floatArrayOf(52f, 60f) else floatArrayOf(66f, 72f, 58f)
        for ((i, dx) in stems.withIndex()) {
            val h = heights[i]
            val ph = phase + i * 0.21f + if (front) 0.5f else 0f
            var px = x + dx
            var py = base
            val stem = Path().apply { moveTo(px, py) }
            val steps = 10
            val points = ArrayList<Offset>(steps)
            for (k in 1..steps) {
                val f = k / steps.toFloat()
                val sway = swing(t, 8, ph + f * 0.18f) * 3.2f * f * f + dx * 0.15f * f
                val nx = x + dx + sway
                val ny = base - h * f
                stem.quadraticTo(px, (py + ny) / 2, nx, ny)
                px = nx
                py = ny
                points += Offset(nx, ny)
            }
            drawPath(stem, kelpStem, style = Stroke(1.3f, cap = StrokeCap.Round))
            for ((k, p) in points.withIndex()) {
                val side = if ((k + i) % 2 == 0) 1f else -1f
                val f = (k + 1) / steps.toFloat()
                val length = 7.5f - 3f * f
                val flutter = swing(t, 8, ph + f * 0.18f + 0.1f) * 12f
                kelpLeafAt(p, side, length, flutter, if ((k + i) % 3 == 0) kelpLeafDark else kelpLeaf)
            }
            dot(kelpLight, points.last().x, points.last().y, 1.4f)
        }
    }

    private fun DrawScope.kelpLeafAt(p: Offset, side: Float, length: Float, flutter: Float, color: Color) {
        val a = ((if (side > 0) -40f else -140f) + flutter) * DEG
        val tip = p + Offset(cos(a) * length, sin(a) * length)
        val n = Offset(-sin(a), cos(a)) * (length * 0.24f)
        val mid = (p + tip) / 2f
        val leaf = Path().apply {
            moveTo(p.x, p.y)
            quadraticTo(mid.x + n.x, mid.y + n.y, tip.x, tip.y)
            quadraticTo(mid.x - n.x, mid.y - n.y, p.x, p.y)
            close()
        }
        drawPath(leaf, color)
    }

    /** The big round rock in the middle, lit from above. */
    private fun DrawScope.bigRock() {
        oval(Color.Black.copy(alpha = 0.16f), 52f, 71f, 20f, 2.4f)
        val rock = Path().apply {
            moveTo(33f, 71f)
            cubicTo(32f, 58f, 42f, 49f, 53f, 49f)
            cubicTo(64f, 49f, 72f, 58f, 71f, 71f)
            close()
        }
        drawPath(rock, rockShade)
        translate(-1f, -1f) { scale(0.94f, 0.92f, Offset(52f, 71f)) { drawPath(rock, rockLit) } }
        oval(rockLight.copy(alpha = 0.7f), 47f, 55f, 7f, 3f)
        oval(rockShade.copy(alpha = 0.5f), 60f, 64f, 4f, 2.2f)
        oval(rockShade.copy(alpha = 0.4f), 44f, 66f, 3f, 1.5f)
        // A little starfish resting on it, and a tuft of weed.
        for (k in 0 until 5) {
            val a = (-90f + k * 72f) * DEG
            stick(g(0xFFFF9A3D), 61f, 55f, 61f + cos(a) * 2.6f, 55f + sin(a) * 2.6f, 1.4f)
        }
        dot(g(0xFFFFB46A), 61f, 55f, 1.1f)
        stick(seaGrass, 36f, 70f, 35f, 66f, 0.8f)
        stick(seaGrass, 37f, 70f, 38f, 65.5f, 0.8f)
    }

    // The branching coral: a mound at its foot, round-tipped branches spreading up over what hides in it.
    private fun DrawScope.coralBack() {
        oval(Color.Black.copy(alpha = 0.14f), 28f, 94f, 13f, 2f)
        coralBranch(20f, 94f, 15f, 76f, coralDark)
        coralBranch(36f, 94f, 41f, 78f, coralDark)
        coralBranch(28f, 94f, 30f, 72f, coralDark)
    }

    private fun DrawScope.coralFront() {
        coralBranch(23f, 95f, 18f, 83f, coral)
        coralBranch(33f, 95f, 38f, 84f, coral)
        oval(coralDark, 28f, 94f, 9f, 3f)
        oval(coral, 28f, 93.4f, 8f, 2.4f)
    }

    private fun DrawScope.coralBranch(x1: Float, y1: Float, x2: Float, y2: Float, color: Color) {
        val path = Path().apply {
            moveTo(x1, y1)
            quadraticTo(x1 + (x2 - x1) * 0.2f, (y1 + y2) / 2, x2, y2)
        }
        drawPath(path, color, style = Stroke(2.6f, cap = StrokeCap.Round))
        dot(coralTip, x2, y2, 1.7f)
        // A short twig off each branch.
        val mx = (x1 + x2) / 2 + (x2 - x1) * 0.1f
        val my = (y1 + y2) / 2
        val tx = mx + (if (x2 >= x1) -3.5f else 3.5f)
        stick(color, mx, my, tx, my - 4f, 2f)
        dot(coralTip, tx, my - 4f, 1.3f)
    }

    // The anemone: a ring of soft tentacles on a pink foot, the back ones behind what hides in it.
    private fun DrawScope.anemoneTentacles(t: Float, front: Boolean) {
        if (!front) oval(Color.Black.copy(alpha = 0.14f), 62f, 98f, 12f, 1.8f)
        val count = if (front) 8 else 7
        for (k in 0 until count) {
            val f = k / (count - 1f)
            val bx = 52.5f + f * 19f
            val by = if (front) 93f else 89f
            val h = if (front) 8f + 2f * sin(f * 3.1416f) else 10f + 2.5f * sin(f * 3.1416f)
            val lean = (f - 0.5f) * 9f + swing(t, 12, f * 0.3f + if (front) 0.2f else 0f) * 2.2f
            val tip = Offset(bx + lean, by - h)
            val path = Path().apply {
                moveTo(bx, by)
                quadraticTo(bx + lean * 0.2f, by - h * 0.6f, tip.x, tip.y)
            }
            drawPath(path, if (front) anemone else anemoneDark, style = Stroke(2.3f, cap = StrokeCap.Round))
            dot(anemoneTip, tip.x, tip.y, 1.3f)
        }
    }

    private fun DrawScope.anemoneFront(t: Float) {
        anemoneTentacles(t, front = true)
        box(anemoneBase, 54f, 92f, 70f, 98.5f, 3f)
        oval(anemone.copy(alpha = 0.6f), 60f, 93.5f, 5f, 1f)
    }

    /** The sea fan: a broad purple lattice fanning up from a short stem, swaying a little. */
    private fun DrawScope.seaFan(t: Float) {
        val sway = swing(t, 10, 0.4f) * 1.5f
        val stem = Offset(88f, 106f)
        for (k in 0 until 9) {
            val a = (-150f + k * 15f) * DEG
            val length = 19f - kotlin.math.abs(k - 4) * 1.3f
            val tip = Offset(stem.x + cos(a) * length + sway, stem.y + sin(a) * length)
            drawLine(fanDark, stem, tip, 1.3f, StrokeCap.Round)
            dot(fan, tip.x, tip.y, 1.1f)
        }
        for (ring in 1..4) {
            val r = ring * 4.2f
            val arc = Path()
            for (k in 0..12) {
                val a = (-150f + k * 10f) * DEG
                val p = Offset(stem.x + cos(a) * r + sway * ring / 4f, stem.y + sin(a) * r)
                if (k == 0) arc.moveTo(p.x, p.y) else arc.lineTo(p.x, p.y)
            }
            drawPath(arc, fan.copy(alpha = 0.85f), style = Stroke(0.9f, cap = StrokeCap.Round))
        }
        stick(fanDark, 88f, 106.5f, 88f, 102f, 2.4f)
        oval(fanDark, 88f, 106.5f, 3f, 1.2f)
    }

    /** A heap of rocks at the front left, a brain coral and a shell on it. */
    private fun DrawScope.rockPile() {
        oval(Color.Black.copy(alpha = 0.16f), 14f, 116f, 17f, 2.2f)
        dot(rockShade, 22f, 110f, 7.5f)
        dot(rockLit, 21.4f, 109.3f, 6.8f)
        dot(rockShade, 7f, 109f, 9.5f)
        dot(rockLit, 6.2f, 108.2f, 8.8f)
        oval(rockLight.copy(alpha = 0.6f), 4f, 103f, 4f, 1.8f)
        box(rockShade, -2f, 110f, 30f, 117f, 3f)
        oval(rockLit, 15f, 112f, 10f, 4.6f)
        // The brain coral.
        oval(brainShade, 11f, 101.5f, 6f, 4.2f)
        oval(brain, 10.6f, 101f, 5.4f, 3.7f)
        for (k in 0 until 3) {
            val y = 99.5f + k * 1.3f
            val wave = Path().apply {
                moveTo(6.5f, y)
                quadraticTo(8.5f, y - 1f, 10.5f, y)
                quadraticTo(12.5f, y + 1f, 14.5f, y)
            }
            drawPath(wave, brainShade, style = Stroke(0.5f, cap = StrokeCap.Round))
        }
        // A scallop shell.
        drawPath(polygon(24f, 113.5f, 20.5f, 109f, 27.5f, 109f), shell)
        dot(shell, 24f, 109.4f, 3.5f)
        for (k in -1..1) stick(shellShade, 24f, 113f, 24f + k * 2f, 107f, 0.4f)
    }

    // The clump of sea grass at the front: tall waving blades, the back row darker.
    private fun DrawScope.seaGrassBlades(t: Float, front: Boolean) {
        val path = Path()
        val count = if (front) 7 else 6
        for (b in 0 until count) {
            val x = if (front) 38f + b * 3.5f else 39.5f + b * 3.5f
            val h = if (front) 9f + (b * 5 % 4) * 1.4f else 14f + (b * 3 % 4) * 1.2f
            val lean = (b - count / 2f) * 0.7f + swing(t, 9, b * 0.11f + if (front) 0.25f else 0f) * 2f
            path.moveTo(x - 0.9f, 119f)
            path.quadraticTo(x + lean * 0.3f, 119f - h * 0.6f, x + lean, 119f - h)
            path.quadraticTo(x + lean * 0.3f + 0.7f, 119f - h * 0.5f, x + 0.9f, 119f)
            path.close()
        }
        drawPath(path, if (front) seaGrass else seaGrassDark)
    }

    private fun DrawScope.seaGrassFront(t: Float) {
        seaGrassBlades(t, front = true)
        // A clam at its foot, opening a crack now and then.
        val open = ((swing(t, 12) - 0.6f) * 2.5f).coerceIn(0f, 1f)
        oval(g(0xFF8C7FA8), 57f, 117.5f, 4f, 1.8f)
        dot(Color.White, 57f, 116.6f, 0.9f * open)
        oval(g(0xFFB2A6CC), 57f, 116.5f - open, 4f, 1.6f)
        oval(Color.White.copy(alpha = 0.4f), 56f, 116f - open, 1.6f, 0.5f)
        if (open > 0.5f) drawCircle(bubble.copy(alpha = 0.6f), 0.6f, Offset(57.5f, 114f - open * 3f), style = Stroke(0.3f))
    }
}
