package io.colorsand.core

/**
 * The short, calm keepsake games. Every keepsake opens one of them (see [KeepsakeGame.of]); several keepsakes share
 * a game and give it their own twist.
 */
enum class Minigame(val title: String) {
    SNOWBALL_TOSS("Snowball toss"),
    SAND_FLOW("Sand flow"),
    TREASURE_DIG("Treasure dig"),
    HIDE_AND_SEEK("Hide and seek"),
    ROCKET_PATH("Rocket path"),
    SORT("Sort"),
    STACK("Stack the castle"),
    CATCH_THE_GRAINS("Catch the grains"),
    SAND_ART("Sand art bottle"),
    BUBBLE_POP("Bubble pop"),
    COLOR_MIXER("Color mixer"),
    GEM_MATCH("Sand gem match"),
    MEMORY("Keepsake memory"),
    DIG_DEEPER("Dig deeper"),
}

/**
 * The game behind one keepsake: the [arena] and [stage] (1 to [Arena.LEVELS]) it is earned in, the [keepsake]'s
 * name as it reads in a sentence ("Play with the dump truck"), the [game] it opens and the [twist] that game takes
 * there, a short line under its title.
 */
data class KeepsakeGame(val arena: Arena, val stage: Int, val keepsake: String, val game: Minigame, val twist: String) {
    companion object {
        /** The keepsake game of [arena]'s [stage]. */
        fun of(arena: Arena, stage: Int): KeepsakeGame {
            require(stage in 1..Arena.LEVELS) { "Stages run from 1 to ${Arena.LEVELS}, was $stage" }
            return all.getValue(arena)[stage - 1]
        }

        /** The keepsake game earned by solving level [number]. Repeated arenas repeat their keepsakes. */
        fun forLevel(number: Int): KeepsakeGame = of(Arena.of(number), Arena.stage(number))

        private val all: Map<Arena, List<KeepsakeGame>> = mapOf(
            Arena.PLAYGROUND to games(
                Arena.PLAYGROUND,
                Triple("ball", Minigame.SNOWBALL_TOSS, "Toss sandballs into the bucket"),
                Triple("rubber duck", Minigame.SAND_FLOW, "Carve a sandy stream to the duck"),
                Triple("dump truck", Minigame.TREASURE_DIG, "Dig the sandbox for lost toys"),
                Triple("teddy", Minigame.HIDE_AND_SEEK, "Find where teddy is hiding"),
                Triple("kite", Minigame.ROCKET_PATH, "Steer the kite along the breeze"),
            ),
            Arena.BEACH to games(
                Arena.BEACH,
                Triple("starfish", Minigame.SORT, "Sort the shells by color"),
                Triple("crab", Minigame.TREASURE_DIG, "Dig for shells and a message in a bottle"),
                Triple("sandcastle", Minigame.STACK, "Stack the tallest sandcastle"),
                Triple("beach umbrella", Minigame.CATCH_THE_GRAINS, "Catch the sand blowing in the breeze"),
                Triple("surfboard", Minigame.SAND_ART, "Layer a bottle of beach sand"),
            ),
            Arena.SEA_FLOOR to games(
                Arena.SEA_FLOOR,
                Triple("clownfish", Minigame.BUBBLE_POP, "Pop the bubbles with the clownfish"),
                Triple("seahorse", Minigame.HIDE_AND_SEEK, "Spot the seahorse in the kelp"),
                Triple("octopus", Minigame.COLOR_MIXER, "Mix the octopus's inks"),
                Triple("sea turtle", Minigame.ROCKET_PATH, "Swim the turtle through the reef"),
                Triple("treasure chest", Minigame.GEM_MATCH, "Match the gems from the chest"),
            ),
            Arena.DESERT to games(
                Arena.DESERT,
                Triple("oasis palm", Minigame.SAND_FLOW, "Lead the water to the oasis"),
                Triple("tent", Minigame.MEMORY, "Find the pairs in the tent"),
                Triple("camel", Minigame.CATCH_THE_GRAINS, "Catch the dune sand on the camel"),
                Triple("Bedouin", Minigame.SAND_ART, "Layer a bottle of desert sand"),
                Triple("pyramid", Minigame.DIG_DEEPER, "Dig down to the hidden chamber"),
            ),
            Arena.BUILDING_SITE to games(
                Arena.BUILDING_SITE,
                Triple("traffic cone", Minigame.SNOWBALL_TOSS, "Toss sandbags past the cones"),
                Triple("wheelbarrow", Minigame.SORT, "Sort the gravel, sand and bricks"),
                Triple("builder", Minigame.STACK, "Stack the bricks for the builder"),
                Triple("cement mixer", Minigame.COLOR_MIXER, "Mix the cement colors"),
                Triple("excavator", Minigame.DIG_DEEPER, "Dig down with the excavator"),
            ),
            Arena.MARS to games(
                Arena.MARS,
                Triple("flag", Minigame.GEM_MATCH, "Match the Martian gems"),
                Triple("alien", Minigame.MEMORY, "Find the alien's pairs"),
                Triple("astronaut", Minigame.CATCH_THE_GRAINS, "Catch the red dust in a jar"),
                Triple("rover", Minigame.TREASURE_DIG, "Dig for Martian ice and fossils"),
                Triple("rocket", Minigame.ROCKET_PATH, "Fly the rocket up to the moons"),
            ),
        )

        private fun games(arena: Arena, vararg games: Triple<String, Minigame, String>): List<KeepsakeGame> =
            games.mapIndexed { i, (keepsake, game, twist) -> KeepsakeGame(arena, i + 1, keepsake, game, twist) }
    }
}
