package io.colorsand.ui.minigame

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import io.colorsand.core.Arena
import io.colorsand.ui.arena.SceneGrade

/** Where the course runs: up through the Playground's sky, up through the reef, or up into Mars's sky. */
internal enum class PathScene { SKY, REEF, SPACE }

/**
 * The look of Rocket path in one arena: the [scene], its backdrop at the start ([lowTop], [lowBottom]) and near the
 * goal ([highTop], [highBottom]), the [ring] color and its [ringLight], the [sparkle] color, the obstacles' colors
 * ([thing], [thingDark]), the ground left behind at the start ([ground], [groundDark]) and the keepsake flying it
 * ([arena]'s [stage]). The words name the keepsake, the sparkles and the goal.
 */
internal class PathLook(
    val arena: Arena,
    val stage: Int,
    val scene: PathScene,
    val lowTop: Color,
    val lowBottom: Color,
    val highTop: Color,
    val highBottom: Color,
    val ring: Color,
    val ringLight: Color,
    val sparkle: Color,
    val thing: Color,
    val thingDark: Color,
    val ground: Color,
    val groundDark: Color,
    val keepsake: String,
    val sparkles: String,
    val goal: String,
    val start: String,
    val arrived: String,
) {
    companion object {
        /** [arena]'s look, its colors through [g]. Arenas without Rocket path get Mars's. */
        fun of(arena: Arena, g: SceneGrade): PathLook = when (arena) {
            Arena.PLAYGROUND -> PathLook(
                Arena.PLAYGROUND, 5, PathScene.SKY,
                g(0xFF58AAE6), g(0xFFBFE3F7), g(0xFF7EC3F0), g(0xFFFFF1C9),
                g(0xFFFF8A5C), g(0xFFFFD1A8), g(0xFFFFD447),
                g(0xFFE8494E), g(0xFFB8333A),
                g(0xFF6BBB4F), g(0xFF4C9A3D),
                "kite", "stars", "the sunny cloud",
                "Drag to steer the kite!",
                "Up to the sunny cloud!",
            )
            Arena.SEA_FLOOR -> PathLook(
                Arena.SEA_FLOOR, 4, PathScene.REEF,
                g(0xFF1B6E9C), g(0xFF0E4A73), g(0xFF5CC4D8), g(0xFF2A8FB5),
                g(0xFFF28C6B), g(0xFFFFC2A6), g(0xFFE8FBFF),
                g(0xFFF59BD0), g(0xFFC75FA0),
                g(0xFFE7D2A0), g(0xFFB89A62),
                "turtle", "bubbles", "the reef cave",
                "Drag to steer the turtle!",
                "Home to the reef cave!",
            )
            else -> PathLook(
                Arena.MARS, 5, PathScene.SPACE,
                g(0xFF6A3550), g(0xFFC9714E), g(0xFF120E2A), g(0xFF3A1F4D),
                g(0xFF6FE0F2), g(0xFFCFF8FF), g(0xFFFFD98A),
                g(0xFF9C8576), g(0xFF6A574C),
                g(0xFFD27145), g(0xFF9C4A2A),
                "rocket", "stardust", "the two moons",
                "Drag to steer the rocket!",
                "Up to the two moons!",
            )
        }
    }
}

/**
 * Where Rocket path sits in a [width] x [height] canvas, in pixels: across is the field's 0 to 1, and the course
 * scrolls down past the keepsake, which flies at [shipY] near the bottom. Distances along the course are in field
 * widths, like across. [unit] is a hundredth of the width.
 */
internal class PathLayout(val width: Float, val height: Float, private val view: Float) {
    val unit: Float = width / 100f
    val shipY: Float = height - maxOf(width * 0.32f, height * 0.24f)

    fun x(x: Float): Float = x * width

    /** The y of [d] along the course. */
    fun y(d: Float): Float = shipY - (d - view) * width
    fun at(x: Float, d: Float): Offset = Offset(x(x), y(d))
    fun len(d: Float): Float = d * width

    /** Whether something at [d] that reaches [reach] field widths around it is on screen. */
    fun shows(d: Float, reach: Float): Boolean = y(d) + len(reach) > 0f && y(d) - len(reach) < height
}
