package io.colorsand.ui.arena

import androidx.compose.foundation.layout.Spacer
import androidx.compose.runtime.Composable
import androidx.compose.runtime.State
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.drawWithCache
import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.RoundRect
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.clipPath
import androidx.compose.ui.graphics.drawscope.clipRect
import androidx.compose.ui.graphics.drawscope.scale
import androidx.compose.ui.graphics.drawscope.translate
import androidx.compose.ui.graphics.lerp
import kotlin.math.max
import kotlin.math.min

/**
 * The Desert: golden-hour dunes. A dusk sky going from indigo with the first stars down to a warm orange glow,
 * a big hazy sun shimmering in the heat over far mesas, dunes lit on one side and shaded on the other,
 * a saguaro cactus, and wisps of sand blowing over the near dunes.
 */
@Composable
internal fun DesertScene(grade: SceneGrade, modifier: Modifier = Modifier) {
    val clock = rememberSceneClock()
    Spacer(
        modifier.drawWithCache {
            val art = DesertArt(size, grade)
            onDrawBehind { art.draw(this, clock) }
        },
    )
}

/** Everything the Desert draws, built once per size and grade; [draw] only moves it. */
private class DesertArt(size: Size, private val g: SceneGrade) {
    private val w = size.width
    private val h = size.height
    private val u = min(w, h * 0.6f)

    private val horizonY = h * 0.75f
    private val haze = Color(0xFFFFD9A6)
    private fun far(c: Long, amount: Float) = g(lerp(Color(c), haze, amount))

    private val sky = Brush.verticalGradient(
        0f to g(0xFF2E2C66), 0.16f to g(0xFF544690), 0.34f to g(0xFFA2689A), 0.52f to g(0xFFE58C72),
        0.66f to g(0xFFF9B979), 0.75f to g(haze),
        startY = 0f, endY = h,
    )

    // Stars in the dark top of the sky.
    private class Star(val at: Offset, val radius: Float, val bright: Float, val cycles: Int, val phase: Float)

    private val stars = SceneRandom(41).let { r ->
        List(46) {
            val f = r.next()
            val y = h * 0.26f * f * f
            Star(Offset(w * r.next(), y), u * r.next(0.002f, 0.0055f), 1f - y / (h * 0.28f), 20 + (r.next() * 40).toInt(), r.next())
        }
    }
    private val starColor = g(0xFFFFF6E0)

    // The big hazy sun, low over the mesas.
    private val sunCenter = Offset(w * 0.3f, h * 0.665f)
    private val sunRadius = u * 0.15f
    private val sunHalo = g(0xFFFFC77A)
    private val sunDisk = Brush.radialGradient(
        0f to g(0xFFFFF1C4), 0.75f to g(0xFFFFE19A), 0.92f to g(Color(0xCCFFD58A)), 1f to g(Color(0x00FFD58A)),
        center = Offset.Zero, radius = sunRadius,
    )
    private val sunSlices = 14

    // Far mesas, then nearer ones: farther is paler and more violet.
    private val farMesas = mesas(listOf(-0.05f to 0.18f, 0.52f to 0.7f, 0.86f to 1.08f), u * 0.05f)
    private val nearMesas = mesas(listOf(0.12f to 0.3f, 0.66f to 0.82f), u * 0.035f)
    private val horizonHaze = Brush.verticalGradient(
        0f to Color.Transparent, 0.6f to g(haze.copy(alpha = 0.45f)), 1f to Color.Transparent,
        startY = horizonY - u * 0.04f, endY = horizonY + u * 0.02f,
    )
    private val farMesaColor = far(0xFFB27C9C, 0.5f)
    private val nearMesaColor = far(0xFFA2626A, 0.32f)
    private val nearMesaShade = far(0xFF7E4A5E, 0.3f)

    private fun mesas(spans: List<Pair<Float, Float>>, height: Float): Path = Path().apply {
        for ((a, b) in spans) {
            val x0 = w * a
            val x1 = w * b
            val top = horizonY - height
            moveTo(x0 - u * 0.04f, horizonY + 1f)
            cubicTo(x0 - u * 0.01f, horizonY - height * 0.2f, x0, top + height * 0.3f, x0 + u * 0.012f, top)
            lineTo(x1 - u * 0.012f, top)
            cubicTo(x1, top + height * 0.3f, x1 + u * 0.01f, horizonY - height * 0.2f, x1 + u * 0.04f, horizonY + 1f)
            close()
        }
    }

    // Dunes: a lit face toward the sun on the left, a shaded face away from it.
    private class Dune(val body: Path, val shade: Path)

    private fun dune(x0: Float, crestX: Float, x1: Float, crestY: Float, baseY: Float, bottom: Float): Dune {
        // Both feet run down off the bottom, so where one dune covers another there is no seam.
        val body = Path().apply {
            moveTo(x0, bottom)
            cubicTo(x0 + (crestX - x0) * 0.35f, baseY, crestX - (crestX - x0) * 0.3f, crestY, crestX, crestY)
            cubicTo(crestX + (x1 - crestX) * 0.25f, crestY + (baseY - crestY) * 0.15f, x1 - (x1 - crestX) * 0.3f, baseY, x1, bottom)
            close()
        }
        val shade = Path().apply {
            moveTo(crestX, crestY)
            cubicTo(crestX + (x1 - crestX) * 0.25f, crestY + (baseY - crestY) * 0.15f, x1 - (x1 - crestX) * 0.3f, baseY, x1, bottom)
            lineTo(crestX + (x1 - crestX) * 0.1f, bottom)
            quadraticTo(crestX + (x1 - crestX) * 0.02f, crestY + (bottom - crestY) * 0.4f, crestX, crestY)
            close()
        }
        return Dune(body, shade)
    }

    private val midDunes = listOf(
        dune(-w * 0.3f, w * 0.18f, w * 0.62f, h * 0.775f, h * 0.83f, h),
        dune(w * 0.35f, w * 0.72f, w * 1.3f, h * 0.765f, h * 0.835f, h),
    )
    private val midBrush = Brush.verticalGradient(
        0f to far(0xFFF0A766, 0.18f), 1f to far(0xFFE08F4E, 0.1f), startY = h * 0.76f, endY = h * 0.88f,
    )
    private val midShade = far(0xFFB8644A, 0.15f)
    private val nearDunes = listOf(
        dune(-w * 0.5f, w * 0.38f, w * 1.1f, h * 0.865f, h * 0.92f, h),
        dune(w * 0.55f, w * 0.95f, w * 1.6f, h * 0.885f, h * 0.93f, h),
    )
    private val nearBrush = Brush.verticalGradient(
        0f to g(0xFFF4A55C), 1f to g(0xFFE0843F), startY = h * 0.86f, endY = h,
    )
    private val nearShade = g(0xFFB65E37)
    private val ripples = Path().apply {
        val r = SceneRandom(43)
        repeat(16) {
            val x = w * r.next(-0.1f, 1f)
            val y = h * r.next(0.9f, 0.995f)
            val len = u * r.next(0.12f, 0.3f)
            moveTo(x, y)
            cubicTo(x + len * 0.3f, y - u * 0.012f, x + len * 0.6f, y + u * 0.008f, x + len, y - u * 0.004f)
        }
    }
    private val rippleDark = g(Color(0x40A0522D))
    private val rippleLight = g(Color(0x40FFE3B0))

    // The saguaro on the right and a small far one on the left.
    private val cactus = Path().apply {
        addRoundRect(RoundRect(-0.09f, -1f, 0.09f, 0f, CornerRadius(0.09f)))
        addRoundRect(RoundRect(-0.36f, -0.68f, -0.24f, -0.3f, CornerRadius(0.06f)))
        addRoundRect(RoundRect(-0.36f, -0.42f, -0.02f, -0.3f, CornerRadius(0.06f)))
        addRoundRect(RoundRect(0.22f, -0.84f, 0.34f, -0.46f, CornerRadius(0.06f)))
        addRoundRect(RoundRect(0.02f, -0.58f, 0.34f, -0.46f, CornerRadius(0.06f)))
    }
    private val cactusLit = g(0xFF8DA65A)
    private val cactusShade = g(0xFF4B6B3F)
    private val cactusFar = far(0xFF6F7D52, 0.35f)
    private val cactusX = w * 0.88f
    private val cactusBase = h * 0.83f
    private val cactusSize = u * 0.2f

    // Sand wisps blowing to the right.
    private class Wisp(val y: Float, val length: Float, val laps: Int, val start: Float)

    private val wisps = SceneRandom(47).let { r ->
        List(6) { Wisp(h * r.next(0.86f, 0.93f), u * r.next(0.12f, 0.24f), 3 + (r.next() * 3).toInt(), r.next()) }
    }
    private val wispColor = g(0xFFFFE6BF)

    private val shade = vignette(w, h, g(Color(0x4A2A1430)))

    fun draw(scope: DrawScope, clock: State<Float>) = with(scope) {
        val t = clock.value
        drawRect(sky)
        for (s in stars) {
            val twinkle = 0.55f + 0.45f * swing(t, s.cycles, s.phase)
            drawCircle(starColor.copy(alpha = (s.bright * twinkle).coerceIn(0f, 1f)), s.radius, s.at)
            if (s.radius > u * 0.0045f) {
                val l = s.radius * 3.2f * twinkle
                val c = starColor.copy(alpha = s.bright * twinkle * 0.6f)
                drawLine(c, s.at - Offset(l, 0f), s.at + Offset(l, 0f), s.radius * 0.5f)
                drawLine(c, s.at - Offset(0f, l), s.at + Offset(0f, l), s.radius * 0.5f)
            }
        }

        drawGlow(sunCenter, u * 1.2f, sunHalo.copy(alpha = 0.55f))
        drawSun(t)
        drawPath(farMesas, farMesaColor)
        drawRect(horizonHaze, Offset(0f, horizonY - u * 0.04f), Size(w, u * 0.06f))
        drawPath(nearMesas, nearMesaColor)
        clipPath(nearMesas) { translate(u * 0.03f, 0f) { drawPath(nearMesas, nearMesaShade, alpha = 0.6f) } }

        for (d in midDunes) {
            drawPath(d.body, midBrush)
            drawPath(d.shade, midShade, alpha = 0.55f)
        }
        drawCactus(Offset(w * 0.1f, h * 0.81f), u * 0.08f, far = true)
        drawCactus(Offset(cactusX, cactusBase), cactusSize, far = false)

        for (d in nearDunes) {
            drawPath(d.body, nearBrush)
            drawPath(d.shade, nearShade, alpha = 0.5f)
        }
        drawPath(ripples, rippleDark, style = Stroke(u * 0.004f, cap = StrokeCap.Round))
        translate(0f, -u * 0.004f) { drawPath(ripples, rippleLight, style = Stroke(u * 0.003f, cap = StrokeCap.Round)) }
        drawWisps(t)
        drawRect(shade)
    }

    /** The sun in horizontal slices that sway a little, more toward the hot ground: heat shimmer. */
    private fun DrawScope.drawSun(t: Float) {
        val top = sunCenter.y - sunRadius
        val slice = 2 * sunRadius / sunSlices
        for (i in 0 until sunSlices) {
            val y = top + i * slice
            val depth = i / (sunSlices - 1f)
            val dx = u * 0.006f * depth * depth * swing(t, 90, i * 0.21f)
            clipRect(sunCenter.x - sunRadius * 1.2f, y, sunCenter.x + sunRadius * 1.2f, y + slice + 0.5f) {
                translate(sunCenter.x + dx, sunCenter.y) { drawCircle(sunDisk, sunRadius, Offset.Zero) }
            }
        }
    }

    private fun DrawScope.drawCactus(base: Offset, size: Float, far: Boolean) {
        drawOval(Color.Black.copy(alpha = if (far) 0.06f else 0.12f), Offset(base.x - size * 0.1f, base.y - size * 0.03f), Size(size * 0.7f, size * 0.08f))
        translate(base.x, base.y) {
            scale(size, size, Offset.Zero) {
                if (far) {
                    drawPath(cactus, cactusFar)
                } else {
                    drawPath(cactus, cactusLit)
                    // Shade everything but a rim on the sun side.
                    clipPath(cactus) { translate(0.05f, 0f) { drawPath(cactus, cactusShade) } }
                    for (x in listOf(-0.03f, 0.03f)) drawLine(cactusLit.copy(alpha = 0.35f), Offset(x, -0.95f), Offset(x, -0.05f), 0.012f)
                }
            }
        }
    }

    private fun DrawScope.drawWisps(t: Float) {
        for (wsp in wisps) {
            val p = drift(t, wsp.laps, wsp.start)
            val x = -wsp.length + p * (w + 2 * wsp.length)
            // Fade in and out over the crossing.
            val a = max(0f, swing(p, 1, -0.25f) * 0.5f + 0.5f) * 0.35f
            val y = wsp.y + u * 0.006f * swing(t, 17, wsp.start)
            drawOval(
                Brush.horizontalGradient(0f to Color.Transparent, 0.6f to wispColor.copy(alpha = a), 1f to Color.Transparent, startX = x, endX = x + wsp.length),
                Offset(x, y - u * 0.004f),
                Size(wsp.length, u * 0.008f),
            )
        }
    }
}
