package io.colorsand.ui.minigame

import kotlin.random.Random

/** A way the digger can dig. */
enum class DigWay(val dx: Int, val dy: Int) { LEFT(-1, 0), RIGHT(1, 0), DOWN(0, 1) }

/** What a dig did: nothing, cracked a tile, broke one and moved in, turned up a find, or opened the chamber. */
enum class DeepEvent { NONE, WALK, CRACK, BREAK, FIND, CHAMBER }

/**
 * One tile of the ground: its [layer] (0 at the top, [DigDeeper.LAYERS] - 1 at the bottom), how many taps it takes
 * to break ([hardness], 1 to 3), the [find] in it (an index into the arena's finds) if any, and whether it is a
 * [slab]: a hard old pipe or stone block, drawn as one.
 */
data class DeepTile(val layer: Int, val hardness: Int, val find: Int? = null, val slab: Boolean = false)

/**
 * A round of Dig deeper: a [columns]-wide shaft of ground [depth] rows deep, a hidden chamber under it. The digger
 * starts on the surface ([y] = -1) at column [x] and digs left, right or down: each tap cracks the next tile, and
 * when it breaks the digger moves in, picking up any find there. Reaching the
 * bottom row opens the chamber ([isDone]). Nothing blocks the way for good, so a round always ends. Immutable;
 * [dig] returns the next state.
 */
data class DigDeeper(
    val columns: Int,
    val depth: Int,
    val tiles: List<DeepTile>,
    val x: Int,
    val y: Int = -1,
    /** Taps each tile has taken so far. */
    val hits: List<Int> = List(tiles.size) { 0 },
    /** The finds picked up so far, in order, as indices into the arena's finds. */
    val found: List<Int> = emptyList(),
) {
    init {
        require(tiles.size == columns * depth) { "Need $columns x $depth tiles" }
    }

    /** Whether the digger has broken through into the chamber. */
    val isDone: Boolean get() = y >= depth

    /** How many finds are buried in all. */
    val finds: Int get() = tiles.count { it.find != null }

    fun tile(x: Int, y: Int): DeepTile = tiles[y * columns + x]

    /** Whether the tile at ([x], [y]) has been dug out. */
    fun isDug(x: Int, y: Int): Boolean = hits[y * columns + x] >= tile(x, y).hardness

    /** How cracked the tile at ([x], [y]) is: 0 untouched, up to just under 1 before it breaks. */
    fun cracks(x: Int, y: Int): Float = hits[y * columns + x].toFloat() / tile(x, y).hardness

    /** The layer the digger is in, or -1 on the surface. */
    val layer: Int get() = if (y < 0) -1 else tile(x, y.coerceAtMost(depth - 1)).layer

    /** This round after a dig [way], and what it did. */
    fun dig(way: DigWay): Pair<DigDeeper, DeepEvent> {
        if (isDone) return this to DeepEvent.NONE
        val tx = x + way.dx
        val ty = y + way.dy
        if (tx !in 0 until columns || ty >= depth) return this to DeepEvent.NONE
        // On the surface the digger just walks along.
        if (ty < 0) return copy(x = tx) to DeepEvent.WALK
        val i = ty * columns + tx
        val t = tiles[i]
        if (hits[i] >= t.hardness) return moveTo(tx, ty, null).let { (next, event) -> next to (if (event == DeepEvent.CHAMBER) event else DeepEvent.WALK) }
        val taken = hits.toMutableList().also { it[i]++ }
        val cracked = copy(hits = taken)
        if (taken[i] < t.hardness) return cracked to DeepEvent.CRACK
        return cracked.moveTo(tx, ty, t.find)
    }

    /** The digger moved into the open tile ([tx], [ty]), picking up [find]. */
    private fun moveTo(tx: Int, ty: Int, find: Int?): Pair<DigDeeper, DeepEvent> {
        val picked = if (find != null) found + find else found
        val event = when {
            ty == depth - 1 -> DeepEvent.CHAMBER
            find != null -> DeepEvent.FIND
            else -> DeepEvent.BREAK
        }
        // The bottom row is the chamber's roof: the digger drops straight through it.
        return copy(x = tx, y = if (ty == depth - 1) depth else ty, found = picked) to event
    }

    /** The way the keyboard and screen reader's "Dig down" goes: always down, which always ends the round. */
    fun next(): Pair<DigDeeper, DeepEvent> = dig(DigWay.DOWN)

    companion object {
        const val COLUMNS = 7
        const val DEPTH = 12
        const val LAYERS = 4
        const val FINDS = 6

        /**
         * A new round, the same for the same [seed]: [DEPTH] rows in [LAYERS] layers that get harder further down,
         * with [FINDS] finds scattered near the middle, one or two per layer. With [slabs], one row of the third
         * layer has a run of hard slabs across part of it.
         */
        fun start(seed: Int, slabs: Boolean = false, columns: Int = COLUMNS, depth: Int = DEPTH): DigDeeper {
            val random = Random(seed)
            val perLayer = depth / LAYERS
            val tiles = MutableList(columns * depth) { i ->
                val layer = ((i / columns) / perLayer).coerceAtMost(LAYERS - 1)
                val hardness = when (layer) {
                    0 -> 1
                    1 -> if (random.nextFloat() < 0.3f) 2 else 1
                    2 -> 2
                    else -> if (random.nextFloat() < 0.4f) 3 else 2
                }
                DeepTile(layer, hardness)
            }
            if (slabs) {
                val row = 2 * perLayer + random.nextInt(perLayer)
                val length = 3 + random.nextInt(2)
                val from = random.nextInt(columns - length + 1)
                for (k in from until from + length) tiles[row * columns + k] = tiles[row * columns + k].copy(hardness = 3, slab = true)
            }
            // The finds: spread down the shaft, on rows apart, never in the bottom row (the chamber's roof).
            val mid = columns / 2
            val rows = (1 until depth - 1).shuffled(random).take(FINDS).sorted()
            rows.forEachIndexed { find, row ->
                val col = (mid + random.nextInt(-2, 3)).coerceIn(0, columns - 1)
                val i = row * columns + col
                tiles[i] = tiles[i].copy(find = find)
            }
            return DigDeeper(columns, depth, tiles, x = mid)
        }
    }
}
