// Sand gem match's drawing: the board in its frame, the glossy gems, and the rings for the selected gem, the
// keyboard's focus and the hint.

/** Where the board sits in a play area [width] x [height] (pixels): a square, centered, [size] cells across. */
internal class GemGrid(width: Float, height: Float, val size: Int) {
    val side: Float = min(width, height)
    val origin: Offset = Offset((width - side) / 2f, (height - side) / 2f)

    /** The frame's thickness. */
    val pad: Float = side * 0.05f

    val cell: Float = (side - 2 * pad) / size

    /** The well inside the frame. */
    val well: Rect get() = Rect(origin.x + pad, origin.y + pad, origin.x + side - pad, origin.y + side - pad)

    /** The middle of the cell at [row] (may be fractional or above the board) and [column]. */
    fun center(row: Float, column: Int): Offset = Offset(origin.x + pad + (column + 0.5f) * cell, origin.y + pad + (row + 0.5f) * cell)

    fun center(cell: Int): Offset = center((cell / size).toFloat(), cell % size)

    /** The cell under [p], or null off the board. */
    fun cellAt(p: Offset): Int? {
        val c = ((p.x - origin.x - pad) / cell).toInt()
        val r = ((p.y - origin.y - pad) / cell).toInt()
        if (p.x < origin.x + pad || p.y < origin.y + pad || c !in 0 until size || r !in 0 until size) return null
        return r * size + c
    }
}

/** The frame and the checkered well, with the dusk sky and its stars behind the Mars board. */
internal fun DrawScope.drawGemBoard(look: GemLook, grid: GemGrid, t: Float) {
    val o = grid.origin
    val s = grid.side
    val corner = s * 0.06f
    drawRoundRect(Color.Black.copy(alpha = 0.18f), o + Offset(0f, s * 0.015f), Size(s, s), CornerRadius(corner))
    drawRoundRect(look.frameDark, o, Size(s, s), CornerRadius(corner))
    drawRoundRect(
        Brush.verticalGradient(listOf(look.frame, look.frameDark), o.y, o.y + s),
        o + Offset(s * 0.008f, s * 0.006f),
        Size(s - s * 0.016f, s - s * 0.02f),
        CornerRadius(corner * 0.9f),
    )
    // Planks or plates along the frame, and its trim: gold corners on the chest, copper rivets on Mars.
    val w = grid.well
    if (!look.stars) {
        for (k in 1..3) {
            val y = o.y + grid.pad * 0.5f * k / 2f
            drawLine(look.frameDark.copy(alpha = 0.4f), Offset(o.x + corner, y), Offset(o.x + s - corner, y), s * 0.003f)
        }
        val bracket = grid.pad * 1.5f
        for ((cx, cy) in listOf(o.x to o.y, o.x + s to o.y, o.x to o.y + s, o.x + s to o.y + s)) {
            val l = if (cx == o.x) cx else cx - bracket
            val top = if (cy == o.y) cy else cy - bracket
            drawRoundRect(look.trim, Offset(l, top), Size(bracket, bracket), CornerRadius(corner * 0.8f))
            drawCircle(look.frameDark.copy(alpha = 0.5f), grid.pad * 0.16f, Offset(l + bracket / 2, top + bracket / 2))
        }
    } else {
        val n = 6
        for (k in 0..n) {
            val f = k / n.toFloat()
            for (p in listOf(
                Offset(o.x + grid.pad / 2, o.y + grid.pad / 2 + f * (s - grid.pad)),
                Offset(o.x + s - grid.pad / 2, o.y + grid.pad / 2 + f * (s - grid.pad)),
                Offset(o.x + grid.pad / 2 + f * (s - grid.pad), o.y + grid.pad / 2),
                Offset(o.x + grid.pad / 2 + f * (s - grid.pad), o.y + s - grid.pad / 2),
            )) {
                drawCircle(look.frameDark, grid.pad * 0.2f, p + Offset(0f, grid.pad * 0.04f))
                drawCircle(look.trim, grid.pad * 0.16f, p)
            }
        }
    }
    // The well: its light, then the checkered tiles over it.
    val wellCorner = CornerRadius(corner * 0.55f)
    drawRoundRect(Brush.verticalGradient(listOf(look.wellTop, look.wellBottom), w.top, w.bottom), w.topLeft, w.size, wellCorner)
    for (r in 0 until grid.size) for (c in 0 until grid.size) {
        val tl = Offset(w.left + c * grid.cell, w.top + r * grid.cell)
        val color = if ((r + c) % 2 == 0) look.tileA else look.tileB
        drawRoundRect(color.copy(alpha = 0.55f), tl + Offset(grid.cell * 0.04f, grid.cell * 0.04f), Size(grid.cell * 0.92f, grid.cell * 0.92f), CornerRadius(grid.cell * 0.16f))
    }
    if (look.stars) {
        for (k in 0 until 14) {
            val x = w.left + w.width * ((k * 0.618f + 0.1f) % 1f)
            val y = w.top + w.height * 0.55f * ((k * 0.377f + 0.05f) % 1f)
            val twinkle = 0.35f + 0.3f * sin(t * 1.3f + k * 2.1f)
            drawCircle(Color.White.copy(alpha = twinkle), grid.cell * (0.025f + 0.012f * (k % 3)), Offset(x, y))
        }
    }
    // An inner shadow along the top of the well.
    drawRoundRect(
        Brush.verticalGradient(listOf(Color.Black.copy(alpha = 0.2f), Color.Transparent), w.top, w.top + grid.cell * 0.5f),
        w.topLeft,
        Size(w.width, grid.cell * 0.5f),
        wellCorner,
    )
}

/** A gem of [style], [r] from its middle [c] to its edge, with a glint as [shine] (0 to 1) passes. */
internal fun DrawScope.drawGem(style: GemStyle, c: Offset, r: Float, shine: Float = 0f) {
    drawCircle(Color.Black.copy(alpha = 0.16f), r * 0.82f, c + Offset(r * 0.06f, r * 0.14f))
    translate(c.x, c.y) {
        when (style.shape) {
            GemShape.PEARL -> pearl(style, r)
            GemShape.GLASS -> seaGlass(style, r)
            GemShape.HEX -> faceted(style, polygonPath(6, r * 0.92f, 0f, 1f, 1f))
            GemShape.DROP -> drop(style, r)
            GemShape.STAR -> star(style, r)
            GemShape.SHARD -> faceted(style, polygonPath(6, r, 0f, 0.72f, 1.02f))
            GemShape.METEOR -> meteor(style, r)
            GemShape.DIAMOND -> faceted(style, polygonPath(4, r, -TAU / 4, 0.86f, 1.04f))
            GemShape.TRIANGLE -> translate(0f, r * 0.14f) { faceted(style, polygonPath(3, r * 1.08f, -TAU / 4, 1f, 1f)) }
            GemShape.OCTAGON -> faceted(style, polygonPath(8, r * 0.92f, TAU / 16, 1f, 1f))
        }
    }
    if (shine > 0f && shine < 1f) drawSparkle(c + Offset(r * 0.4f, -r * 0.45f), r * 0.55f * sin(shine * 3.1416f), Color.White)
}

/** A regular polygon of [sides] around (0, 0), [r] to a corner, turned by [turn] radians, stretched [sx], [sy]. */
private fun polygonPath(sides: Int, r: Float, turn: Float, sx: Float, sy: Float): Path = Path().apply {
    for (k in 0 until sides) {
        val a = turn + k * TAU / sides
        val x = cos(a) * r * sx
        val y = sin(a) * r * sy
        if (k == 0) moveTo(x, y) else lineTo(x, y)
    }
    close()
}

/**
 * A cut gem in [outline]: a dark rim, a body lit from the top left, a bright table in the middle with facet lines
 * running out to the rim, and a highlight.
 */
private fun DrawScope.faceted(style: GemStyle, outline: Path) {
    val b = outline.getBounds()
    drawPath(outline, style.dark)
    scale(0.84f, 0.84f, Offset.Zero) {
        drawPath(outline, Brush.linearGradient(listOf(style.light, style.mid, style.dark), b.topLeft, b.bottomRight))
    }
    scale(0.46f, 0.46f, Offset.Zero) {
        drawPath(outline, Brush.linearGradient(listOf(Color.White.copy(alpha = 0.9f), style.light), b.topLeft, b.bottomRight))
    }
    // The rim catches the light; the step down from the table is in shade.
    val r = b.maxDimension / 2
    drawPath(outline, Color.White.copy(alpha = 0.35f), style = Stroke(r * 0.04f))
    scale(0.84f, 0.84f, Offset.Zero) { drawPath(outline, style.dark.copy(alpha = 0.3f), style = Stroke(r * 0.05f)) }
    scale(0.46f, 0.46f, Offset.Zero) { drawPath(outline, Color.White.copy(alpha = 0.6f), style = Stroke(r * 0.07f)) }
    rotate(-35f, Offset.Zero) {
        drawOval(Color.White.copy(alpha = 0.85f), Offset(-r * 0.32f, -r * 0.62f), Size(r * 0.42f, r * 0.16f))
    }
}

private fun DrawScope.pearl(style: GemStyle, r: Float) {
    val rr = r * 0.82f
    drawCircle(
        Brush.radialGradient(
            0f to Color.White,
            0.5f to style.mid,
            1f to style.dark,
            center = Offset(-rr * 0.35f, -rr * 0.35f),
            radius = rr * 1.5f,
        ),
        rr,
        Offset.Zero,
    )
    drawCircle(Color(0xFFFFD2E6).copy(alpha = 0.45f), rr * 0.9f, Offset.Zero, style = Stroke(rr * 0.1f))
    drawCircle(Color(0xFFB8E8FF).copy(alpha = 0.3f), rr * 0.7f, Offset(rr * 0.08f, rr * 0.1f), style = Stroke(rr * 0.08f))
    drawCircle(Color.White, rr * 0.2f, Offset(-rr * 0.36f, -rr * 0.38f))
}

private fun DrawScope.seaGlass(style: GemStyle, r: Float) {
    val h = r * 0.8f
    rotate(12f, Offset.Zero) {
        drawRoundRect(style.dark, Offset(-h, -h), Size(2 * h, 2 * h), CornerRadius(h * 0.55f))
        drawRoundRect(
            Brush.linearGradient(listOf(style.light, style.mid), Offset(-h, -h), Offset(h, h)),
            Offset(-h * 0.86f, -h * 0.86f),
            Size(h * 1.72f, h * 1.72f),
            CornerRadius(h * 0.48f),
        )
        // Frosted, worn by the sea: a soft milky patch and a glossy edge.
        drawCircle(Color.White.copy(alpha = 0.28f), h * 0.55f, Offset(h * 0.1f, h * 0.15f))
        drawRoundRect(Color.White.copy(alpha = 0.75f), Offset(-h * 0.62f, -h * 0.66f), Size(h * 0.8f, h * 0.2f), CornerRadius(h * 0.1f))
    }
}

private fun DrawScope.drop(style: GemStyle, r: Float) {
    val path = Path().apply {
        moveTo(0f, -r * 0.98f)
        cubicTo(r * 0.3f, -r * 0.5f, r * 0.82f, -r * 0.05f, r * 0.82f, r * 0.3f)
        cubicTo(r * 0.82f, r * 0.75f, r * 0.42f, r * 0.92f, 0f, r * 0.92f)
        cubicTo(-r * 0.42f, r * 0.92f, -r * 0.82f, r * 0.75f, -r * 0.82f, r * 0.3f)
        cubicTo(-r * 0.82f, -r * 0.05f, -r * 0.3f, -r * 0.5f, 0f, -r * 0.98f)
        close()
    }
    drawPath(path, style.dark)
    scale(0.84f, 0.84f, Offset(0f, r * 0.1f)) {
        drawPath(path, Brush.radialGradient(listOf(style.light, style.mid, style.dark), Offset(-r * 0.25f, -r * 0.1f), r * 1.2f))
    }
    drawCircle(Color.White.copy(alpha = 0.3f), r * 0.32f, Offset(r * 0.1f, r * 0.38f))
    rotate(-30f, Offset.Zero) { drawOval(Color.White.copy(alpha = 0.85f), Offset(-r * 0.42f, -r * 0.1f), Size(r * 0.18f, r * 0.42f)) }
}

private fun DrawScope.star(style: GemStyle, r: Float) {
    val path = starPath(0.5f)
    translate(0f, r * 0.06f) {
        scale(r * 1.02f, r * 1.02f, Offset.Zero) { drawPath(path, style.dark) }
        scale(r * 0.86f, r * 0.86f, Offset.Zero) {
            drawPath(path, Brush.linearGradient(listOf(style.light, style.mid, style.dark), Offset(-1f, -1f), Offset(1f, 1f)))
        }
        // A ridge from the middle out to each point.
        for (k in 0 until 5) {
            val a = -TAU / 4 + k * TAU / 5
            drawLine(Color.White.copy(alpha = 0.5f), Offset.Zero, Offset(cos(a) * r * 0.78f, sin(a) * r * 0.78f), r * 0.05f, StrokeCap.Round)
        }
        drawCircle(Color.White.copy(alpha = 0.8f), r * 0.12f, Offset(-r * 0.05f, -r * 0.08f))
    }
}

private fun DrawScope.meteor(style: GemStyle, r: Float) {
    val bumps = floatArrayOf(0.9f, 0.82f, 0.94f, 0.86f, 0.92f, 0.8f, 0.9f, 0.85f, 0.95f, 0.84f)
    val path = Path().apply {
        for (k in bumps.indices) {
            val a = k * TAU / bumps.size
            val p = Offset(cos(a) * r * bumps[k], sin(a) * r * bumps[k])
            if (k == 0) moveTo(p.x, p.y) else lineTo(p.x, p.y)
        }
        close()
    }
    drawPath(path, style.dark)
    scale(0.88f, 0.88f, Offset.Zero) {
        drawPath(path, Brush.radialGradient(listOf(style.light, style.mid, style.dark), Offset(-r * 0.3f, -r * 0.35f), r * 1.3f))
    }
    // Glowing seams of molten orange, and a couple of little craters.
    val glow = Color(0xFFFF8A2A)
    drawGlow(Offset(r * 0.05f, r * 0.1f), r * 0.75f, glow.copy(alpha = 0.35f))
    val seam = Path().apply {
        moveTo(-r * 0.55f, -r * 0.1f)
        lineTo(-r * 0.15f, r * 0.05f)
        lineTo(r * 0.05f, -r * 0.3f)
        lineTo(r * 0.5f, -r * 0.2f)
        moveTo(-r * 0.15f, r * 0.05f)
        lineTo(r * 0.1f, r * 0.5f)
    }
    drawPath(seam, glow, style = Stroke(r * 0.1f, cap = StrokeCap.Round))
    drawPath(seam, Color(0xFFFFE08A), style = Stroke(r * 0.035f, cap = StrokeCap.Round))
    drawCircle(style.dark.copy(alpha = 0.55f), r * 0.11f, Offset(r * 0.35f, r * 0.32f))
    drawCircle(style.dark.copy(alpha = 0.5f), r * 0.08f, Offset(-r * 0.4f, r * 0.35f))
    drawOval(Color.White.copy(alpha = 0.55f), Offset(-r * 0.5f, -r * 0.62f), Size(r * 0.4f, r * 0.14f))
}

/** A soft glowing ring around a gem: the selected one bright, a hint pulsing with [pulse] (0 to 1). */
internal fun DrawScope.drawGemRing(c: Offset, cell: Float, color: Color, pulse: Float) {
    drawGlow(c, cell * (0.62f + 0.06f * pulse), color.copy(alpha = 0.45f + 0.3f * pulse))
    drawRoundRect(
        color.copy(alpha = 0.8f + 0.2f * pulse),
        c - Offset(cell * 0.46f, cell * 0.46f),
        Size(cell * 0.92f, cell * 0.92f),
        CornerRadius(cell * 0.2f),
        style = Stroke(cell * 0.06f),
    )
}

/** The keyboard's ring around a cell. */
internal fun DrawScope.drawGemFocus(c: Offset, cell: Float, color: Color) {
    drawRoundRect(
        color,
        c - Offset(cell * 0.5f, cell * 0.5f),
        Size(cell, cell),
        CornerRadius(cell * 0.22f),
        style = Stroke(cell * 0.07f),
    )
    drawRoundRect(
        Color.White,
        c - Offset(cell * 0.43f, cell * 0.43f),
        Size(cell * 0.86f, cell * 0.86f),
        CornerRadius(cell * 0.18f),
        style = Stroke(cell * 0.025f),
    )
}
