// The Sea Floor's creatures and the Desert's travellers, in the order they are earned. See KeepsakeArt.kt for the box.

internal fun DrawScope.seaKeepsake(stage: Int, t: Float, g: SceneGrade) = when (stage) {
    1 -> clownfish(t, g)
    2 -> seahorse(t, g)
    3 -> octopus(t, g)
    4 -> seaTurtle(t, g)
    else -> treasureChest(t, g)
}

internal fun DrawScope.desertKeepsake(stage: Int, t: Float, g: SceneGrade) = when (stage) {
    1 -> oasisPalm(t, g)
    2 -> bedouinTent(t, g)
    3 -> camel(t, g)
    4 -> bedouin(t, g)
    else -> pyramid(t, g)
}

/** Three bubbles rising from ([x], [y]), wobbling as they go. */
private fun DrawScope.bubbles(t: Float, x: Float, y: Float, laps: Int) {
    for (k in 0..2) {
        val p = drift(t, laps, k / 3f)
        val bx = x + swing(t, 90, k * 0.3f) * 2f
        val by = y - p * 50f
        drawCircle(Color.White.copy(alpha = 0.7f * (1f - p)), 1.6f + k * 0.6f, Offset(bx, by), style = ring)
    }
}

private val ring = Stroke(0.9f)

/** An orange-and-white clownfish swimming back and forth over the sand. */
private fun DrawScope.clownfish(t: Float, g: SceneGrade) {
    val x = swing(t, 10) * 9f
    val bob = swing(t, 40) * 2f
    // Faces the way it's swimming.
    val facing = if (cos(TAU * t * 10) >= 0f) 1f else -1f
    groundShadow(50f + x, 34f, 0.12f)
    translate(x, bob) {
        scale(facing, 1f, Offset(50f, 60f)) {
            val orange = g(0xFFFF8A1E)
            val dark = g(0xFF2A2328)
            val tail = swing(t, 160) * 8f
            rotate(tail, Offset(32f, 60f)) { drawPath(fishTail, dark); scale(0.8f, 0.8f, Offset(32f, 60f)) { drawPath(fishTail, orange) } }
            oval(dark, 52f, 49f, 9f, 5f)
            oval(orange, 52f, 50f, 8f, 4f)
            oval(dark, 50f, 60f, 21f, 13f)
            clipPath(fishBody) {
                drawPath(fishBody, orange)
                for (sx in floatArrayOf(40f, 54f, 66f)) {
                    oval(dark, sx, 60f, 4.4f, 14f)
                    oval(Color.White, sx, 60f, 3f, 14f)
                }
                oval(g(0xFFD9620C), 50f, 70f, 22f, 4f)
            }
            rotate(swing(t, 120) * 20f, Offset(53f, 66f)) { oval(orange, 53f, 70f, 5f, 3f) }
            dot(Color.White, 63f, 57f, 3.3f)
            eye(63.6f, 57.2f, 2f)
        }
    }
    bubbles(t, 50f + x + facing * 22f, 54f + bob, 30)
}

private val fishBody = Path().apply { addOval(Rect(30f, 48f, 70f, 72f)) }
private val fishTail = polygon(34f, 60f, 20f, 49f, 22f, 60f, 20f, 71f)

/** A yellow seahorse with a curled tail, bobbing upright. */
private fun DrawScope.seahorse(t: Float, g: SceneGrade) {
    val bob = swing(t, 30) * 3f
    groundShadow(52f, 22f, 0.12f)
    translate(0f, bob - 4f) {
        val body = g(0xFFFFB13C)
        val shade = g(0xFFE58A1F)
        val belly = g(0xFFFFD98A)
        rotate(swing(t, 140) * 10f, Offset(42f, 52f)) { oval(g(0xFFFFE3A8).copy(alpha = 0.85f), 38f, 52f, 6f, 9f) }
        for (i in seahorseSpine.indices) dot(shade, seahorseSpine[i].x, seahorseSpine[i].y, seahorseRadii[i])
        for (i in seahorseSpine.indices) dot(body, seahorseSpine[i].x - 0.6f, seahorseSpine[i].y - 0.6f, seahorseRadii[i] - 1.2f)
        for (i in 1..4) oval(belly, seahorseSpine[i].x + 4f, seahorseSpine[i].y, 3.2f, 4.5f)
        for (i in 1..5) stick(shade, seahorseSpine[i].x - 6f, seahorseSpine[i].y - 1f, seahorseSpine[i].x + 2f, seahorseSpine[i].y + 1f, 0.9f)
        oval(body, 66f, 33f, 9f, 3.6f)
        dot(body, 55f, 30f, 9.5f)
        drawPath(seahorseCrown, shade)
        eye(57f, 28f, 2.3f)
        oval(g(0xFFFF8A7A).copy(alpha = 0.5f), 58f, 34f, 3f, 2f)
    }
}

private val seahorseSpine = listOf(
    Offset(50f, 42f), Offset(47f, 53f), Offset(48f, 64f), Offset(52f, 73f), Offset(55f, 81f),
    Offset(53f, 88f), Offset(48f, 90f), Offset(45f, 86f), Offset(48f, 83f),
)
private val seahorseRadii = floatArrayOf(10f, 10.5f, 9f, 7f, 5.5f, 4.5f, 3.8f, 3.2f, 2.6f)
private val seahorseCrown = polygon(48f, 22f, 51f, 15f, 54f, 21f, 57f, 15f, 59f, 22f)

/** A purple octopus waving its curly arms. */
private fun DrawScope.octopus(t: Float, g: SceneGrade) {
    val purple = g(0xFF9B5DE5)
    val dark = g(0xFF7440C2)
    groundShadow(50f, 60f)
    for (i in 0..5) {
        val out = if (i < 3) -1f else 1f
        val spread = (i - 2.5f) / 2.5f
        val wave = swing(t, 36, i * 0.17f)
        for (k in 0..8) {
            val s = k / 8f
            val curl = if (s > 0.7f) (s - 0.7f) * 30f else 0f
            val x = 36f + i * 5.6f + spread * s * s * 20f + wave * sin(s * PI.toFloat()) * 3f + out * curl * 0.3f
            val y = 62f + s * 28f - curl
            dot(if (i % 2 == 0) dark else purple, x, y, 6.5f * (1f - s * 0.65f))
        }
    }
    oval(dark, 50f, 48f, 21f, 22f)
    oval(purple, 49f, 46f, 19.5f, 20.5f)
    oval(Color.White.copy(alpha = 0.3f), 42f, 34f, 6f, 4f)
    dot(g(0xFFC9A3F5), 58f, 36f, 2.6f)
    dot(g(0xFFC9A3F5), 63f, 44f, 1.8f)
    dot(g(0xFFC9A3F5), 37f, 50f, 1.8f)
    oval(Color.White, 42f, 52f, 5f, 6f)
    oval(Color.White, 56f, 52f, 5f, 6f)
    eye(43f, 53f, 3f)
    eye(57f, 53f, 3f)
    oval(g(0xFFFF8FB8).copy(alpha = 0.55f), 37f, 60f, 3.5f, 2f)
    oval(g(0xFFFF8FB8).copy(alpha = 0.55f), 61f, 60f, 3.5f, 2f)
}

/**
 * A green sea turtle gliding along, paddling its flippers. Out in open water ([swimming], as in the Sea Floor
 * scene) it has no shadow on the ground and no bubbles.
 */
internal fun DrawScope.seaTurtle(t: Float, g: SceneGrade, swimming: Boolean = false) {
    val bob = swing(t, 24) * 3f
    val paddle = swing(t, 40) * 16f
    if (!swimming) groundShadow(50f, 56f, 0.12f)
    translate(0f, bob - 6f) {
        val skin = g(0xFF8FC46E)
        val skinDark = g(0xFF6A9F4E)
        // The far front flipper, sweeping back along the body like a wing.
        rotate(paddle, Offset(64f, 58f)) { drawPath(farFlipper, skinDark) }
        rotate(paddle, Offset(36f, 60f)) { oval(skinDark, 30f, 54f, 7f, 3.5f) }
        drawPath(turtleTail, skinDark)
        oval(skin, 79f, 58f, 9.5f, 7f)
        eye(83f, 56f, 1.8f)
        oval(g(0xFF3F6B2C), 50f, 62f, 25f, 15f)
        oval(g(0xFF5E8C3A), 50f, 60f, 24f, 13.5f)
        val plate = g(0xFF86B556)
        oval(plate, 50f, 56f, 7f, 5f)
        oval(plate, 37f, 59f, 6f, 4.5f)
        oval(plate, 63f, 59f, 6f, 4.5f)
        oval(plate, 44f, 66f, 6f, 3.5f)
        oval(plate, 57f, 66f, 6f, 3.5f)
        oval(g(0xFFD9C98A), 50f, 72f, 22f, 3f)
        // The near front flipper: long, rooted at the front of the shell, its tip trailing back toward the tail.
        rotate(paddle, Offset(66f, 68f)) { drawPath(nearFlipper, skin) }
        rotate(-paddle, Offset(36f, 70f)) { oval(skin, 33f, 75f, 8f, 3.5f) }
        oval(Color.White.copy(alpha = 0.3f), 44f, 52f, 8f, 3f)
    }
    if (!swimming) bubbles(t, 86f, 50f + bob, 24)
}

private val turtleTail = polygon(27f, 60f, 18f, 63f, 27f, 66f)
private val nearFlipper = Path().apply {
    moveTo(70f, 66f)
    quadraticTo(60f, 85f, 43f, 88f)
    // A rounded tip.
    cubicTo(36f, 89f, 33f, 83f, 39f, 80f)
    quadraticTo(52f, 76f, 60f, 69f)
    close()
}
private val farFlipper = Path().apply {
    moveTo(68f, 55f)
    quadraticTo(60f, 45f, 47f, 44f)
    cubicTo(42f, 43.5f, 40.5f, 48f, 45f, 49.5f)
    quadraticTo(54f, 52f, 58f, 58f)
    close()
}

/** An open treasure chest full of gold, twinkling and letting out bubbles. */
private fun DrawScope.treasureChest(t: Float, g: SceneGrade) {
    val wood = g(0xFF8A5530)
    val woodDark = g(0xFF5E3519)
    val gold = g(0xFFF2C14A)
    val goldDark = g(0xFFC98E22)
    groundShadow(50f, 66f)
    box(woodDark, 22f, 32f, 78f, 52f, 6f)
    box(wood, 24f, 34f, 76f, 50f, 5f)
    box(gold, 30f, 33f, 35f, 51f)
    box(gold, 65f, 33f, 70f, 51f)
    box(g(0xFF3A1F0E), 24f, 50f, 76f, 64f)
    for (i in 0..5) {
        val x = 30f + i * 8f
        dot(goldDark, x, 62f - (i % 2) * 3f, 5.5f)
        dot(gold, x - 0.6f, 61f - (i % 2) * 3f, 4.5f)
    }
    dot(g(0xFFE24A57), 44f, 57f, 2.6f)
    dot(g(0xFF4FB0E8), 59f, 58f, 2.4f)
    box(woodDark, 22f, 62f, 78f, 95f, 3f)
    box(wood, 24f, 64f, 76f, 93f, 2f)
    box(woodDark, 24f, 76f, 76f, 78f)
    box(goldDark, 29f, 62f, 35f, 95f)
    box(gold, 30f, 62f, 34f, 95f)
    box(goldDark, 65f, 62f, 71f, 95f)
    box(gold, 66f, 62f, 70f, 95f)
    box(goldDark, 45f, 66f, 55f, 78f, 2f)
    box(gold, 46f, 67f, 54f, 77f, 2f)
    dot(woodDark, 50f, 71f, 1.6f)
    val twinkle = swing(t, 30)
    if (twinkle > 0.3f) drawSparkle(Offset(40f, 54f), 5f, Color.White.copy(alpha = (twinkle - 0.3f) * 1.4f))
    val twinkle2 = swing(t, 30, 0.5f)
    if (twinkle2 > 0.3f) drawSparkle(Offset(62f, 55f), 4f, Color.White.copy(alpha = (twinkle2 - 0.3f) * 1.4f))
    bubbles(t, 56f, 48f, 20)
}

/** A little oasis: a palm leaning over a pond, its fronds stirring. */
private fun DrawScope.oasisPalm(t: Float, g: SceneGrade) {
    oval(g(0xFF2E8FB8), 48f, 92f, 34f, 5.5f)
    oval(g(0xFF5DC0DE), 46f, 91f, 28f, 3.6f)
    stick(Color.White.copy(alpha = 0.5f), 34f + swing(t, 20) * 2f, 91f, 42f + swing(t, 20) * 2f, 91f, 0.8f)
    val grass = g(0xFF4C9A44)
    for (x in floatArrayOf(16f, 20f, 76f, 81f)) stick(grass, x, 94f, x + (x - 48f) * 0.08f, 85f, 1.6f)
    val trunk = g(0xFF9A6A3E)
    val ring = g(0xFF6E4728)
    for (k in 0..9) {
        val s = k / 9f
        val x = 52f + s * s * 10f
        val y = 92f - s * 56f
        oval(ring, x, y, 4.6f - s * 1.2f, 3.4f)
        oval(trunk, x - 0.4f, y - 0.6f, 4.2f - s * 1.2f, 2.8f)
    }
    val crownX = 62f
    val crownY = 34f
    val sway = swing(t, 18) * 4f
    val dark = g(0xFF2F7A3A)
    val green = g(0xFF4EAA4E)
    for (i in 0..2) {
        val a = -30f + i * 32f
        for (side in floatArrayOf(-1f, 1f)) {
            translate(crownX, crownY) {
                scale(side, 1f, Offset.Zero) {
                    rotate(a + sway * side, Offset.Zero) { drawPath(frond, if (i == 1) green else dark) }
                }
            }
        }
    }
    dot(g(0xFF7A3E1E), crownX - 2f, crownY + 3f, 2.4f)
    dot(g(0xFF8E4B22), crownX + 2f, crownY + 4f, 2.4f)
}

private val frond = Path().apply {
    moveTo(0f, 0f)
    quadraticBezierTo(18f, -11f, 34f, 6f)
    quadraticBezierTo(18f, -2f, 0f, 4f)
    close()
}

/** A Bedouin tent of striped goat-hair cloth, its door open on a red rug, a lantern glowing by it. */
private fun DrawScope.bedouinTent(t: Float, g: SceneGrade) {
    groundShadow(50f, 86f)
    val rope = g(0xFF8A6A48)
    stick(rope, 22f, 58f, 6f, 94f, 0.9f)
    stick(rope, 82f, 56f, 96f, 94f, 0.9f)
    drawPath(tent, g(0xFF4A3426))
    clipPath(tent) {
        val stripe = g(0xFF7A5A3E)
        for (y in floatArrayOf(60f, 72f, 84f)) box(stripe, 0f, y, 100f, y + 3f)
        box(g(0xFFD9B98A), 0f, 66f, 100f, 67.5f)
        drawPath(tentShade, Color.Black.copy(alpha = 0.18f))
    }
    drawPath(tentDoor, g(0xFF22160F))
    drawPath(tentFlap, g(0xFF6A4A33))
    box(g(0xFFB3322E), 36f, 90f, 66f, 96f, 1f)
    for (x in floatArrayOf(40f, 47f, 54f, 61f)) dot(g(0xFFF2C14A), x, 93f, 1f)
    val glow = 0.75f + 0.25f * swing(t, 70)
    dot(g(0xFFFFD27A).copy(alpha = 0.35f * glow), 72f, 86f, 7f)
    box(g(0xFF6B4A2E), 70f, 82f, 74f, 91f, 1.5f)
    dot(g(0xFFFFE6A0).copy(alpha = glow), 72f, 86.5f, 1.8f)
}

private val tent = polygon(10f, 94f, 16f, 62f, 32f, 52f, 50f, 58f, 68f, 50f, 86f, 60f, 92f, 94f)
private val tentShade = polygon(68f, 50f, 86f, 60f, 92f, 94f, 70f, 94f)
private val tentDoor = polygon(40f, 94f, 46f, 66f, 58f, 66f, 64f, 94f)
private val tentFlap = polygon(58f, 66f, 64f, 94f, 70f, 94f, 62f, 64f)

/** A dromedary with a red saddle blanket, nodding as it chews, swishing its tail. */
private fun DrawScope.camel(t: Float, g: SceneGrade) {
    val coat = g(0xFFD49A5C)
    val shade = g(0xFFAE7740)
    groundShadow(50f, 66f)
    // Far legs first, in shade.
    stick(shade, 38f, 64f, 36f, 94f, 4.5f)
    stick(shade, 70f, 64f, 72f, 94f, 4.5f)
    rotate(swing(t, 30) * 8f, Offset(76f, 56f)) { stick(shade, 76f, 56f, 79f, 72f, 1.6f) }
    oval(coat, 54f, 60f, 23f, 12f)
    oval(coat, 54f, 47f, 12f, 11f)
    box(g(0xFFB3322E), 44f, 46f, 64f, 62f, 3f)
    box(g(0xFFF2C14A), 44f, 59f, 64f, 62f)
    for (x in floatArrayOf(46f, 51f, 56f, 61f)) stick(g(0xFFF2C14A), x, 62f, x, 66f, 1f)
    stick(coat, 42f, 64f, 41f, 95f, 5f)
    stick(coat, 64f, 64f, 66f, 95f, 5f)
    dot(shade, 41.5f, 80f, 2.8f)
    dot(shade, 65f, 80f, 2.8f)
    val nod = swing(t, 26) * 1.5f
    drawPath(camelNeck, coat)
    translate(0f, nod) {
        oval(coat, 18f, 30f, 9f, 6.5f)
        oval(coat, 11f, 33f, 5f, 4f)
        oval(shade, 23f, 25f, 2f, 3f)
        eye(17f, 28.5f, 1.5f)
        stick(shade, 7f, 34f, 10f, 35f, 0.8f)
    }
    oval(Color.White.copy(alpha = 0.25f), 50f, 40f, 6f, 2.5f)
}

private val camelNeck = polygon(36f, 54f, 32f, 66f, 22f, 52f, 13f, 32f, 23f, 28f, 30f, 46f)

/** A Bedouin in a white headscarf and a flowing blue cloak, leaning on a staff, swaying slightly. */
private fun DrawScope.bedouin(t: Float, g: SceneGrade) {
    groundShadow(52f, 40f)
    val skin = g(0xFFB27A50)
    rotate(swing(t, 10) * 1.5f, Offset(50f, GROUND)) {
        stick(g(0xFF7A5230), 71f, 22f, 73f, 95f, 2.2f)
        drawPath(robe, g(0xFFF3EEE4))
        drawPath(cloakLeft, g(0xFF2E4A7D))
        drawPath(cloakRight, g(0xFF243C68))
        box(g(0xFFC9963A), 43f, 62f, 57f, 65f, 1f)
        drawPath(scarf, g(0xFFFAF7F0))
        oval(skin, 50f, 31f, 6f, 7.5f)
        oval(g(0xFF3A2A20), 50f, 37.6f, 5.6f, 3.2f)
        eye(47.5f, 30f, 1.1f)
        eye(52.5f, 30f, 1.1f)
        box(g(0xFF2A2420), 40f, 21f, 60f, 24.5f, 1.8f)
        arm(56f, 46f, 15f, 20f, 5f, g(0xFF2E4A7D), skin)
    }
}

private val robe = polygon(42f, 40f, 58f, 40f, 63f, 95f, 37f, 95f)
private val cloakLeft = polygon(40f, 40f, 48f, 42f, 44f, 95f, 31f, 95f)
private val cloakRight = polygon(52f, 42f, 60f, 40f, 69f, 95f, 56f, 95f)
private val scarf = Path().apply {
    moveTo(40f, 24f)
    quadraticBezierTo(50f, 14f, 60f, 24f)
    lineTo(63f, 46f)
    lineTo(56f, 44f)
    lineTo(56f, 26f)
    lineTo(44f, 26f)
    lineTo(44f, 44f)
    lineTo(37f, 46f)
    close()
}

/** A pyramid in the dunes: a sunlit face and a shaded one, stone courses, a golden capstone that glints. */
private fun DrawScope.pyramid(t: Float, g: SceneGrade) {
    groundShadow(54f, 96f, 0.18f)
    drawPath(pyramidLit, g(0xFFF0C77A))
    drawPath(pyramidShade, g(0xFFC0844A))
    val course = g(0xFFB98447).copy(alpha = 0.55f)
    val courseShade = g(0xFF8E5B30).copy(alpha = 0.6f)
    var y = 26f
    var row = 0
    while (y < 90f) {
        val s = (y - 10f) / 80f
        val left = 50f - 46f * s
        val ridge = 50f + 8f * s
        val right = 50f + 46f * s
        stick(course, left, y, ridge, y, 0.8f)
        stick(courseShade, ridge, y, right, y, 0.8f)
        // A few block joints, staggered row to row.
        var x = left + if (row % 2 == 0) 6f else 11f
        while (x < ridge - 3f) {
            stick(course, x, y, x, y + 7f, 0.6f)
            x += 11f
        }
        y += 8f
        row++
    }
    drawPath(capLit, g(0xFFFFDE7A))
    drawPath(capShade, g(0xFFDDA436))
    val glint = swing(t, 12)
    if (glint > 0.4f) drawSparkle(Offset(50f, 11f), 7f * glint, Color.White.copy(alpha = (glint - 0.4f) * 1.6f))
    drawPath(dune, g(0xFFE3A15E))
    drawPath(duneLit, g(0xFFF2BC7A))
}

private val pyramidLit = polygon(50f, 10f, 4f, 90f, 58f, 90f)
private val pyramidShade = polygon(50f, 10f, 58f, 90f, 96f, 90f)
private val capLit = polygon(50f, 10f, 45.4f, 18f, 50.8f, 18f)
private val capShade = polygon(50f, 10f, 50.8f, 18f, 54.6f, 18f)
private val dune = Path().apply {
    moveTo(0f, 96f)
    quadraticBezierTo(14f, 82f, 36f, 88f)
    quadraticBezierTo(58f, 94f, 76f, 86f)
    quadraticBezierTo(90f, 81f, 100f, 90f)
    lineTo(100f, 97f)
    lineTo(0f, 97f)
    close()
}
private val duneLit = Path().apply {
    moveTo(0f, 96f)
    quadraticBezierTo(14f, 84f, 34f, 90f)
    quadraticBezierTo(18f, 90f, 6f, 97f)
    close()
}
