package io.colorsand.ui.minigame

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Color
import io.colorsand.core.Arena
import io.colorsand.core.KeepsakeGame
import io.colorsand.ui.arena.SceneGrade

/** How a [MemoryLook]'s cards are made: woven rug tiles in the tent, or riveted metal plates under the stars. */
internal enum class MemoryStyle { RUG, METAL }

/** A keepsake shown on a pair of cards: [arena]'s keepsake for [stage], painted by the arenas' own art. */
internal class MemoryFace(val arena: Arena, val stage: Int) {
    /** The keepsake's name as it reads in a sentence ("camel"). */
    val name: String = KeepsakeGame.of(arena, stage).keepsake
}

/**
 * The look of Keepsake memory in one arena: the card [style], the card backs' colors ([back], [backLight],
 * [backDark] and the [backAccent] of their pattern), the faces' [face] and [faceEdge], the [glow] around a found
 * pair, the backdrop the cards lie on ([backdrop] to [backdropDark]) and the six keepsakes on the [faces].
 */
internal class MemoryLook(
    val style: MemoryStyle,
    val back: Color,
    val backLight: Color,
    val backDark: Color,
    val backAccent: Color,
    val backTrim: Color,
    val face: Color,
    val faceLight: Color,
    val faceEdge: Color,
    val glow: Color,
    val backdrop: Color,
    val backdropDark: Color,
    val backdropTrim: Color,
    val faces: List<MemoryFace>,
    /** What the line under the cards says before the first card is turned. */
    val hello: String,
) {
    companion object {
        /** [arena]'s memory game, its colors through [g]. Arenas without one get the tent's. */
        fun of(arena: Arena, g: SceneGrade): MemoryLook = when (arena) {
            Arena.MARS -> MemoryLook(
                MemoryStyle.METAL,
                back = g(0xFFAFB9C6), backLight = g(0xFFE6EBF1), backDark = g(0xFF6E7987),
                backAccent = g(0xFF7ED957), backTrim = g(0xFFFF7FB0),
                face = g(0xFF1C2150), faceLight = g(0xFF3A2E6E), faceEdge = g(0xFFC9D0D8),
                glow = g(0xFF9CFFD2),
                backdrop = g(0xFF2A2157), backdropDark = g(0xFF0F1433), backdropTrim = g(0xFF9AA3AE),
                faces = listOf(
                    MemoryFace(Arena.MARS, 1),
                    MemoryFace(Arena.MARS, 2),
                    MemoryFace(Arena.MARS, 3),
                    MemoryFace(Arena.MARS, 4),
                    MemoryFace(Arena.MARS, 5),
                    // The alien's souvenir from Earth.
                    MemoryFace(Arena.PLAYGROUND, 1),
                ),
                hello = "Turn two cards to find the alien's pairs!",
            )
            else -> MemoryLook(
                MemoryStyle.RUG,
                back = g(0xFFB4383A), backLight = g(0xFFD2554F), backDark = g(0xFF7E2229),
                backAccent = g(0xFFE7A93C), backTrim = g(0xFF2F3E7A),
                face = g(0xFFF7E9CC), faceLight = g(0xFFFFF7E6), faceEdge = g(0xFFC98A4B),
                glow = g(0xFFFFDA6B),
                backdrop = g(0xFFEED6A8), backdropDark = g(0xFFDDB57C), backdropTrim = g(0xFFB4383A),
                // A keepsake from every arena: the tent keeps a souvenir of each trip.
                faces = listOf(
                    MemoryFace(Arena.DESERT, 3),
                    MemoryFace(Arena.PLAYGROUND, 2),
                    MemoryFace(Arena.BEACH, 1),
                    MemoryFace(Arena.SEA_FLOOR, 1),
                    MemoryFace(Arena.BUILDING_SITE, 1),
                    MemoryFace(Arena.MARS, 5),
                ),
                hello = "Turn two rug tiles to find a pair!",
            )
        }
    }
}

/**
 * Where [cards] cards sit in a [width] x [height] area: in [columns] x [rows], each [card] big, [gap] apart, the grid
 * starting at [origin]. Picks whichever of 3 x 4 or 4 x 3 (for 12 cards) gives the bigger cards, centered.
 */
internal class MemoryLayout(width: Float, height: Float, cards: Int, val gap: Float) {
    val columns: Int
    val rows: Int
    val card: Size
    val origin: Offset

    init {
        val tall = gridFor(width, height, cards, gap, columns = portraitColumns(cards))
        val wide = gridFor(width, height, cards, gap, columns = cards / portraitColumns(cards))
        val best = if (wide.second.width > tall.second.width) wide else tall
        columns = best.first
        rows = (cards + columns - 1) / columns
        card = best.second
        origin = Offset(
            (width - (columns * card.width + (columns - 1) * gap)) / 2,
            (height - (rows * card.height + (rows - 1) * gap)) / 2,
        )
    }

    /** Where [index] lies, row by row. */
    fun rect(index: Int): Rect = Rect(
        Offset(origin.x + (index % columns) * (card.width + gap), origin.y + (index / columns) * (card.height + gap)),
        card,
    )

    /** The whole grid. */
    val bounds: Rect get() = Rect(origin, Size(columns * card.width + (columns - 1) * gap, rows * card.height + (rows - 1) * gap))

    companion object {
        /** Width over height of a card. */
        const val ASPECT = 0.78f

        private fun portraitColumns(cards: Int): Int = if (cards % 3 == 0) 3 else 2

        private fun gridFor(width: Float, height: Float, cards: Int, gap: Float, columns: Int): Pair<Int, Size> {
            val rows = (cards + columns - 1) / columns
            val w = minOf((width - (columns - 1) * gap) / columns, (height - (rows - 1) * gap) / rows * ASPECT)
                .coerceAtLeast(1f)
            return columns to Size(w, w / ASPECT)
        }
    }
}
