package io.colorsand.ui.minigame

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.lerp
import io.colorsand.core.Arena
import io.colorsand.ui.arena.SceneGrade

/** One jar of colored sand: its [name] as it reads ("Coral sand") and its [base] color, with a [light] and [dark] grain. */
internal class SandColor(val name: String, val base: Color) {
    val light: Color = lerp(base, Color.White, 0.32f)
    val dark: Color = lerp(base, Color.Black, 0.28f)

    /** The band color for the [tone]th band in a row of this color: alternating a shade lighter and darker. */
    fun band(tone: Int): Color = if (tone % 2 == 0) base else lerp(base, Color.White, 0.12f)
}

/** What stands under a [SandArtLook]'s bottle: a little sand mound with a shell, or a woven rug. */
internal enum class SandBase { MOUND, RUG }

/**
 * The look of a sand art bottle in one arena: the [jars] of sand to pour (sea and sunset colors on the Beach,
 * ochres, terracotta, indigo and saffron in the Desert), the [glass] tint, the cord tied round the neck ([tie],
 * [tieLight]) and its charm ([charm]: a pink shell or a golden tassel), the [base] under the bottle in [baseColors],
 * and the arena's keepsake [stage] standing beside it.
 */
internal class SandArtLook(
    val jars: List<SandColor>,
    val glass: Color,
    val tie: Color,
    val tieLight: Color,
    val charm: Color,
    val base: SandBase,
    val baseColors: List<Color>,
    val stage: Int,
) {
    companion object {
        /** [arena]'s bottle, its colors through [g]. Arenas without a sand art bottle get the Beach's. */
        fun of(arena: Arena, g: SceneGrade): SandArtLook = when (arena) {
            Arena.DESERT -> SandArtLook(
                listOf(
                    SandColor("Ochre", g(0xFFD9962F)),
                    SandColor("Terracotta", g(0xFFC4573A)),
                    SandColor("Indigo", g(0xFF333F86)),
                    SandColor("Saffron", g(0xFFF5B91E)),
                    SandColor("Dune", g(0xFFF1DAA6)),
                    SandColor("Henna", g(0xFF8C3A26)),
                ),
                glass = g(0xFFF6E3BE),
                tie = g(0xFFB5332A), tieLight = g(0xFFE4574A), charm = g(0xFFF0B630),
                base = SandBase.RUG,
                baseColors = listOf(g(0xFFA8322A), g(0xFFE9B646), g(0xFF2F3C7A), g(0xFF7A2219)),
                stage = 4,
            )
            else -> SandArtLook(
                listOf(
                    SandColor("Deep sea", g(0xFF1F6DB0)),
                    SandColor("Lagoon", g(0xFF2FC2C6)),
                    SandColor("Seafoam", g(0xFFF4ECD8)),
                    SandColor("Coral", g(0xFFFF735A)),
                    SandColor("Sunset", g(0xFFFFB637)),
                    SandColor("Dusk", g(0xFF8C66C8)),
                ),
                glass = g(0xFFC9F1F2),
                tie = g(0xFF2E86C1), tieLight = g(0xFF6CC0EC), charm = g(0xFFF7A7A2),
                base = SandBase.MOUND,
                baseColors = listOf(g(0xFFF7E6BE), g(0xFFE3C68E), g(0xFFC9A66C), g(0xFFFFFFFF)),
                stage = 5,
            )
        }
    }
}

/**
 * Where the bottle sits in a [width] x [height] canvas, in pixels: centered with room above for the funnel and below
 * for its base. The body is a straight glass cylinder ([left] to [right] inside the glass, from the [floor] up to
 * the [shoulder]) under a rounded shoulder and a narrow neck whose mouth is at [top].
 */
internal class BottleLayout(val width: Float, val height: Float) {
    val size: Float = minOf(height / 1.24f, width * 1.5f)
    val cx: Float = width / 2
    val bottom: Float = height - size * 0.07f
    val top: Float = bottom - size
    val bodyWidth: Float = size * 0.37f
    val neckWidth: Float = bodyWidth * 0.42f
    val neckHeight: Float = size * 0.13f
    val shoulderHeight: Float = size * 0.13f
    val glassWall: Float = bodyWidth * 0.045f
    val corner: Float = bodyWidth * 0.2f
    val left: Float = cx - bodyWidth / 2 + glassWall
    val right: Float = cx + bodyWidth / 2 - glassWall
    val floor: Float = bottom - glassWall * 1.5f
    val shoulder: Float = top + neckHeight + shoulderHeight

    /** The y of sand [h] high (0 at the floor, 1 at the shoulder). */
    fun y(h: Float): Float = floor - h * (floor - shoulder)

    /** The x of the middle of column [c] of [columns]. */
    fun x(c: Float, columns: Int): Float = left + (c + 0.5f) * (right - left) / columns

    /** Where across the bottle (0 at the left wall, 1 at the right) a finger at [x] pours. */
    fun at(x: Float): Float = ((x - left) / (right - left)).coerceIn(0f, 1f)

    /** The funnel's spout tip over the mouth when pouring at [at]. */
    fun spout(at: Float): Offset = Offset(cx + (at - 0.5f) * neckWidth * 0.45f, top + neckHeight * 0.35f)
}
