package io.colorsand.ui.minigame

import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.BlendMode
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.rotate
import androidx.compose.ui.graphics.drawscope.scale
import androidx.compose.ui.graphics.drawscope.translate
import androidx.compose.ui.graphics.lerp
import io.colorsand.ui.arena.drawGlow
import io.colorsand.ui.arena.drawSparkle
import kotlin.math.PI
import kotlin.math.cos
import kotlin.math.floor
import kotlin.math.sin

// The moving parts of Treasure dig: the shovel, the puff of sand, the holes and their warm and cold glows, the
// sparkle of a find and the glints on the untouched sand. Sizes are in cells ([s] is a cell's size in pixels).

/** How long one dig takes, from the shovel coming in to it flicking the sand away, in milliseconds. */
internal const val DIG_MS = 640

/** The point of a dig, 0 to 1, where the shovel breaks the sand and the hole opens. */
internal const val HOLE_OPENS = 0.3f

/** One loop of the clue glows and glints, in milliseconds. */
internal const val GLOW_LOOP_MS = 6000

/** How long the last find shows off before the round ends, in milliseconds. */
internal const val FINISH_DELAY_MS = 1500L

/** The hole opening as [x] goes from 0 to 1: quickly, a touch too far, then settling. */
internal fun openCurve(x: Float): Float {
    val k = x.coerceIn(0f, 1f) - 1f
    return 1f + 2.70158f * k * k * k + 1.70158f * k * k
}

/** A dug square at [c]: flattened sand around a dark pit, [open] wide (0 to 1), with the dug-out sand piled in front. */
internal fun DrawScope.drawHole(look: DigLook, c: Offset, s: Float, open: Float) {
    val w = s * 0.91f
    drawRoundRect(lerp(look.shade, look.sand, 0.4f), Offset(c.x - w / 2, c.y - w / 2 + s * 0.06f), Size(w, w - s * 0.06f), CornerRadius(s * 0.2f))
    val rx = s * 0.36f * open
    val ry = s * 0.29f * open
    if (rx < 1f) return
    val pit = c + Offset(0f, s * 0.04f)
    drawOval(look.hole, pit - Offset(rx * 1.06f, ry * 1.06f), Size(rx * 2.12f, ry * 2.12f))
    drawOval(Brush.radialGradient(listOf(look.deep, look.hole), center = pit + Offset(0f, ry * 0.2f), radius = rx), pit - Offset(rx, ry), Size(2 * rx, 2 * ry))
    // The far wall in shadow, the dug-out sand piled on the near side.
    drawOval(Color.Black.copy(alpha = 0.18f), pit - Offset(rx * 0.85f, ry * 0.98f), Size(rx * 1.7f, ry * 0.7f))
    drawOval(look.sand, pit + Offset(-rx * 1.08f, ry * 0.55f), Size(rx * 2.16f, ry * 0.8f))
    drawOval(look.light, pit + Offset(-rx * 0.75f, ry * 0.6f), Size(rx * 1.5f, ry * 0.36f))
}

/**
 * The clue over an empty hole at [c]: a pulsing ember glow and a flame chip when [warmth] is hot, a soft amber glow
 * and a small flame when warm, a frosty tint and a snowflake when cold.
 */
internal fun DrawScope.drawClue(warmth: Warmth, c: Offset, s: Float, open: Float, t: Float, cell: Int) {
    val o = open.coerceIn(0f, 1f)
    if (o <= 0.05f) return
    val pit = c + Offset(0f, s * 0.04f)
    val wave = sin(2 * PI.toFloat() * (t * 6 + cell * 0.13f))
    when (warmth) {
        Warmth.HOT -> {
            litGlow(pit, s * 0.7f * o, Color(0xFFFF7A3D).copy(alpha = 0.75f + 0.2f * wave))
            litGlow(pit, s * 0.3f * o, Color(0xFFFFD27A).copy(alpha = 0.9f))
            // Embers drifting up out of the hole.
            for (k in 0 until 3) {
                val v = t * 5 + k / 3f + cell * 0.17f
                val phase = v - floor(v)
                val x = (k - 1) * s * 0.14f + sin(phase * 7f + k) * s * 0.04f
                drawCircle(Color(0xFFFFC14A).copy(alpha = (1f - phase) * o), s * 0.032f, pit + Offset(x, s * 0.05f - phase * s * 0.5f))
            }
        }
        Warmth.WARM -> {
            litGlow(pit, s * 0.55f * o, Color(0xFFFFB238).copy(alpha = 0.55f + 0.12f * wave))
            litGlow(pit, s * 0.22f * o, Color(0xFFFFE6A0).copy(alpha = 0.55f))
        }
        Warmth.COLD -> {
            drawGlow(pit, s * 0.42f * o, Color(0xFF8FD0FF).copy(alpha = 0.45f))
            drawSparkle(pit + Offset(-s * 0.18f, -s * 0.1f), s * 0.06f, Color.White.copy(alpha = (0.55f + 0.35f * wave) * o))
        }
    }
    clueChip(warmth, c + Offset(s * 0.3f, -s * 0.3f), s * 0.15f * o, wave)
}

/** A [drawGlow] that lightens what is under it, like light rather than paint. */
private fun DrawScope.litGlow(center: Offset, radius: Float, color: Color) {
    drawCircle(
        Brush.radialGradient(0f to color, 0.4f to color.copy(alpha = color.alpha * 0.5f), 1f to color.copy(alpha = 0f), center = center, radius = radius),
        radius,
        center,
        blendMode = BlendMode.Screen,
    )
}

/** A little white chip of radius [r] at [c] with the clue's sign on it: a flickering flame, or a snowflake. */
private fun DrawScope.clueChip(warmth: Warmth, c: Offset, r: Float, wave: Float) {
    if (r < 1f) return
    drawCircle(Color.Black.copy(alpha = 0.2f), r, c + Offset(0f, r * 0.15f))
    drawCircle(Color.White, r, c)
    translate(c.x, c.y) {
        scale(r, r, Offset.Zero) {
            when (warmth) {
                Warmth.HOT, Warmth.WARM -> {
                    val hot = warmth == Warmth.HOT
                    val k = if (hot) 1f else 0.78f
                    scale(k, k * (1f + 0.07f * wave), Offset(0f, 0.6f)) {
                        drawPath(flame, if (hot) Color(0xFFFF5A2E) else Color(0xFFFFA62E))
                        scale(0.55f, 0.55f, Offset(0f, 0.62f)) { drawPath(flame, if (hot) Color(0xFFFFC94A) else Color(0xFFFFE6A0)) }
                    }
                }
                Warmth.COLD -> {
                    val ice = Color(0xFF4FA8E8)
                    for (k in 0 until 3) {
                        val a = k * PI / 3 + PI / 2
                        val d = Offset((cos(a) * 0.62f).toFloat(), (sin(a) * 0.62f).toFloat())
                        drawLine(ice, -d, d, 0.16f, StrokeCap.Round)
                    }
                    drawCircle(ice, 0.14f, Offset.Zero)
                }
            }
        }
    }
}

private val flame = Path().apply {
    moveTo(0f, -0.78f)
    quadraticBezierTo(0.68f, -0.05f, 0.44f, 0.38f)
    quadraticBezierTo(0.24f, 0.68f, 0f, 0.66f)
    quadraticBezierTo(-0.24f, 0.68f, -0.44f, 0.38f)
    quadraticBezierTo(-0.68f, -0.05f, 0f, -0.78f)
    close()
}

/** A puff of sand thrown out of a hole at [c], [q] going from 0 (the shovel breaking in) to 1 (settled). */
internal fun DrawScope.sandPuff(look: DigLook, c: Offset, s: Float, q: Float, cell: Int) {
    val fade = 1f - q
    for ((dx, dy) in listOf(-0.22f to -0.04f, 0.22f to -0.08f, 0f to -0.2f)) {
        drawCircle(look.light.copy(alpha = 0.4f * fade), s * (0.16f + 0.3f * q), c + Offset(dx * s * (0.5f + q), dy * s * (0.5f + q)))
    }
    for (k in 0 until 10) {
        val a = -PI / 2 + (k - 4.5) * 0.3 + (noise(cell * 17 + k) - 0.5) * 0.3
        val v = s * (0.6f + 0.55f * noise(cell * 29 + k))
        val p = c + Offset((cos(a) * v * q).toFloat(), (sin(a) * v * q).toFloat() + s * 1.2f * q * q)
        val color = if (k % 3 == 0) look.shade else look.sand
        drawCircle(color.copy(alpha = 1f - q * q), s * 0.04f * (1f - 0.4f * q), p)
    }
}

/**
 * The little shovel digging the square at [c], [p] from 0 to 1: it swings in and bites at [HOLE_OPENS], then scoops
 * the sand up and flicks it away, fading out.
 */
internal fun DrawScope.drawShovel(look: DigLook, c: Offset, s: Float, p: Float) {
    val angle: Float
    val tip: Offset
    val alpha: Float
    if (p < HOLE_OPENS) {
        val k = p / HOLE_OPENS
        val e = k * k
        angle = -55f + 65f * e
        tip = c + Offset(s * 0.45f * (1f - e), -s * 0.55f + s * 0.6f * e)
        alpha = (k * 4f).coerceAtMost(1f)
    } else {
        val k = (p - HOLE_OPENS) / (1f - HOLE_OPENS)
        val e = 1f - (1f - k) * (1f - k)
        angle = 10f - 85f * e
        tip = c + Offset(s * 0.35f * e, s * 0.05f - s * 0.5f * e)
        alpha = ((1f - k) / 0.4f).coerceIn(0f, 1f)
    }
    translate(tip.x, tip.y) {
        rotate(angle, Offset.Zero) {
            scale(s, s, Offset.Zero) {
                drawLine(Color.Black.copy(alpha = 0.15f * alpha), Offset(0.03f, -0.3f), Offset(0.03f, -0.95f), 0.09f, StrokeCap.Round)
                drawLine(lerp(look.handle, Color.Black, 0.2f).copy(alpha = alpha), Offset(0f, -0.28f), Offset(0f, -0.95f), 0.085f, StrokeCap.Round)
                drawLine(look.handle.copy(alpha = alpha), Offset(-0.01f, -0.3f), Offset(-0.01f, -0.93f), 0.05f, StrokeCap.Round)
                drawRoundRect(lerp(look.handle, Color.Black, 0.2f).copy(alpha = alpha), Offset(-0.12f, -1.04f), Size(0.24f, 0.1f), CornerRadius(0.05f))
                drawPath(shovelBlade, lerp(look.blade, Color.Black, 0.25f).copy(alpha = alpha))
                drawPath(shovelBladeLit, look.blade.copy(alpha = alpha))
                drawOval(Color.White.copy(alpha = 0.45f * alpha), Offset(-0.1f, -0.26f), Size(0.05f, 0.16f))
                if (p >= HOLE_OPENS && p < 0.75f) {
                    // The scoop of sand on the blade.
                    drawOval(look.sand.copy(alpha = alpha), Offset(-0.15f, -0.36f), Size(0.3f, 0.14f))
                    drawOval(look.light.copy(alpha = alpha), Offset(-0.1f, -0.36f), Size(0.18f, 0.07f))
                }
            }
        }
    }
}

private val shovelBlade = Path().apply {
    moveTo(-0.18f, -0.33f)
    lineTo(0.18f, -0.33f)
    quadraticBezierTo(0.2f, -0.08f, 0f, 0.03f)
    quadraticBezierTo(-0.2f, -0.08f, -0.18f, -0.33f)
    close()
}
private val shovelBladeLit = Path().apply {
    moveTo(-0.15f, -0.31f)
    lineTo(0.13f, -0.31f)
    quadraticBezierTo(0.14f, -0.1f, -0.01f, -0.01f)
    quadraticBezierTo(-0.16f, -0.1f, -0.15f, -0.31f)
    close()
}

/** A ring of sparkles flying out of a find's hole at [c] as [b] goes from 0 to 1. */
internal fun DrawScope.sparkleBurst(c: Offset, s: Float, b: Float) {
    val reach = s * (0.3f + 0.65f * b)
    for (k in 0 until 8) {
        val a = k * PI / 4 + 0.4
        val p = c + Offset((cos(a) * reach).toFloat(), (sin(a) * reach * 0.85f).toFloat())
        val color = if (k % 2 == 0) Color(0xFFFFE27A) else Color.White
        drawSparkle(p, s * (if (k % 3 == 0) 0.11f else 0.075f) * (1f - b * 0.5f), color.copy(alpha = 1f - b))
    }
}

/** Now and then a glint twinkles on an untouched square, so the sand looks like it hides something. */
internal fun DrawScope.glints(layout: DigLayout, round: TreasureDig, t: Float) {
    for (k in 0 until 3) {
        val v = t * GLINTS + k / 3f
        val which = floor(v).toInt()
        val phase = v - which
        val cell = (noise(which * 7 + k * 101) * round.cells).toInt().coerceIn(0, round.cells - 1)
        if (cell in round.dug) continue
        val c = layout.center(cell) + Offset(layout.cell * (noise(which + k) - 0.5f) * 0.5f, -layout.cell * 0.12f)
        val glow = sin(phase * PI.toFloat())
        drawSparkle(c, layout.cell * 0.1f * glow, Color.White.copy(alpha = 0.9f * glow))
    }
}

/** How many glints each of the three twinkles gives per glow loop. */
private const val GLINTS = 4
