package io.colorsand.ui.arena

import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import io.colorsand.core.Arena
import kotlin.math.cos
import kotlin.math.sin

// The keepsakes' art: each one is painted in a 100 x 100 box and stands on y = GROUND, in the scenes' flat,
// two-tone style (a shade under a lit color, a soft highlight, no outlines). The paintings themselves are in
// KeepsakesPlaygroundBeach.kt, KeepsakesSeaDesert.kt and KeepsakesSiteMars.kt.

/** The ground line of a keepsake's 100-unit box. */
internal const val GROUND = 96f

/** Draws [arena]'s keepsake for [stage] (1 to [Arena.LEVELS]) at scene clock [t], with colors through [g]. */
internal fun DrawScope.drawKeepsake(arena: Arena, stage: Int, t: Float, g: SceneGrade) = when (arena) {
    Arena.PLAYGROUND -> playgroundKeepsake(stage, t, g)
    Arena.BEACH -> beachKeepsake(stage, t, g)
    Arena.SEA_FLOOR -> seaKeepsake(stage, t, g)
    Arena.DESERT -> desertKeepsake(stage, t, g)
    Arena.BUILDING_SITE -> siteKeepsake(stage, t, g)
    Arena.MARS -> marsKeepsake(stage, t, g)
}

/** An ellipse of radii [rx], [ry] around ([cx], [cy]). */
internal fun DrawScope.oval(color: Color, cx: Float, cy: Float, rx: Float, ry: Float) =
    drawOval(color, Offset(cx - rx, cy - ry), Size(2 * rx, 2 * ry))

/** A rectangle from ([l], [t]) to ([r], [b]), its corners rounded by [radius]. */
internal fun DrawScope.box(color: Color, l: Float, t: Float, r: Float, b: Float, radius: Float = 0f) =
    drawRoundRect(color, Offset(l, t), Size(r - l, b - t), CornerRadius(radius))

/** A circle of radius [r] around ([cx], [cy]). */
internal fun DrawScope.dot(color: Color, cx: Float, cy: Float, r: Float) = drawCircle(color, r, Offset(cx, cy))

/** A round-capped line [width] thick from ([x1], [y1]) to ([x2], [y2]). */
internal fun DrawScope.stick(color: Color, x1: Float, y1: Float, x2: Float, y2: Float, width: Float) =
    drawLine(color, Offset(x1, y1), Offset(x2, y2), width, StrokeCap.Round)

/** The soft contact shadow of something [width] wide standing at [cx]. */
internal fun DrawScope.groundShadow(cx: Float, width: Float, alpha: Float = 0.22f) =
    oval(Color.Black.copy(alpha = alpha), cx, GROUND - 0.5f, width / 2, width * 0.08f + 1.5f)

/** A cartoon eye: a dark dot of radius [r] with a white glint. */
internal fun DrawScope.eye(cx: Float, cy: Float, r: Float) {
    dot(Color(0xFF26222B), cx, cy, r)
    dot(Color.White, cx - r * 0.35f, cy - r * 0.4f, r * 0.38f)
}

/**
 * An arm from [shoulderX], [shoulderY] reaching [length] at [degrees] (0 is to the right, -90 straight up),
 * in a [sleeve] [width] thick, with a round [hand].
 */
internal fun DrawScope.arm(shoulderX: Float, shoulderY: Float, length: Float, degrees: Float, width: Float, sleeve: Color, hand: Color) {
    val a = degrees * TAU / 360f
    val hx = shoulderX + cos(a) * length
    val hy = shoulderY + sin(a) * length
    stick(sleeve, shoulderX, shoulderY, hx, hy, width)
    dot(hand, hx, hy, width * 0.55f)
}

/** A closed polygon through the points [xy] (x, y, x, y, ...). Build these once and keep them. */
internal fun polygon(vararg xy: Float): Path = Path().apply {
    moveTo(xy[0], xy[1])
    for (i in 2 until xy.size step 2) lineTo(xy[i], xy[i + 1])
    close()
}

/** A five-pointed star around (0, 0) with outer radius 1 and inner radius [inner]. */
internal fun starPath(inner: Float): Path = Path().apply {
    for (k in 0 until 10) {
        val r = if (k % 2 == 0) 1f else inner
        val a = -TAU / 4 + k * TAU / 10
        if (k == 0) moveTo(cos(a) * r, sin(a) * r) else lineTo(cos(a) * r, sin(a) * r)
    }
    close()
}
