// The drawing of Sort, in dp units (the game scales its canvas by the density): the ground and the patch the pile
// lies on, the things in the pile (each painted in a 100 x 100 box around (50, 50)), and the bins.

/** The ground under everything: sand with the sea along the top, or a site's gravel with a hazard-striped fence. */
internal fun DrawScope.drawSortGround(look: SortLook, layout: SortLayout, t: Float) {
    val w = layout.width
    val h = layout.height
    drawRect(Brush.verticalGradient(listOf(look.groundLight, look.ground), 0f, h), Offset.Zero, Size(w, h))
    for (k in 0 until 40) {
        drawCircle(look.groundShade.copy(alpha = 0.45f), 0.8f + 1.6f * noise(k * 3 + 7), Offset(w * noise(k * 5 + 1), h * noise(k * 7 + 2)))
    }
    when (look.theme) {
        SortTheme.SHELLS -> {
            val sea = h * 0.07f
            drawRect(Brush.verticalGradient(listOf(look.band, look.bandLight), 0f, sea * 1.4f), Offset.Zero, Size(w, sea))
            val foam = Path().apply {
                moveTo(0f, sea)
                var x = 0f
                var k = 0
                val step = w / 8
                while (x < w) {
                    val dip = sea * (0.18f + 0.1f * sin(t * 2 * PI.toFloat() * 20 + k))
                    quadraticBezierTo(x + step / 2, sea + dip, x + step, sea)
                    x += step
                    k++
                }
            }
            drawPath(foam, Color.White.copy(alpha = 0.55f), style = Stroke(2.5f))
            // Wet sand a little darker under the waves.
            drawRect(look.groundShade.copy(alpha = 0.18f), Offset(0f, sea), Size(w, sea * 0.5f))
        }
        SortTheme.MATERIALS -> {
            val fence = h * 0.045f
            drawRect(look.bandLight, Offset.Zero, Size(w, fence))
            clipPath(Path().apply { addRect(Rect(0f, 0f, w, fence)) }) {
                var x = -fence
                while (x < w + fence) {
                    drawPath(polygon(x, fence, x + fence * 0.9f, 0f, x + fence * 1.8f, 0f, x + fence * 0.9f, fence), look.band)
                    x += fence * 1.8f
                }
            }
            drawRect(Color.Black.copy(alpha = 0.15f), Offset(0f, fence), Size(w, 3f))
        }
    }
    // The patch the pile lies on.
    val p = layout.pile
    val r = layout.item * 0.55f
    drawOval(look.patch.copy(alpha = 0.45f), Offset(p.left - r, p.top - r * 0.6f), Size(p.width + 2 * r, p.height + 1.6f * r))
    drawOval(look.groundLight.copy(alpha = 0.35f), Offset(p.left - r * 0.4f, p.top - r * 0.3f), Size(p.width + 0.8f * r, p.height * 0.5f))
}

/**
 * Item [item] at [center], [size] across, turned by its tilt plus [extraTilt]. [lift] (0 to 1) raises it off the
 * ground with a bigger, softer shadow, as when it is picked up; [alpha] fades it.
 */
internal fun DrawScope.drawSortItem(look: SortLook, item: SortItem, center: Offset, size: Float, lift: Float = 0f, extraTilt: Float = 0f) {
    val s = size * (1f + 0.12f * lift)
    drawOval(
        Color.Black.copy(alpha = 0.16f - 0.06f * lift),
        Offset(center.x - s * 0.36f, center.y + s * (0.26f + 0.12f * lift)),
        Size(s * 0.72f, s * 0.16f),
    )
    val up = s * 0.1f * lift
    translate(center.x - s / 2, center.y - s / 2 - up) {
        rotate(item.tilt + extraTilt, Offset(s / 2, s / 2)) {
            scale(s / 100f, s / 100f, Offset.Zero) { drawThing(look, item.kind, item.shape) }
        }
    }
}

/** One thing, in a 100-unit box: a shell of a kind's color, or a gravel stone, a sack of sand or bricks. */
internal fun DrawScope.drawThing(look: SortLook, kind: Int, shape: Int) {
    val k = look.kinds[kind]
    when (look.theme) {
        SortTheme.SHELLS -> when (shape) {
            0 -> scallop(k)
            1 -> spiralShell(k)
            else -> clam(k)
        }
        SortTheme.MATERIALS -> when (kind) {
            0 -> stone(k, shape)
            1 -> sack(k, shape)
            else -> bricks(k, shape)
        }
    }
}

private fun DrawScope.scallop(k: SortKind) {
    val fan = Path().apply {
        moveTo(50f, 82f)
        lineTo(13f, 44f)
        cubicTo(16f, 8f, 84f, 8f, 87f, 44f)
        close()
    }
    translate(0f, 3f) { drawPath(fan, k.shade) }
    drawPath(fan, Brush.radialGradient(listOf(k.light, k.color), Offset(46f, 34f), 52f))
    for (i in 0..6) {
        val a = PI.toFloat() * (1.12f + 0.76f * i / 6f)
        val end = Offset(50f + cos(a) * 40f, 48f + sin(a) * 34f)
        drawLine(k.shade.copy(alpha = 0.55f), Offset(50f, 80f), end, 2.6f, StrokeCap.Round)
    }
    drawPath(polygon(36f, 74f, 64f, 74f, 60f, 90f, 40f, 90f), k.shade)
    drawPath(polygon(38f, 74f, 62f, 74f, 58f, 87f, 42f, 87f), k.color)
    oval(Color.White.copy(alpha = 0.45f), 36f, 30f, 8f, 4f)
}

private fun DrawScope.spiralShell(k: SortKind) {
    rotate(-28f, Offset(50f, 50f)) {
        oval(k.shade, 50f, 62f, 24f, 30f)
        oval(k.color, 48f, 60f, 22f, 28f)
        dot(k.shade, 50f, 30f, 14f)
        dot(k.color, 49f, 29f, 12.5f)
        dot(k.shade, 50f, 17f, 8.5f)
        dot(k.light, 49.5f, 16.5f, 7f)
        dot(k.shade, 50f, 9f, 4.2f)
        drawArc(k.shade, 200f, 160f, false, Offset(30f, 38f), Size(38f, 16f), style = Stroke(2.4f))
        drawArc(k.shade, 200f, 160f, false, Offset(38f, 22f), Size(24f, 10f), style = Stroke(2f))
        // The opening, pink-lit inside.
        oval(k.light, 44f, 68f, 11f, 19f)
        oval(lerp(k.shade, Color.Black, 0.1f), 45f, 70f, 6f, 13f)
        oval(Color.White.copy(alpha = 0.4f), 60f, 52f, 4f, 9f)
    }
}

private fun DrawScope.clam(k: SortKind) {
    oval(k.shade, 50f, 56f, 38f, 30f)
    oval(k.color, 50f, 53f, 37f, 28f)
    for (i in 1..4) {
        val rx = 37f * (1f - i * 0.2f)
        val ry = 28f * (1f - i * 0.2f)
        drawArc(k.shade.copy(alpha = 0.5f), 190f, 160f, false, Offset(50f - rx, 70f - 2 * ry + (28f - ry) * 0.4f), Size(2 * rx, 2 * ry), style = Stroke(2.4f))
    }
    oval(k.shade, 50f, 82f, 12f, 6f)
    oval(k.light, 50f, 80f, 10f, 4.5f)
    oval(Color.White.copy(alpha = 0.45f), 36f, 38f, 9f, 4f)
}

private val stones = listOf(
    floatArrayOf(20f, 50f, 28f, 28f, 52f, 20f, 76f, 30f, 84f, 54f, 72f, 76f, 46f, 82f, 24f, 70f),
    floatArrayOf(12f, 58f, 24f, 40f, 50f, 34f, 80f, 38f, 90f, 56f, 76f, 70f, 46f, 74f, 20f, 70f),
    floatArrayOf(22f, 70f, 34f, 34f, 54f, 16f, 70f, 34f, 82f, 64f, 66f, 80f, 42f, 82f, 28f, 80f),
)

/** A smooth closed blob through the points [xy] (x, y, ...), each corner rounded off at its edges' middles. */
private fun blob(xy: FloatArray): Path = Path().apply {
    val n = xy.size / 2
    fun mid(i: Int): Offset {
        val a = i % n
        val b = (i + 1) % n
        return Offset((xy[2 * a] + xy[2 * b]) / 2, (xy[2 * a + 1] + xy[2 * b + 1]) / 2)
    }
    val start = mid(n - 1)
    moveTo(start.x, start.y)
    for (i in 0 until n) {
        val m = mid(i)
        quadraticBezierTo(xy[2 * i], xy[2 * i + 1], m.x, m.y)
    }
    close()
}

private fun DrawScope.stone(k: SortKind, shape: Int) {
    val path = blob(stones[shape])
    translate(0f, 3.5f) { drawPath(path, k.shade) }
    drawPath(path, Brush.radialGradient(listOf(k.light, k.color), Offset(42f, 40f), 46f))
    clipPath(path) {
        for (i in 0 until 9) dot(k.shade.copy(alpha = 0.6f), 24f + 56f * noise(shape * 19 + i), 30f + 46f * noise(shape * 23 + i * 3), 1.4f + 1.4f * noise(i + shape))
        drawPath(path, Color.Black.copy(alpha = 0.12f), style = Stroke(6f))
    }
    oval(Color.White.copy(alpha = 0.5f), 40f, 36f, 9f, 4f)
}

private fun DrawScope.sack(k: SortKind, shape: Int) {
    val lean = if (shape == 1) 12f else 0f
    val squash = if (shape == 2) 0.84f else 1f
    scale(squash, squash, Offset(50f, 92f)) {
        rotate(lean, Offset(50f, 90f)) {
            val bag = Path().apply {
                moveTo(40f, 30f)
                cubicTo(16f, 40f, 14f, 84f, 26f, 90f)
                lineTo(74f, 90f)
                cubicTo(86f, 84f, 84f, 40f, 60f, 30f)
                close()
            }
            translate(0f, 3f) { drawPath(bag, k.shade) }
            drawPath(bag, Brush.horizontalGradient(listOf(k.light, k.color, k.shade), 18f, 84f))
            // Burlap weave.
            clipPath(bag) {
                for (y in 38..88 step 6) drawLine(k.shade.copy(alpha = 0.25f), Offset(14f, y.toFloat()), Offset(86f, y.toFloat()), 1.2f)
                for (x in 20..80 step 6) drawLine(k.shade.copy(alpha = 0.18f), Offset(x.toFloat(), 30f), Offset(x.toFloat(), 92f), 1.2f)
            }
            // The tied neck and the ears above it.
            drawPath(polygon(38f, 30f, 62f, 30f, 68f, 14f, 58f, 18f, 50f, 12f, 42f, 18f, 32f, 14f), k.color)
            drawPath(polygon(42f, 18f, 50f, 12f, 58f, 18f, 54f, 26f, 46f, 26f), k.light)
            stick(Color(0xFF8E5A2E), 38f, 30f, 62f, 30f, 4f)
            // A stenciled band on the front.
            box(Color.White.copy(alpha = 0.55f), 30f, 56f, 70f, 70f, 3f)
            for (i in 0 until 4) box(k.shade.copy(alpha = 0.8f), 34f + i * 9f, 59f, 39f + i * 9f, 67f, 1f)
        }
    }
}

private fun DrawScope.brick(k: SortKind, l: Float, t: Float, w: Float, h: Float) {
    val d = h * 0.45f
    // Top face, front face and side, with the holes on top.
    drawPath(polygon(l, t + d, l + d, t, l + w + d, t, l + w, t + d), k.light)
    box(k.color, l, t + d, l + w, t + d + h)
    drawPath(polygon(l + w, t + d, l + w + d, t, l + w + d, t + h, l + w, t + d + h), k.shade)
    val holes = if (w > 40f) 3 else 1
    for (i in 0 until holes) {
        val cx = l + d * 0.5f + w * (i + 0.5f) / holes
        oval(k.shade, cx, t + d * 0.5f, w * 0.07f + 1f, d * 0.22f)
    }
    drawLine(Color.White.copy(alpha = 0.35f), Offset(l + 3f, t + d + 3f), Offset(l + w - 3f, t + d + 3f), 2f)
}

private fun DrawScope.bricks(k: SortKind, shape: Int) {
    translate(0f, 3f) {
        when (shape) {
            0 -> box(k.shade, 14f, 48f, 78f, 78f, 2f)
            1 -> box(k.shade, 18f, 30f, 76f, 82f, 2f)
            else -> box(k.shade, 26f, 48f, 66f, 80f, 2f)
        }
    }
    when (shape) {
        0 -> brick(k, 12f, 38f, 64f, 34f)
        1 -> {
            brick(k, 16f, 52f, 56f, 28f)
            brick(k, 22f, 24f, 56f, 28f)
        }
        else -> brick(k, 24f, 38f, 38f, 34f)
    }
}

/**
 * Bin [i] in [r]: a woven basket on the Beach, a metal skip on the Building Site, with its kind's band of color and
 * a sample of what goes in it on the front, and [count] things already peeking out of it. [hop] (0 to 1) bounces it;
 * [wobble] (0 to 1) gives it a little shake after a wrong drop. [glow] lights it while it can take the item held.
 */
internal fun DrawScope.drawBin(
    look: SortLook,
    i: Int,
    r: Rect,
    contents: List<SortItem>,
    hop: Float,
    wobble: Float,
    glow: Float,
) {
    val k = look.kinds[i]
    val lift = if (hop > 0f && hop < 1f) sin(hop * PI.toFloat()) * r.height * 0.14f else 0f
    val shake = if (wobble > 0f && wobble < 1f) sin(wobble * 4 * PI.toFloat()) * 5f * (1f - wobble) else 0f
    drawOval(Color.Black.copy(alpha = 0.18f - 0.08f * (lift / r.height / 0.14f)), Offset(r.left + r.width * 0.06f, r.bottom - r.height * 0.07f), Size(r.width * 0.88f, r.height * 0.12f))
    translate(0f, -lift) {
        rotate(shake, Offset(r.center.x, r.bottom)) {
            if (glow > 0f) {
                drawRoundRect(Color(0xFFFFF2B0).copy(alpha = 0.55f * glow), Offset(r.left - 6f, r.top - 6f), Size(r.width + 12f, r.height + 12f), CornerRadius(r.width * 0.2f))
            }
            val top = r.top + r.height * 0.16f
            val inset = r.width * 0.09f
            val body = polygon(r.left, top, r.right, top, r.right - inset, r.bottom - r.height * 0.04f, r.left + inset, r.bottom - r.height * 0.04f)
            // The back rim, then whatever is inside peeking out, then the front.
            drawOval(look.binDark, Offset(r.left, top - r.height * 0.07f), Size(r.width, r.height * 0.14f))
            val size = r.width * 0.36f
            contents.takeLast(6).forEachIndexed { n, item ->
                val x = r.left + r.width * (0.26f + 0.24f * (n % 3)) + (if (n >= 3) r.width * 0.1f else 0f)
                val y = top - size * (if (n >= 3) 0.42f else 0.26f)
                drawSortItem(look, item, Offset(x, y), size)
            }
            when (look.theme) {
                SortTheme.SHELLS -> {
                    drawPath(body, Brush.verticalGradient(listOf(look.binLight, look.binBody), top, r.bottom))
                    clipPath(body) {
                        // The weave: rows of reeds over stakes.
                        val row = r.height * 0.1f
                        var y = top + row * 0.5f
                        var n = 0
                        while (y < r.bottom) {
                            var x = r.left + if (n % 2 == 0) 0f else row
                            while (x < r.right) {
                                drawRoundRect(look.binDark.copy(alpha = 0.28f), Offset(x, y), Size(row * 1.2f, row * 0.7f), CornerRadius(row * 0.35f))
                                x += row * 2f
                            }
                            y += row
                            n++
                        }
                        drawRect(k.color, Offset(r.left, top + r.height * 0.18f), Size(r.width, r.height * 0.12f))
                        drawRect(Color.White.copy(alpha = 0.3f), Offset(r.left, top + r.height * 0.18f), Size(r.width, r.height * 0.03f))
                    }
                    drawRoundRect(look.binDark, Offset(r.left - 2f, top - r.height * 0.035f), Size(r.width + 4f, r.height * 0.08f), CornerRadius(r.height * 0.04f))
                    drawRoundRect(look.binLight, Offset(r.left, top - r.height * 0.035f), Size(r.width, r.height * 0.04f), CornerRadius(r.height * 0.02f))
                }
                SortTheme.MATERIALS -> {
                    drawPath(body, Brush.horizontalGradient(listOf(look.binLight, look.binBody, look.binDark), r.left, r.right))
                    clipPath(body) {
                        for (n in 1..4) {
                            val x = r.left + r.width * n / 5f
                            drawLine(look.binDark.copy(alpha = 0.4f), Offset(x, top), Offset(x, r.bottom), r.width * 0.025f)
                        }
                        drawRect(k.color, Offset(r.left, top + r.height * 0.16f), Size(r.width, r.height * 0.1f))
                    }
                    drawRoundRect(look.binDark, Offset(r.left - 3f, top - r.height * 0.04f), Size(r.width + 6f, r.height * 0.08f), CornerRadius(3f))
                    // Lifting lugs on the sides.
                    for (side in listOf(r.left + inset * 0.3f, r.right - inset * 0.3f)) dot(look.binDark, side, top + r.height * 0.42f, r.width * 0.035f)
                }
            }
            // A round plate on the front with a sample of what goes in.
            val plate = Offset(r.center.x, top + r.height * 0.3f)
            val pr = r.height * 0.17f
            drawCircle(Color.Black.copy(alpha = 0.15f), pr, plate + Offset(0f, 2f))
            drawCircle(Color.White.copy(alpha = 0.92f), pr, plate)
            drawCircle(k.color, pr, plate, style = Stroke(2.5f))
            val sample = pr * 1.7f
            translate(plate.x - sample / 2, plate.y - sample / 2) {
                scale(sample / 100f, sample / 100f, Offset.Zero) { drawThing(look, i, 0) }
            }
        }
    }
}

/** A ring around something the keyboard is on, [r] in dp. */
internal fun DrawScope.drawSortFocus(r: Rect, color: Color, round: Float) {
    drawRoundRect(Color.White, r.topLeft - Offset(5f, 5f), Size(r.width + 10f, r.height + 10f), CornerRadius(round + 5f), style = Stroke(6f))
    drawRoundRect(color, r.topLeft - Offset(5f, 5f), Size(r.width + 10f, r.height + 10f), CornerRadius(round + 5f), style = Stroke(3f))
}
