/**
 * Bubble pop, the clownfish's game: glossy, iridescent bubbles of all sizes rise slowly from the sea floor, swaying
 * as they go, and some carry a tiny treasure (a pearl, a shell, a starfish). Tap one and it bursts in a ring of
 * droplets while the clownfish swims over to it; a treasure drifts down into the open shell on the sand. Popping
 * [BubblePop.GOAL] bubbles or collecting [BubblePop.TREASURE_GOAL] treasures calls [onFinished]. Nothing is lost
 * when a bubble floats away. Enter, Space or a screen reader's "Pop a bubble" pops the one nearest the floor.
 * [seed] makes the round. Only the Sea Floor's clownfish plays it, so [arena] gives no other look.
 */
@Suppress("UNUSED_PARAMETER")
@Composable
fun BubblePopGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val round = remember(seed) { BubblePop(seed) }
    var frame by remember(seed) { mutableStateOf(0) }
    var popped by remember(seed) { mutableStateOf(0) }
    var found by remember(seed) { mutableStateOf(0) }
    var landed by remember(seed) { mutableStateOf(0) }
    var done by remember(seed) { mutableStateOf(false) }
    var status by remember(seed) { mutableStateOf(PopStatus.START) }
    var lastTreasure by remember(seed) { mutableStateOf<BubbleTreasure?>(null) }
    // The clownfish, in field units (y up from the floor), and which way it faces.
    val fish = remember(seed) { Animatable(Offset(0.3f, 0.55f), Offset.VectorConverter) }
    val facing = remember(seed) { floatArrayOf(1f, 0.3f) }
    var lastTap by remember(seed) { mutableStateOf(0f) }
    val focus = remember { FocusRequester() }
    // Keys go to the game at once, so Enter and Space pop without tabbing to it first.
    LaunchedEffect(focus) { runCatching { focus.requestFocus() } }
    val scope = rememberCoroutineScope()

    fun swimTo(x: Float, y: Float) {
        val from = fish.value
        if (abs(x - from.x) > 0.01f) facing[0] = if (x > from.x) 1f else -1f
        // The nose stops at the spot, not the middle of the fish.
        val target = Offset(
            (x - facing[0] * FISH_LENGTH * 0.4f).coerceIn(0.08f, 0.92f),
            y.coerceIn(0.12f, round.height - 0.06f),
        )
        scope.launch { fish.animateTo(target, spring(dampingRatio = 0.85f, stiffness = Spring.StiffnessVeryLow)) }
    }

    fun onPop(pop: PoppedBubble) {
        lastTap = round.time
        swimTo(pop.x, pop.y)
        popped = round.popped
        feedback.play(Sounds.pick)
        feedback.tick()
        val treasure = pop.bubble.treasure
        if (treasure != null) {
            found = round.treasures.size
            lastTreasure = treasure
            feedback.play(Sounds.chime(found + 1))
        }
        status = when {
            round.isDone && round.treasures.size >= round.treasureGoal -> PopStatus.ALL_TREASURE
            round.isDone -> PopStatus.ALL_POPPED
            treasure != null -> PopStatus.TREASURE
            popped >= round.goal - 5 -> PopStatus.ALMOST
            popped >= 8 -> PopStatus.LOVELY
            else -> PopStatus.POP
        }
        if (round.isDone && !done) {
            done = true
            feedback.confirm()
        }
    }

    fun popLowest() {
        round.popLowest()?.let(::onPop)
    }

    LaunchedEffect(round) {
        var last = -1L
        while (true) {
            withFrameNanos { now ->
                val dt = if (last < 0) 0f else ((now - last) / 1_000_000_000f).coerceAtMost(0.1f)
                last = now
                round.step(dt)
                // A treasure landing in the shell.
                val settled = round.pops.count { it.bubble.treasure != null && round.time - it.at >= DROP_S }
                if (settled > landed) {
                    landed = settled
                    feedback.play(Sounds.land)
                }
                frame++
            }
        }
    }
    // Now and then the clownfish wanders off on its own while nobody taps.
    LaunchedEffect(round) {
        val wander = Random(seed)
        while (true) {
            delay(3200)
            if (round.time - lastTap > 3f && !done) {
                swimTo(0.15f + 0.7f * wander.nextFloat(), 0.3f + (round.height - 0.45f) * wander.nextFloat())
            }
        }
    }
    LaunchedEffect(done) {
        if (done) {
            delay((DROP_S * 1000).toLong() + FINISH_MS)
            onFinished()
        }
    }

    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        Canvas(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .clip(RoundedCornerShape(26.dp))
                .border(1.5.dp, Color.White.copy(alpha = 0.55f), RoundedCornerShape(26.dp))
                .onSizeChanged { round.height = BubbleField(it.width.toFloat(), it.height.toFloat()).water }
                .semantics {
                    contentDescription = "Bubbles rising from the sea floor, with the clownfish"
                    stateDescription = "$popped of ${round.goal} popped, $found of ${round.treasureGoal} treasures"
                    onClick(label = POP_ONE) { popLowest(); true }
                    customActions = listOf(CustomAccessibilityAction(POP_ONE) { popLowest(); true })
                }
                .onKeyEvent { event ->
                    val press = event.key == Key.Enter || event.key == Key.Spacebar || event.key == Key.NumPadEnter
                    if (press && event.type == KeyEventType.KeyDown) popLowest()
                    press
                }
                .focusRequester(focus)
                .focusable()
                .pointerInput(round) {
                    detectTapGestures { p ->
                        val field = BubbleField(size.width.toFloat(), size.height.toFloat())
                        val at = field.field(p)
                        val pop = round.popAt(at.x, at.y)
                        if (pop != null) {
                            onPop(pop)
                        } else if (!done) {
                            lastTap = round.time
                            swimTo(at.x, at.y)
                        }
                    }
                },
        ) {
            if (frame < 0) return@Canvas
            val field = BubbleField(size.width, size.height)
            val t = round.time
            drawBubbleWater(field, grade, t)
            drawBubbleFloor(field, grade, t)
            val settled = round.pops.filter { it.bubble.treasure != null && t - it.at >= DROP_S }
            val shine = if (done) ((t - round.pops.last().at) / DROP_S).coerceIn(0f, 1f) else 0f
            drawShellBack(field, grade, shine * (0.75f + 0.25f * sin(t * 4f)))
            settled.forEachIndexed { i, pop ->
                drawTreasure(pop.bubble.treasure!!, field.slot(i), field.slotSize, grade)
            }
            drawShellFront(field, grade)
            for (b in round.bubbles) {
                val r = round.radius(b) * field.width
                val age = t - b.born
                drawBubble(
                    field.at(round.x(b), round.y(b)),
                    r,
                    spin = (age * 0.08f + b.phase) % 1f,
                    squish = 0.035f * sin((age * b.wobbleRate * 2f + b.phase) * 2f * PI.toFloat()),
                    treasure = b.treasure,
                    g = grade,
                )
            }
            // The clownfish, its tail beating faster while it swims.
            val f = fish.value
            val bob = sin(t * 1.6f) * 0.008f
            val speed = abs(fish.velocity.x) + abs(fish.velocity.y)
            facing[1] += (0.25f + 1.6f * speed.coerceAtMost(1f)) * 0.5f
            drawSwimmingClownfish(field.at(f.x, f.y + bob), FISH_LENGTH * field.width, facing[0], facing[1], grade)
            // Treasures drifting down into the shell, and the bursts.
            var slot = 0
            for (pop in round.pops) {
                val age = t - pop.at
                val from = field.at(pop.x, pop.y)
                val treasure = pop.bubble.treasure
                if (treasure != null) {
                    val i = slot++
                    if (age < DROP_S) {
                        val p = (age / DROP_S).coerceIn(0f, 1f)
                        val ease = p * p * (3f - 2f * p)
                        val to = field.slot(i)
                        val sway = sin(p * PI.toFloat() * 3f) * field.width * 0.035f * (1f - p)
                        val at = Offset(from.x + (to.x - from.x) * ease + sway, from.y + (to.y - from.y) * ease)
                        val s = field.slotSize * (1.25f - 0.25f * p)
                        drawTreasure(treasure, at, s, grade)
                        if (sin(age * 18f) > 0.3f) drawSparkle(at + Offset(s, -s), s * 0.45f, Color.White, 0.8f)
                    }
                }
                if (age < BURST_S) drawPopBurst(from, pop.bubble.r * field.width, age / BURST_S, pop.bubble.id)
            }
        }
        Spacer(Modifier.height(10.dp))
        TreasureSlots(round, found, grade)
        Spacer(Modifier.height(10.dp))
        Row(
            Modifier
                .widthIn(max = 460.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Text(
                status.text(lastTreasure?.title),
                color = palette.text,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center,
                maxLines = 1,
                modifier = Modifier.weight(1f, fill = false).semantics { liveRegion = LiveRegionMode.Polite },
            )
            Text("$popped/${round.goal}", color = palette.accent, fontSize = 16.sp, fontWeight = FontWeight.Black, maxLines = 1)
        }
    }
}

/** A slot for each treasure to collect: empty until one lands in it. */
@Composable
private fun TreasureSlots(round: BubblePop, found: Int, grade: SceneGrade) {
    val palette = LocalPalette.current
    Row(
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        modifier = Modifier.semantics { contentDescription = "$found of ${round.treasureGoal} treasures" },
    ) {
        for (i in 0 until round.treasureGoal) {
            val treasure = round.treasures.getOrNull(i)
            Box(Modifier.size(38.dp).frosted(palette, CircleShape, elevation = 4.dp), contentAlignment = Alignment.Center) {
                Canvas(Modifier.fillMaxSize().padding(7.dp)) {
                    val c = Offset(size.width / 2, size.height / 2)
                    if (treasure != null) {
                        drawTreasure(treasure, c, size.minDimension * 0.46f, grade)
                    } else {
                        drawCircle(Color.Black.copy(alpha = 0.12f), size.minDimension * 0.3f, c)
                    }
                }
            }
        }
    }
}

/** What the line under the water says after the last pop. */
private enum class PopStatus {
    START, POP, LOVELY, ALMOST, TREASURE, ALL_POPPED, ALL_TREASURE;

    fun text(treasure: String?): String = when (this) {
        START -> "Tap the bubbles to pop them!"
        POP -> "Pop! Keep going."
        LOVELY -> "Lovely popping!"
        ALMOST -> "Almost there!"
        TREASURE -> "A $treasure! Down into the clam it goes."
        ALL_POPPED -> "All popped! What a bubbly sea!"
        ALL_TREASURE -> "Five treasures in the clam!"
    }
}

/** What Enter, Space and screen readers do. */
private const val POP_ONE = "Pop a bubble"

/** The clownfish's length, in field widths. */
private const val FISH_LENGTH = 0.2f

/** Seconds a pop's ring and droplets last. */
private const val BURST_S = 0.5f

/** Seconds a treasure takes to drift down into the shell. */
private const val DROP_S = 1.5f

/** How long to admire the full shell before the result card. */
private const val FINISH_MS = 900L
