/**
 * Hide and seek: a richly drawn corner of [arena] filling the play area (the Playground's tree, slide, bushes,
 * bench, sandbox and toy box; the Sea Floor's kelp, rocks, coral and anemone), with the arena's hide-and-seek
 * keepsake and four of its friends tucked in behind or among the props, partly showing. Tap one to find it: it pops
 * out with a sparkle and flies to its place in the tray at the bottom. A tap on anything else just rustles what was
 * tapped; after [HideAndSeek.HINT] such taps in a row, the nearest thing still hiding wiggles. Finding all five calls
 * [onFinished]. [seed] picks the hiding spots.
 */
@Composable
fun HideAndSeekGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { SeekLook.of(arena, grade) }
    val scene = look.scene
    var round by remember(seed) { mutableStateOf(HideAndSeek.start(seed, scene.spots.size)) }
    var status by remember(seed) { mutableStateOf(SeekStatus.START) }
    var lastName by remember(seed) { mutableStateOf("") }
    var hinted by remember(seed) { mutableStateOf<Int?>(null) }
    val reveals = remember(seed) { List(round.count) { Animatable(0f) } }
    val lands = remember(seed) { List(round.count) { Animatable(0f) } }
    val rustles = remember(seed) { List(scene.props.size) { Animatable(0f) } }
    val hint = remember(seed) { Animatable(0f) }
    val clock = rememberSceneClock()
    val scope = rememberCoroutineScope()

    fun find(item: Int) {
        val next = round.look(round.hiding[item])
        if (next === round) return
        round = next
        hinted = null
        lastName = look.name(item)
        status = if (next.isDone) SeekStatus.ALL_FOUND else SeekStatus.FOUND
        feedback.play(Sounds.chime(next.found.size * 2))
        feedback.confirm()
        scope.launch {
            reveals[item].animateTo(1f, tween(REVEAL_MS, easing = LinearEasing))
            feedback.tick()
            lands[item].animateTo(1f, spring(dampingRatio = 0.42f, stiffness = Spring.StiffnessMedium))
        }
    }

    fun miss(prop: Int?, at: Offset) {
        val next = round.look(null)
        if (next === round) return
        round = next
        if (prop != null) {
            lastName = scene.props[prop].name
            feedback.play(Sounds.pour)
            scope.launch {
                rustles[prop].snapTo(0f)
                rustles[prop].animateTo(1f, tween(RUSTLE_MS, easing = LinearEasing))
            }
        } else {
            feedback.play(Sounds.pick)
        }
        feedback.tick()
        if (next.needsHint) {
            hinted = next.nearestHidden { spot -> (scene.spots[spot].center - at).getDistance() }
            status = SeekStatus.HINT
        } else {
            status = if (prop != null) SeekStatus.RUSTLE else SeekStatus.NOTHING
        }
    }

    fun tap(p: Offset, frame: SeekFrame, density: Density) {
        if (round.isDone) return
        val at = frame.toStage(p)
        val reach = with(density) { MIN_REACH.toPx() } / frame.unit
        val item = round.stillHiding()
            .map { it to look.place(it, scene.spots[round.hiding[it]], sizeOf(it)) }
            .map { (i, r) -> Triple(i, r, (r.center - at).getDistance()) }
            .filter { (_, r, d) -> d <= maxOf(r.maxDimension * 0.6f, reach) }
            .minByOrNull { it.third }?.first
        if (item != null) {
            find(item)
        } else {
            // The front-most prop under the tap rustles.
            miss(scene.props.indices.lastOrNull { scene.props[it].hit.contains(at) }, at)
        }
    }

    fun lookNext() {
        round.stillHiding().firstOrNull()?.let(::find)
    }

    LaunchedEffect(hinted) {
        if (hinted == null) {
            hint.snapTo(0f)
            return@LaunchedEffect
        }
        while (true) {
            hint.snapTo(0f)
            hint.animateTo(1f, tween(HINT_MS, easing = LinearEasing))
            delay(HINT_PAUSE_MS)
        }
    }
    LaunchedEffect(round.isDone) {
        if (round.isDone) {
            // Let the last find land in the tray first.
            delay(REVEAL_MS + SEEK_FINISH_MS)
            onFinished()
        }
    }

    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        Box(Modifier.weight(1f).fillMaxWidth()) {
            Canvas(
                Modifier
                    .fillMaxSize()
                    .clip(RoundedCornerShape(26.dp))
                    .border(1.5.dp, Color.White.copy(alpha = 0.55f), RoundedCornerShape(26.dp))
                    // Screen readers and keyboards find the next thing still hiding: the keepsake, then its friends.
                    .semantics {
                        contentDescription = "${look.sceneName()}: ${look.name(0)} and 4 friends are hiding, " +
                            "${round.found.size} of ${round.count} found"
                        onClick(label = LOOK_NEXT) { lookNext(); true }
                        customActions = listOf(CustomAccessibilityAction(LOOK_NEXT) { lookNext(); true })
                    }
                    .onKeyEvent { event ->
                        val press = event.type == KeyEventType.KeyUp && (event.key == Key.Enter || event.key == Key.Spacebar)
                        if (press) lookNext()
                        press
                    }
                    .focusable()
                    .pointerInput(seed, look) {
                        detectTapGestures { p ->
                            tap(p, SeekFrame(size.width.toFloat(), size.height.toFloat(), TRAY_RESERVE.toPx()), this)
                        }
                    },
            ) {
                val frame = SeekFrame(size.width, size.height, TRAY_RESERVE.toPx())
                drawSeekScene(look, grade, frame, round, reveals, rustles, hinted, hint.value, clock)
            }
            SeekTray(
                look, grade, round, reveals, lands,
                Modifier.align(Alignment.BottomCenter).padding(bottom = TRAY_GAP),
            )
            // The finds pop out and fly over everything, the tray included.
            Canvas(Modifier.fillMaxSize()) {
                val frame = SeekFrame(size.width, size.height, TRAY_RESERVE.toPx())
                drawFlights(look, grade, frame, round, reveals, clock.value)
            }
        }
        Spacer(Modifier.height(10.dp))
        Text(
            status.text(look.name(0), lastName),
            color = palette.text,
            fontSize = 16.sp,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center,
            maxLines = 1,
            modifier = Modifier
                .widthIn(max = 420.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp)
                .semantics { liveRegion = LiveRegionMode.Polite },
        )
    }
}

/** What the line under the scene says after the last tap. */
private enum class SeekStatus {
    START, FOUND, RUSTLE, NOTHING, HINT, ALL_FOUND;

    fun text(keepsake: String, name: String): String = when (this) {
        START -> "Find ${keepsake} and 4 friends!"
        FOUND -> "You found $name!"
        RUSTLE -> "Just $name. Look again!"
        NOTHING -> "Nothing there. Keep looking!"
        HINT -> "Psst… something is wiggling!"
        ALL_FOUND -> "Found everyone! Peekaboo!"
    }
}

private const val LOOK_NEXT = "Look for the next one"

private fun SeekLook.sceneName(): String = when (arena) {
    Arena.SEA_FLOOR -> "A kelp forest"
    else -> "A cozy playground corner"
}

/** How big thing [i] is next to its spot: the keepsake a little bigger than its friends. */
private fun sizeOf(i: Int): Float = if (i == 0) 1.1f else 0.92f

/** The scene at this frame: scenery, then every prop back to front with what still hides in it. */
private fun DrawScope.drawSeekScene(
    look: SeekLook,
    grade: SceneGrade,
    frame: SeekFrame,
    round: HideAndSeek,
    reveals: List<Animatable<Float, *>>,
    rustles: List<Animatable<Float, *>>,
    hinted: Int?,
    hint: Float,
    clock: State<Float>,
) {
    val t = clock.value
    val scene = look.scene
    translate(frame.origin.x, frame.origin.y) {
        scale(frame.unit, frame.unit, Offset.Zero) {
            with(scene) { drawScenery(frame.view, t) }
            for (prop in scene.props.indices) {
                withRustle(scene.props[prop], rustles[prop].value) {
                    with(scene) { drawBack(prop, t) }
                    for (item in round.hiding.indices) {
                        val spot = scene.spots[round.hiding[item]]
                        if (spot.prop != prop) continue
                        // A find leaves its spot as soon as it pops out (see drawFlights).
                        if (item in round.found && reveals[item].value > 0f) continue
                        val wiggle = if (item == hinted) wiggle(hint) else 0f
                        if (item == hinted && hint > 0f) {
                            // A soft glow behind it while it wiggles.
                            val placed = look.place(item, spot, sizeOf(item))
                            drawGlow(placed.center, placed.maxDimension * 0.85f, Color(0xFFFFF2B0).copy(alpha = 0.5f * sin(hint * PI.toFloat())))
                        }
                        drawHider(look, grade, item, spot, wiggle, t)
                    }
                    with(scene) { drawFront(prop, t) }
                }
            }
        }
    }
}

/** Draws [content] moved the way [prop] rustles, [p] of the way through a rustle (0 or 1: still). */
private inline fun DrawScope.withRustle(prop: SeekProp, p: Float, content: DrawScope.() -> Unit) {
    if (p <= 0f || p >= 1f) {
        content()
        return
    }
    val fade = (1f - p) * (1f - p)
    val (cycles, degrees) = when (prop.rustle) {
        Rustle.SHAKE -> 4f to 3.2f
        Rustle.SWAY -> 1.5f to 7f
        Rustle.WOBBLE -> 3f to 2f
    }
    val angle = sin(p * cycles * 2 * PI.toFloat()) * degrees * fade
    val shift = if (prop.rustle == Rustle.SHAKE) sin(p * cycles * 2 * PI.toFloat() + 1f) * 0.5f * fade else 0f
    translate(shift, 0f) { rotate(angle, prop.pivot) { content() } }
}

/** The hint's soft wiggle at [h] of the way through one: a few rocks side to side, fading in and out. */
private fun wiggle(h: Float): Float = sin(h * 3f * 2 * PI.toFloat()) * 11f * sin(h * PI.toFloat())

/** Thing [item] hiding at [spot], leaning [extra] degrees more than the spot has it. Drawn in stage units. */
private fun DrawScope.drawHider(look: SeekLook, grade: SceneGrade, item: Int, spot: SeekSpot, extra: Float, t: Float) {
    rotate(spot.tilt + extra, Offset(spot.x, spot.y)) {
        drawFitted(look, grade, item, look.place(item, spot, sizeOf(item)), t, stand = true)
    }
}

/**
 * Thing [item]'s painting fitted into [target], keeping its shape: standing on the target's bottom if it [stand]s,
 * else in its middle. Shadows and loose bits outside its bounds are left out.
 */
private fun DrawScope.drawFitted(look: SeekLook, grade: SceneGrade, item: Int, target: Rect, t: Float, stand: Boolean) {
    val b = look.bounds(item)
    val k = minOf(target.width / b.width, target.height / b.height)
    val left = target.center.x - b.width * k / 2
    val top = if (stand) target.bottom - b.height * k else target.center.y - b.height * k / 2
    translate(left - b.left * k, top - b.top * k) {
        scale(k, k, Offset.Zero) {
            clipRect(b.left - 5f, b.top - 8f, b.right + 5f, b.bottom + 1.5f) { drawKeepsake(look.arena, look.hiders[item], t, grade) }
        }
    }
}

/** A square [side] wide around [c]. */
private fun square(c: Offset, side: Float): Rect = Rect(c, side / 2)

/** Where tray slot [i]'s middle is in a play area [width] x [height] pixels, by the tray's layout in [SeekTray]. */
private fun DrawScope.slotCenter(i: Int, count: Int): Offset = Offset(
    size.width / 2 + (i - (count - 1) / 2f) * (SLOT + SLOT_GAP).toPx(),
    size.height - (TRAY_GAP + TRAY_PAD + SLOT / 2).toPx(),
)

/** Every find on its way: popping out of its spot with a sparkle, then flying in an arc to its slot in the tray. */
private fun DrawScope.drawFlights(
    look: SeekLook,
    grade: SceneGrade,
    frame: SeekFrame,
    round: HideAndSeek,
    reveals: List<Animatable<Float, *>>,
    t: Float,
) {
    for (item in round.found) {
        val r = reveals[item].value
        if (r <= 0f || r >= 1f) continue
        val spot = look.scene.spots[round.hiding[item]]
        val placed = look.place(item, spot, sizeOf(item))
        val start = frame.toPx(placed.center)
        val startBox = placed.maxDimension * frame.unit
        val end = slotCenter(item, round.count)
        val endBox = SLOT_ART.toPx() * ART_IN_SLOT
        val center: Offset
        val boxSize: Float
        if (r < POP) {
            val q = r / POP
            val lift = sin(q * PI.toFloat() / 2)
            center = start - Offset(0f, startBox * 0.22f * lift)
            boxSize = startBox * (1f + 0.3f * lift)
            drawGlow(center, startBox * (0.5f + 0.5f * q), Color(0xFFFFF2B0).copy(alpha = 0.85f * (1f - q * 0.4f)))
        } else {
            val q = FastOutSlowInEasing.transform((r - POP) / (1f - POP))
            val from = start - Offset(0f, startBox * 0.22f)
            val control = Offset((from.x + end.x) / 2, minOf(from.y, end.y) - 90.dp.toPx())
            val a = 1f - q
            center = from * (a * a) + control * (2 * a * q) + end * (q * q)
            boxSize = startBox * 1.3f + (endBox - startBox * 1.3f) * q
            drawGlow(center, boxSize * 0.62f, Color(0xFFFFE27A).copy(alpha = 0.5f * (1f - q)))
        }
        if (r < SPARKLE) sparkleBurst(start, startBox * 1.1f, r / SPARKLE)
        drawFitted(look, grade, item, square(center, boxSize), t, stand = false)
    }
}

/** The five hiders in a frosted tray: silhouettes until each is found, then the thing itself; the keepsake ringed in gold. */
@Composable
private fun SeekTray(
    look: SeekLook,
    grade: SceneGrade,
    round: HideAndSeek,
    reveals: List<Animatable<Float, *>>,
    lands: List<Animatable<Float, *>>,
    modifier: Modifier,
) {
    val palette = LocalPalette.current
    Row(
        modifier
            .frosted(palette, RoundedCornerShape(50), elevation = 6.dp)
            .padding(horizontal = 10.dp, vertical = TRAY_PAD),
        horizontalArrangement = Arrangement.spacedBy(SLOT_GAP),
    ) {
        for (i in 0 until round.count) {
            val landed = i in round.found && reveals[i].value >= 1f
            val name = look.name(i)
            Box(
                Modifier
                    .size(SLOT)
                    .clip(CircleShape)
                    .border(if (i == 0) 2.5.dp else 1.dp, if (i == 0) GoldDeep.copy(alpha = 0.85f) else Color.White.copy(alpha = 0.7f), CircleShape)
                    .semantics { contentDescription = if (landed) "Found $name" else "Someone still hiding" },
                contentAlignment = Alignment.Center,
            ) {
                Canvas(
                    Modifier.size(SLOT_ART).graphicsLayer {
                        val pop = if (landed) 0.6f + 0.4f * lands[i].value else 1f
                        scaleX = pop
                        scaleY = pop
                    },
                ) {
                    drawCircle(Color.White.copy(alpha = if (landed) 0.35f else 0.18f), size.minDimension * 0.62f)
                    val art = square(center, size.minDimension * ART_IN_SLOT)
                    if (landed) {
                        drawFitted(look, grade, i, art, 0f, stand = false)
                    } else {
                        silhouette(Color.Black.copy(alpha = 0.22f)) { drawFitted(look, grade, i, art, 0f, stand = false) }
                    }
                }
            }
        }
    }
}

/** How much of a slot's art square the art fills. */
private const val ART_IN_SLOT = 0.86f

private val SLOT = 50.dp
private val SLOT_ART = 42.dp
private val SLOT_GAP = 8.dp
private val TRAY_PAD = 7.dp
private val TRAY_GAP = 8.dp

/** The room the scene leaves at the bottom of the play area for the tray. */
private val TRAY_RESERVE = SLOT + TRAY_PAD * 2 + TRAY_GAP + 6.dp

/** The smallest distance from a thing still hiding that a tap finds it at, so small ones are easy to hit. */
private val MIN_REACH = 30.dp

private const val REVEAL_MS = 1250
private const val RUSTLE_MS = 750
private const val HINT_MS = 1100
private const val HINT_PAUSE_MS = 1600L
private const val SEEK_FINISH_MS = 700L

/** How much of a reveal the pop out of the spot takes, and how long its sparkle lasts. */
private const val POP = 0.28f
private const val SPARKLE = 0.55f
