// The drawing of the toss: the scenery, the keepsake by the launcher, the sling and its pouch, the dotted arc, the
// targets as they pop up, topple or fill, the ball in flight and the puffs it makes. Positions are in the round's
// field (see [TossLayout]); [t] is the round's time in seconds.

private const val TAU = (2 * PI).toFloat()

/** A puff of sand at ([x], [y]) in the field, made at [at] seconds, [size] times a small one. */
internal class TossPuff(val x: Float, val y: Float, val at: Float, val size: Float)

/** How long a puff lasts, in seconds. */
internal const val PUFF_S = 0.7f

/** How long the splat of a ball that missed stays on the ground. */
private const val SPLAT_S = 2.6f

/** The sky, the far hills or building site, and the ground the targets stand on. */
internal fun DrawScope.drawTossScenery(look: TossLook, layout: TossLayout, t: Float) {
    val u = layout.unit
    val w = layout.width
    val h = layout.height
    val gy = layout.groundY
    drawRect(Brush.verticalGradient(listOf(look.skyTop, look.skyBottom), 0f, gy), Offset.Zero, Size(w, gy + 1f))
    val sun = Offset(w * 0.8f, minOf(gy * 0.16f, 18f * u))
    drawGlow(sun, 26f * u, Color(0xFFFFF4C2).copy(alpha = 0.75f))
    drawCircle(Color(0xFFFFF3C8), 8f * u, sun)
    for (k in 0 until 3) {
        val x = wrap(0.1f + k * 0.37f + t * (0.004f + k * 0.0015f)) * 1.4f - 0.2f
        puffyCloud(Offset(x * w, gy * (0.2f + 0.14f * k) + 6f * u), (1f - k * 0.18f) * u)
    }
    when (look.scene) {
        TossScene.PLAYGROUND -> {
            hills(layout, gy - 22f * u, 9f * u, 1.3f, 0.2f, lerp(look.far, look.skyBottom, 0.45f))
            // A swing set on the far hill, and a big tree at the right edge of the lawn.
            val haze = lerp(look.frameDark, look.skyBottom, 0.55f)
            val sx = w * 0.56f
            val sy = gy - 24f * u
            stick(haze, Offset(sx - 9f * u, sy + 9f * u), Offset(sx - 6f * u, sy - 3f * u), 0.9f * u)
            stick(haze, Offset(sx - 3f * u, sy + 9f * u), Offset(sx - 6f * u, sy - 3f * u), 0.9f * u)
            stick(haze, Offset(sx + 13f * u, sy + 9f * u), Offset(sx + 16f * u, sy - 3f * u), 0.9f * u)
            stick(haze, Offset(sx + 19f * u, sy + 9f * u), Offset(sx + 16f * u, sy - 3f * u), 0.9f * u)
            stick(haze, Offset(sx - 6f * u, sy - 3f * u), Offset(sx + 16f * u, sy - 3f * u), 0.9f * u)
            for (k in 0..1) {
                val px = sx + (1.5f + k * 8f) * u
                val swingA = sin(t * 1.3f + k) * 1.2f * u
                stick(haze.copy(alpha = 0.8f), Offset(px, sy - 3f * u), Offset(px + swingA, sy + 5f * u), 0.35f * u)
                stick(haze.copy(alpha = 0.8f), Offset(px + 3f * u, sy - 3f * u), Offset(px + 3f * u + swingA, sy + 5f * u), 0.35f * u)
                stick(haze, Offset(px - 0.4f * u + swingA, sy + 5f * u), Offset(px + 3.4f * u + swingA, sy + 5f * u), 0.8f * u)
            }
            hills(layout, gy - 12f * u, 7f * u, 2.1f, 0.6f, look.far)
            val tx = w * 0.97f
            val crown = gy - minOf(gy * 0.62f, 62f * u)
            box(look.frameDark, tx - 2.2f * u, crown + 10f * u, tx + 2.2f * u, gy - 2f * u, 1f * u)
            val leaf = lerp(look.far, look.groundShade, 0.4f)
            for ((dx, dy, r) in listOf(Triple(-8f, 12f, 11f), Triple(4f, 6f, 12f), Triple(-2f, -2f, 10f), Triple(8f, 18f, 9f))) {
                drawCircle(lerp(leaf, Color.Black, 0.12f), r * u, Offset(tx + dx * u, crown + dy * u + 1.2f * u))
                drawCircle(leaf, r * u, Offset(tx + dx * u, crown + dy * u))
            }
            drawCircle(Color.White.copy(alpha = 0.16f), 5f * u, Offset(tx - 6f * u, crown + 2f * u))
            // A picket fence along the back of the lawn.
            val fenceTop = gy - 9f * u
            val wood = lerp(look.frame, Color.White, 0.35f)
            box(wood, 0f, fenceTop + 2.6f * u, w, fenceTop + 3.6f * u)
            box(wood, 0f, fenceTop + 5.6f * u, w, fenceTop + 6.6f * u)
            var x = 2f * u
            while (x < w) {
                val pale = Path().apply {
                    moveTo(x, fenceTop + 9.5f * u)
                    lineTo(x, fenceTop + 0.8f * u)
                    lineTo(x + 0.9f * u, fenceTop)
                    lineTo(x + 1.8f * u, fenceTop + 0.8f * u)
                    lineTo(x + 1.8f * u, fenceTop + 9.5f * u)
                    close()
                }
                drawPath(pale, wood)
                drawPath(pale, Color.Black.copy(alpha = 0.08f), style = Stroke(0.25f * u))
                x += 4.2f * u
            }
            groundBand(look, layout, gy - 1f * u)
            // Tufts and little flowers scattered over the lawn.
            val r = SceneRandom(7)
            repeat(26) {
                val px = r.next() * w
                val py = gy + r.next(0.06f, 0.92f) * (h - gy)
                if (it % 4 == 0) {
                    val c = if (it % 8 == 0) Color(0xFFFFD54F) else Color.White
                    for (p in 0 until 5) {
                        val a = p * TAU / 5
                        drawCircle(c, 0.55f * u, Offset(px + cos(a) * 0.6f * u, py + sin(a) * 0.6f * u))
                    }
                    drawCircle(Color(0xFFF5A623), 0.45f * u, Offset(px, py))
                } else {
                    for (b in -1..1) {
                        drawLine(look.groundShade, Offset(px, py), Offset(px + b * 0.8f * u, py - 1.8f * u), 0.45f * u, StrokeCap.Round)
                    }
                }
            }
            // A patch of sandbox sand around the sling.
            val sandC = layout.at(0.1f, 0f)
            drawOval(look.ballDark.copy(alpha = 0.8f), Offset(sandC.x - 13f * u, sandC.y - 2f * u), Size(26f * u, 7.5f * u))
            drawOval(look.ball, Offset(sandC.x - 12.5f * u, sandC.y - 2.2f * u), Size(25f * u, 6.6f * u))
        }
        TossScene.SITE -> {
            // A crane and a half-built frame, hazy in the distance.
            val haze = lerp(look.far, look.skyBottom, 0.35f)
            val mastX = w * 0.7f
            val top = gy - minOf(gy * 0.62f, 60f * u)
            box(haze, mastX - 1.4f * u, top, mastX + 1.4f * u, gy - 10f * u)
            var y = top + 2f * u
            while (y < gy - 12f * u) {
                drawLine(lerp(haze, look.skyBottom, 0.5f), Offset(mastX - 1.4f * u, y), Offset(mastX + 1.4f * u, y + 2.6f * u), 0.4f * u)
                y += 3f * u
            }
            box(haze, mastX - 30f * u, top - 1.2f * u, mastX + 14f * u, top + 0.8f * u)
            box(haze, mastX + 8f * u, top - 0.4f * u, mastX + 14f * u, top + 3.5f * u)
            drawLine(haze, Offset(mastX - 22f * u, top + 0.5f * u), Offset(mastX - 22f * u, top + 14f * u + sin(t * 0.8f) * 0.6f * u), 0.3f * u)
            box(haze, mastX - 24f * u, top + 14f * u, mastX - 20f * u, top + 16f * u, 0.4f * u)
            val frameTop = gy - 30f * u
            for (k in 0..3) box(look.far, w * 0.06f + k * 9f * u, frameTop, w * 0.06f + k * 9f * u + 1.6f * u, gy - 8f * u)
            for (k in 0..2) box(look.far, w * 0.06f, frameTop + k * 8f * u, w * 0.06f + 28.6f * u, frameTop + k * 8f * u + 1.3f * u)
            hills(layout, gy - 9f * u, 3f * u, 1.6f, 0.3f, look.farLight)
            groundBand(look, layout, gy - 1f * u)
            // Gravel speckle.
            val r = SceneRandom(11)
            repeat(70) {
                val c = listOf(Color(0xFF6B6763), Color(0xFFE6E3DD), Color(0xFF9A948C))[it % 3]
                val px = r.next() * w
                val py = gy + r.next(0.05f, 0.95f) * (h - gy)
                drawOval(c.copy(alpha = 0.7f), Offset(px, py), Size(r.next(0.5f, 1.3f) * u, r.next(0.35f, 0.8f) * u))
            }
            // A striped kerb along the back of the yard.
            val kerbTop = gy - 2.4f * u
            box(Color(0xFFB9B5AE), 0f, kerbTop, w, gy - 0.6f * u)
            var x = 0f
            var k = 0
            while (x < w) {
                box(if (k % 2 == 0) Color(0xFFF7C12C) else Color(0xFF3B3A3E), x, kerbTop, x + 6f * u, kerbTop + 1f * u)
                x += 6f * u
                k++
            }
        }
    }
}

/**
 * The foreground below the ground line, and the keepsake in it: a sandbox corner with the ball on the Playground, a
 * heap of sand and sandbags with the cone on the Building Site. At scene clock [sceneT].
 */
internal fun DrawScope.drawTossForeground(look: TossLook, layout: TossLayout, grade: SceneGrade, sceneT: Float) {
    val u = layout.unit
    val w = layout.width
    val h = layout.height
    val band = h - layout.groundY
    val size = minOf(w * 0.3f, band * 0.72f)
    val bottom = h - band * 0.08f
    when (look.scene) {
        TossScene.PLAYGROUND -> {
            // The corner of the sandbox, its wooden edge running off the bottom and the left.
            val top = bottom - size * 0.55f
            val right = w * 0.08f + size * 1.25f
            val sand = Path().apply {
                moveTo(-1f, top)
                lineTo(right - size * 0.2f, top)
                quadraticTo(right, top, right, top + size * 0.2f)
                lineTo(right, h + 1f)
                lineTo(-1f, h + 1f)
                close()
            }
            drawPath(sand, look.ballDark)
            drawPath(sand, Brush.verticalGradient(listOf(look.ballLight, look.ball), top, h), alpha = 0.95f)
            drawPath(sand, look.frameDark, style = Stroke(2.6f * u))
            drawPath(sand, look.frame, style = Stroke(1.4f * u))
            val r = SceneRandom(3)
            repeat(24) {
                drawCircle(look.ballDark.copy(alpha = 0.35f), r.next(0.2f, 0.45f) * u, Offset(r.next(0f, right - 2f * u), r.next(top + 2f * u, h)))
            }
        }
        TossScene.SITE -> {
            // A heap of building sand with a few sandbags, at the bottom right.
            val cx = w * 0.8f
            val heap = Path().apply {
                moveTo(cx - size * 1.0f, h + 1f)
                quadraticTo(cx - size * 0.35f, bottom - size * 0.55f, cx, bottom - size * 0.5f)
                quadraticTo(cx + size * 0.4f, bottom - size * 0.5f, cx + size * 1.0f, h + 1f)
                close()
            }
            drawPath(heap, Brush.verticalGradient(listOf(look.ballLight, look.ball, look.ballDark), bottom - size * 0.55f, h))
            for (k in 0 until 3) {
                val c = Offset(cx - size * 0.45f + k * size * 0.42f, bottom - size * (if (k == 1) 0.28f else 0.12f))
                val bw = size * 0.36f
                val bh = size * 0.2f
                drawRoundRect(look.ballDark, Offset(c.x - bw / 2, c.y - bh / 2), Size(bw, bh), CornerRadius(bh * 0.45f))
                drawRoundRect(look.ball, Offset(c.x - bw / 2 + 0.3f * u, c.y - bh / 2), Size(bw - 0.6f * u, bh * 0.85f), CornerRadius(bh * 0.42f))
                drawLine(look.ballDark.copy(alpha = 0.4f), Offset(c.x - bw * 0.35f, c.y), Offset(c.x + bw * 0.35f, c.y), 0.3f * u)
            }
        }
    }
    val k = size / 100f
    translate(w * 0.08f + size * 0.6f - 50f * k, bottom - 96f * k) {
        scale(k, k, Offset.Zero) { drawKeepsake(look.arena, look.stage, sceneT, grade) }
    }
}

/** The sling's post and its far fork arm with the band behind the ball; drawn before the ball and targets. */
internal fun DrawScope.drawLauncherBack(look: TossLook, layout: TossLayout, round: SandToss) {
    val u = layout.unit
    val base = layout.at(SandToss.LAUNCH_X, 0f)
    val fork = layout.at(SandToss.LAUNCH_X, SandToss.LAUNCH_Y - 0.055f)
    val back = layout.at(SandToss.LAUNCH_X + 0.028f, SandToss.LAUNCH_Y + 0.012f)
    // Spare balls heaped at the foot of the post.
    for (i in 0 until 3) {
        val c = layout.at(SandToss.LAUNCH_X + 0.045f + i * 0.03f - (if (i == 2) 0.045f else 0f), if (i == 2) 0.032f else 0.012f)
        spareBall(look, c, layout.len(SandToss.RADIUS) * 1.1f)
    }
    drawOval(Color.Black.copy(alpha = 0.18f), Offset(base.x - 4f * u, base.y - 0.8f * u), Size(8f * u, 1.8f * u))
    stick(look.frameDark, base, fork, 3.2f * u)
    stick(look.frame, base + Offset(-0.5f * u, 0f), fork + Offset(-0.5f * u, 0f), 2.2f * u)
    stick(look.frameDark, fork, back, 2.5f * u)
    if (look.scene == TossScene.SITE) {
        // Hazard stripes on the steel post.
        for (k in 0 until 3) {
            val y = base.y - (1.5f + k * 2.6f) * u
            drawLine(Color(0xFF3B3A3E), Offset(base.x - 1.2f * u, y), Offset(base.x + 1.2f * u, y - 1f * u), 0.9f * u)
        }
    }
    val pouch = pouchAt(layout, round)
    stick(lerp(look.band, Color.Black, 0.25f), back, pouch, 0.9f * u)
}

/** The sling's near fork arm, the band in front and the pouch, holding the next ball while one can be thrown. */
internal fun DrawScope.drawLauncherFront(look: TossLook, layout: TossLayout, round: SandToss, t: Float) {
    val u = layout.unit
    val fork = layout.at(SandToss.LAUNCH_X, SandToss.LAUNCH_Y - 0.055f)
    val front = layout.at(SandToss.LAUNCH_X - 0.026f, SandToss.LAUNCH_Y + 0.01f)
    val pouch = pouchAt(layout, round)
    if (round.canThrow) drawBall(look, layout, pouch, 0f, round.arena == Arena.BUILDING_SITE)
    val leather = lerp(look.frameDark, Color.Black, 0.2f)
    val dir = (pouch - layout.at(SandToss.LAUNCH_X, SandToss.LAUNCH_Y)).let { if (it.getDistance() < 0.1f) Offset(-1f, 0f) else it / it.getDistance() }
    stick(leather, pouch + Offset(-dir.y, dir.x) * 2.2f * u, pouch - Offset(-dir.y, dir.x) * 2.2f * u, 1.6f * u)
    stick(look.band, front, pouch, 1f * u)
    stick(look.frameDark, fork, front, 2.5f * u)
    stick(look.frame, fork + Offset(0f, -0.25f * u), front + Offset(0.25f * u, -0.25f * u), 1.5f * u)
    drawCircle(look.frameDark, 1.35f * u, front)
}

/** Where the pouch is: drawn back along the aim by the power while a throw is ready, at rest otherwise. */
private fun pouchAt(layout: TossLayout, round: SandToss): Offset {
    if (!round.canThrow) return layout.at(SandToss.LAUNCH_X, SandToss.LAUNCH_Y - 0.008f)
    val a = round.angle * PI.toFloat() / 180f
    val back = 0.015f + round.power * 0.065f
    return layout.at(SandToss.LAUNCH_X - cos(a) * back, SandToss.LAUNCH_Y - sin(a) * back)
}

/** The dotted arc from the launcher as aimed: dots fading out along it, and a soft ring where it ends on something. */
internal fun DrawScope.drawTossPreview(layout: TossLayout, round: SandToss, color: Color) {
    if (!round.canThrow) return
    val arc = round.preview()
    val u = layout.unit
    val step = 3
    val count = arc.size
    var i = step
    while (i < count) {
        val f = i.toFloat() / count
        val c = layout.at(arc[i])
        drawCircle(Color.Black.copy(alpha = 0.12f), 1.15f * u, c + Offset(0f, 0.3f * u))
        drawCircle(color.copy(alpha = 0.95f - 0.45f * f), 1.05f * u, c)
        i += step
    }
    if (round.previewSeconds >= SandToss.FULL_PREVIEW) {
        val end = layout.at(arc.last())
        drawCircle(color.copy(alpha = 0.7f), 2.4f * u, end, style = Stroke(0.6f * u))
    }
}

/** The ball in flight, tumbling as it goes. */
internal fun DrawScope.drawTossBall(look: TossLook, layout: TossLayout, round: SandToss) {
    val b = round.ball ?: return
    val c = layout.at(b.x, b.y)
    val spin = (round.time - b.thrownAt) * (if (b.vx >= 0f) 1f else -1f) * 7f
    // A faint trail of sand behind it.
    for (k in 1..4) {
        val back = Offset(b.vx, -b.vy) * (-0.022f * k * layout.width)
        drawCircle(look.ball.copy(alpha = 0.32f - k * 0.07f), layout.len(SandToss.RADIUS) * (1f - k * 0.16f), c + back)
    }
    drawBall(look, layout, c, spin, round.arena == Arena.BUILDING_SITE)
}

/** A sandball (or a sandbag when [bag]) centered at [c], turned by [spin] radians. */
private fun DrawScope.drawBall(look: TossLook, layout: TossLayout, c: Offset, spin: Float, bag: Boolean) {
    val r = layout.len(SandToss.RADIUS) * 1.15f
    if (bag) {
        rotate(spin * 180f / PI.toFloat() * 0.5f, c) {
            drawRoundRect(look.ballDark, c - Offset(r * 1.05f, r * 0.8f), Size(r * 2.1f, r * 1.75f), CornerRadius(r * 0.6f))
            drawRoundRect(look.ball, c - Offset(r * 1.0f, r * 0.85f), Size(r * 2f, r * 1.6f), CornerRadius(r * 0.55f))
            // Burlap weave and the tied neck.
            for (k in -1..1) drawLine(look.ballDark.copy(alpha = 0.35f), c + Offset(-r * 0.8f, k * r * 0.45f), c + Offset(r * 0.8f, k * r * 0.45f), r * 0.1f)
            drawRoundRect(look.ballDark, c + Offset(r * 0.85f, -r * 0.35f), Size(r * 0.45f, r * 0.7f), CornerRadius(r * 0.2f))
            drawOval(look.ballLight.copy(alpha = 0.7f), c - Offset(r * 0.7f, r * 0.7f), Size(r * 0.9f, r * 0.4f))
        }
        return
    }
    drawCircle(look.ballDark, r, c + Offset(0f, r * 0.08f))
    drawCircle(look.ball, r * 0.94f, c)
    // Grains turning with it.
    for (k in 0 until 6) {
        val a = spin + k * TAU / 6 + k * 0.7f
        val d = r * (0.25f + 0.13f * (k % 3))
        drawCircle(look.ballDark.copy(alpha = 0.55f), r * 0.11f, c + Offset(cos(a) * d, sin(a) * d))
    }
    drawCircle(look.ballLight, r * 0.35f, c - Offset(r * 0.3f, r * 0.32f))
}

/** A spare ball waiting at the foot of the launcher. */
private fun DrawScope.spareBall(look: TossLook, c: Offset, r: Float) {
    drawOval(Color.Black.copy(alpha = 0.15f), Offset(c.x - r, c.y + r * 0.6f), Size(2 * r, r * 0.6f))
    drawCircle(look.ballDark, r, c)
    drawCircle(look.ball, r * 0.9f, c - Offset(r * 0.05f, r * 0.08f))
    drawCircle(look.ballLight.copy(alpha = 0.8f), r * 0.3f, c - Offset(r * 0.32f, r * 0.35f))
}

/** Every target: popping up when it appears, toppling over or filling up once hit, then fading away. */
internal fun DrawScope.drawTossTargets(look: TossLook, layout: TossLayout, round: SandToss, grade: SceneGrade) {
    for (target in round.targets) {
        val grow = ((round.time - target.appearedAt) / 0.45f).coerceIn(0f, 1f)
        val pop = if (grow >= 1f) 1f else 1f + 0.18f * sin(grow * PI.toFloat()) - (1f - grow) * (1f - grow) * (1f - grow)
        val hit = target.hitAt?.let { ((round.time - it) / SandToss.CLEAR_S).coerceIn(0f, 1f) }
        val base = layout.at(target.x, 0f)
        val u = layout.unit
        val alpha = if (hit == null) 1f else (1f - (hit - 0.7f) / 0.3f).coerceIn(0f, 1f)
        if (alpha <= 0f) continue
        val shadowW = layout.len(target.kind.halfWidth) * 2.2f
        drawOval(Color.Black.copy(alpha = 0.18f * alpha * pop.coerceAtMost(1f)), Offset(base.x - shadowW / 2, base.y - 0.9f * u), Size(shadowW, 2f * u))
        scale(pop.coerceAtLeast(0.01f), pop.coerceAtLeast(0.01f), base) {
            when (target.kind) {
                TossTargetKind.BLOCKS -> blocks(layout, target, hit, alpha, grade)
                TossTargetKind.CONES -> cones(layout, target, hit, alpha, grade)
                TossTargetKind.BUCKET -> bucket(look, layout, target, hit, alpha, grade)
                TossTargetKind.PALLET -> pallet(look, layout, target, hit, alpha, grade)
            }
        }
        if (hit != null) {
            // A ring of sparkles bursting from where it was hit.
            val c = layout.at(target.x, target.top)
            val burst = (hit / 0.6f).coerceAtMost(1f)
            for (k in 0 until 7) {
                val a = k * TAU / 7 + target.id
                val d = (3f + 9f * burst) * u
                drawSparkle(c + Offset(cos(a) * d, sin(a) * d * 0.8f - 3f * burst * u), (1.6f - burst) * u + 0.5f * u, Color(0xFFFFE27A).copy(alpha = (1f - burst) * alpha))
            }
        }
    }
}

/** Toy blocks: two on the ground, one on them and a little one on top; once hit they tumble apart. */
private fun DrawScope.blocks(layout: TossLayout, target: TossTarget, hit: Float?, alpha: Float, g: SceneGrade) {
    val s = target.kind.halfWidth
    val colors = listOf(g(0xFFE8494E), g(0xFF3E8EE0), g(0xFFFFC93A), g(0xFF4DBA6A))
    // Each block: middle in the field, size, and which way it tumbles.
    val parts = listOf(
        Triple(target.x - s / 2, s / 2, s) to -1f,
        Triple(target.x + s / 2, s / 2, s) to 1f,
        Triple(target.x, s * 1.5f, s) to 0.6f,
        Triple(target.x + s * 0.08f, s * 2.4f, s * 0.8f) to 1.4f,
    )
    parts.forEachIndexed { i, (p, way) ->
        val (x, y, size) = p
        val fall = hit?.let { (it / 0.6f).coerceAtMost(1f) } ?: 0f
        // Tumbling: out to its side, down to the ground, turning over.
        val dx = way * s * 1.2f * fall
        val dy = -(y - size / 2) * fall * fall + 0.05f * sin(fall * PI.toFloat()) * (if (i >= 2) 1f else 0.3f)
        val c = layout.at(x + dx, y + dy)
        val half = layout.len(size) / 2
        val color = colors[(i + target.id) % colors.size]
        rotate(way * 90f * fall, c) {
            drawRoundRect(lerp(color, Color.Black, 0.25f).copy(alpha = alpha), Offset(c.x - half, c.y - half), Size(half * 2, half * 2), CornerRadius(half * 0.28f))
            drawRoundRect(color.copy(alpha = alpha), Offset(c.x - half, c.y - half), Size(half * 2, half * 1.82f), CornerRadius(half * 0.28f))
            drawRoundRect(Color.White.copy(alpha = 0.85f * alpha), Offset(c.x - half * 0.62f, c.y - half * 0.66f), Size(half * 1.24f, half * 1.2f), CornerRadius(half * 0.2f))
            // A simple picture on the face: a dot, a heart-ish pair, a triangle or a bar.
            val ink = color.copy(alpha = alpha)
            when ((i + target.id) % 4) {
                0 -> drawCircle(ink, half * 0.36f, c - Offset(0f, half * 0.05f))
                1 -> {
                    drawCircle(ink, half * 0.22f, c + Offset(-half * 0.22f, -half * 0.12f))
                    drawCircle(ink, half * 0.22f, c + Offset(half * 0.22f, -half * 0.12f))
                    drawCircle(ink, half * 0.22f, c + Offset(0f, half * 0.18f))
                }
                2 -> drawPath(Path().apply {
                    moveTo(c.x, c.y - half * 0.45f)
                    lineTo(c.x + half * 0.42f, c.y + half * 0.3f)
                    lineTo(c.x - half * 0.42f, c.y + half * 0.3f)
                    close()
                }, ink)
                else -> drawRoundRect(ink, Offset(c.x - half * 0.38f, c.y - half * 0.14f), Size(half * 0.76f, half * 0.28f), CornerRadius(half * 0.1f))
            }
        }
    }
}

/** Two traffic cones with a plank across them and a third on top; once hit they tip over and roll away. */
private fun DrawScope.cones(layout: TossLayout, target: TossTarget, hit: Float?, alpha: Float, g: SceneGrade) {
    val fall = hit?.let { (it / 0.6f).coerceAtMost(1f) } ?: 0f
    val k = target.kind.halfWidth / 0.052f
    val orange = g(0xFFFF6B2C).copy(alpha = alpha)
    val dark = g(0xFFD9481A).copy(alpha = alpha)
    val white = g(0xFFF8F4EE).copy(alpha = alpha)
    val baseC = g(0xFF3B3A3E).copy(alpha = alpha)
    fun cone(x: Float, y: Float, way: Float, lift: Float) {
        val foot = layout.at(x + way * 0.07f * k * fall, y * (1f - fall) + lift * sin(fall * PI.toFloat()))
        val w = layout.len(0.05f * k)
        val h = layout.len(0.075f * k)
        rotate(way * 95f * fall, foot) {
            drawRoundRect(baseC, Offset(foot.x - w * 0.55f, foot.y - h * 0.1f), Size(w * 1.1f, h * 0.1f), CornerRadius(w * 0.08f))
            val body = Path().apply {
                moveTo(foot.x - w * 0.42f, foot.y - h * 0.08f)
                lineTo(foot.x - w * 0.1f, foot.y - h)
                quadraticTo(foot.x, foot.y - h * 1.06f, foot.x + w * 0.1f, foot.y - h)
                lineTo(foot.x + w * 0.42f, foot.y - h * 0.08f)
                close()
            }
            drawPath(body, orange)
            drawRect(white, Offset(foot.x - w * 0.3f, foot.y - h * 0.5f), Size(w * 0.6f, h * 0.13f))
            drawRect(white, Offset(foot.x - w * 0.18f, foot.y - h * 0.78f), Size(w * 0.36f, h * 0.1f))
            drawPath(Path().apply {
                moveTo(foot.x + w * 0.05f, foot.y - h)
                lineTo(foot.x + w * 0.42f, foot.y - h * 0.08f)
                lineTo(foot.x + w * 0.18f, foot.y - h * 0.08f)
                close()
            }, dark.copy(alpha = 0.35f * alpha))
        }
    }
    cone(target.x - 0.027f * k, 0f, -1f, 0.02f)
    cone(target.x + 0.027f * k, 0f, 1f, 0.02f)
    // The plank across their tips.
    val plankY = 0.078f * k
    val plank = layout.at(target.x + 0.03f * fall, plankY * (1f - fall))
    rotate(25f * fall, plank) {
        drawRoundRect(g(0xFFB97B45).copy(alpha = alpha), Offset(plank.x - layout.len(0.058f * k), plank.y - layout.len(0.012f * k)), Size(layout.len(0.116f * k), layout.len(0.012f * k)), CornerRadius(layout.unit * 0.3f))
    }
    cone(target.x, plankY + 0.012f * k, 0.7f, 0.06f)
}

/** A sand bucket with a handle; once a ball drops in it hops and shows a heap of sand. */
private fun DrawScope.bucket(look: TossLook, layout: TossLayout, target: TossTarget, hit: Float?, alpha: Float, g: SceneGrade) {
    val colors = listOf(g(0xFFE6533F) to g(0xFFFF8A6B), g(0xFF3E8EE0) to g(0xFF7FC4FF), g(0xFF4DBA6A) to g(0xFF8FE09A), g(0xFFFFC93A) to g(0xFFFFE27A))
    val (body, rim) = colors[target.id % colors.size]
    val hop = hit?.let { sin((it / 0.35f).coerceAtMost(1f) * PI.toFloat()) * 0.02f } ?: 0f
    val hw = target.kind.halfWidth
    val top = layout.y(target.top + hop)
    val bottom = layout.y(hop)
    val l = layout.x(target.x - hw)
    val r = layout.x(target.x + hw)
    val inset = layout.len(0.012f)
    val u = layout.unit
    // The handle, arching over the top.
    drawArc(lerp(body, Color.Black, 0.35f).copy(alpha = alpha), 200f, 140f, false, Offset(l + inset, top - layout.len(hw * 0.85f)), Size(r - l - 2 * inset, layout.len(hw * 1.9f)), style = Stroke(0.7f * u))
    val pail = Path().apply {
        moveTo(l, top)
        lineTo(r, top)
        lineTo(r - inset, bottom)
        quadraticTo(layout.x(target.x), bottom + 0.6f * u, l + inset, bottom)
        close()
    }
    drawPath(pail, body.copy(alpha = alpha))
    drawPath(Path().apply {
        moveTo(layout.x(target.x + hw * 0.35f), top)
        lineTo(r, top)
        lineTo(r - inset, bottom)
        lineTo(layout.x(target.x + hw * 0.3f), bottom)
        close()
    }, Color.Black.copy(alpha = 0.12f * alpha))
    drawLine(Color.White.copy(alpha = 0.45f * alpha), Offset(l + inset * 1.1f, top + 1.6f * u), Offset(l + inset * 1.5f, bottom - 1.2f * u), 0.9f * u, StrokeCap.Round)
    if (hit != null) {
        // A heap of sand peeking out of the top.
        drawOval(look.ballDark.copy(alpha = alpha), Offset(l + inset * 0.4f, top - 2.6f * u), Size(r - l - inset * 0.8f, 4.4f * u))
        drawOval(look.ball.copy(alpha = alpha), Offset(l + inset * 0.6f, top - 2.9f * u), Size(r - l - inset * 1.2f, 3.8f * u))
    } else {
        drawOval(lerp(body, Color.Black, 0.45f).copy(alpha = alpha), Offset(l + 0.4f * u, top - 1.2f * u), Size(r - l - 0.8f * u, 2.4f * u))
    }
    drawRoundRect(rim.copy(alpha = alpha), Offset(l - 0.4f * u, top - 0.6f * u), Size(r - l + 0.8f * u, 1.5f * u), CornerRadius(0.7f * u))
}

/** A wooden pallet; once a sandbag lands on it the bag sits there, squashed a little. */
private fun DrawScope.pallet(look: TossLook, layout: TossLayout, target: TossTarget, hit: Float?, alpha: Float, g: SceneGrade) {
    val hw = target.kind.halfWidth
    val wood = g(0xFFDDA567).copy(alpha = alpha)
    val woodDark = g(0xFF9A6638).copy(alpha = alpha)
    val l = layout.x(target.x - hw)
    val r = layout.x(target.x + hw)
    val top = layout.y(target.top)
    val bottom = layout.y(0f)
    val u = layout.unit
    val h = bottom - top
    // Blocks underneath and slats on top.
    for (k in 0..2) {
        val x = l + (r - l) * (0.06f + 0.44f * k) - 0f
        drawRect(woodDark, Offset(x, top + h * 0.35f), Size((r - l) * 0.12f, h * 0.65f))
    }
    drawRect(wood, Offset(l, top + h * 0.3f), Size(r - l, h * 0.16f))
    for (k in 0 until 5) {
        val x = l + (r - l) * k / 5f
        drawRoundRect(wood, Offset(x + 0.15f * u, top), Size((r - l) / 5f - 0.3f * u, h * 0.32f), CornerRadius(0.3f * u))
        drawLine(woodDark.copy(alpha = 0.4f * alpha), Offset(x + 0.15f * u, top + h * 0.32f), Offset(x + (r - l) / 5f - 0.15f * u, top + h * 0.32f), 0.3f * u)
    }
    if (hit != null) {
        val squash = 1f - 0.25f * sin((hit / 0.3f).coerceAtMost(1f) * PI.toFloat())
        val bw = layout.len(hw * 0.8f) * (2f - squash)
        val bh = layout.len(hw * 0.45f) * squash
        val c = Offset(layout.x(target.x), top - bh / 2)
        drawRoundRect(look.ballDark.copy(alpha = alpha), Offset(c.x - bw / 2, c.y - bh / 2), Size(bw, bh), CornerRadius(bh * 0.45f))
        drawRoundRect(look.ball.copy(alpha = alpha), Offset(c.x - bw / 2 + 0.3f * u, c.y - bh / 2), Size(bw - 0.6f * u, bh * 0.85f), CornerRadius(bh * 0.42f))
        drawRoundRect(look.ballDark.copy(alpha = alpha), Offset(c.x + bw / 2 - 0.4f * u, c.y - bh * 0.25f), Size(1.6f * u, bh * 0.5f), CornerRadius(0.5f * u))
    }
}

/** The splat a ball leaves where it came down without hitting anything, fading into the ground. */
internal fun DrawScope.drawTossSplat(look: TossLook, layout: TossLayout, round: SandToss) {
    val (p, at) = round.splat ?: return
    val age = round.time - at
    if (age > SPLAT_S) return
    val a = (1f - age / SPLAT_S).coerceIn(0f, 1f)
    val c = layout.at(p.x, 0f)
    val u = layout.unit
    val spread = (age / 0.18f).coerceAtMost(1f)
    drawOval(look.ballDark.copy(alpha = 0.7f * a), Offset(c.x - 4.2f * u * spread, c.y - 1.2f * u), Size(8.4f * u * spread, 2.4f * u))
    drawOval(look.ball.copy(alpha = a), Offset(c.x - 3.6f * u * spread, c.y - 1.5f * u), Size(7.2f * u * spread, 2.1f * u))
    for (k in 0 until 4) {
        val x = c.x + (k - 1.5f) * 2.6f * u * spread
        drawCircle(look.ball.copy(alpha = a), 0.6f * u, Offset(x, c.y - 1.8f * u - (k % 2) * 0.6f * u))
    }
}

/** The little puffs of sand where balls bounced, splatted or hit something. */
internal fun DrawScope.drawTossPuffs(look: TossLook, layout: TossLayout, puffs: List<TossPuff>, t: Float) {
    val u = layout.unit
    for (puff in puffs) {
        val age = ((t - puff.at) / PUFF_S).coerceIn(0f, 1f)
        val c = layout.at(puff.x, puff.y)
        val out = 1f - (1f - age) * (1f - age)
        for (k in 0 until 7) {
            val a = -PI.toFloat() * (0.08f + 0.84f * k / 6f)
            val d = (1.5f + 5f * out) * u * puff.size
            drawCircle(
                lerp(look.ballLight, Color.White, 0.3f).copy(alpha = 0.75f * (1f - age)),
                (1.6f - 0.8f * age) * u * puff.size,
                c + Offset(cos(a) * d, sin(a) * d * 0.7f),
            )
        }
    }
}

private fun DrawScope.hills(layout: TossLayout, base: Float, rise: Float, waves: Float, phase: Float, color: Color) {
    val w = layout.width
    val path = Path().apply {
        moveTo(0f, layout.height)
        val steps = 32
        for (s in 0..steps) {
            val x = w * s / steps
            val p = s.toFloat() / steps
            val y = base - rise * (0.5f + 0.5f * sin(TAU * (p * waves + phase)))
            lineTo(x, y)
        }
        lineTo(w, layout.height)
        close()
    }
    drawPath(path, color)
}

private fun DrawScope.groundBand(look: TossLook, layout: TossLayout, top: Float) {
    drawRect(
        Brush.verticalGradient(listOf(look.groundLight, look.ground, look.groundShade), top, layout.height),
        Offset(0f, top),
        Size(layout.width, layout.height - top),
    )
    drawRect(Color.White.copy(alpha = 0.18f), Offset(0f, top), Size(layout.width, layout.unit * 0.6f))
}

private fun DrawScope.puffyCloud(c: Offset, u: Float) {
    val white = Color.White.copy(alpha = 0.9f)
    drawOval(Color(0xFFC9DDF0).copy(alpha = 0.8f), c - Offset(10f * u, 2f * u), Size(20f * u, 5.5f * u))
    drawOval(white, c - Offset(10f * u, 2.8f * u), Size(20f * u, 5f * u))
    drawCircle(white, 4.2f * u, c + Offset(-3.5f * u, -2f * u))
    drawCircle(white, 5.2f * u, c + Offset(2.5f * u, -3f * u))
}

private fun DrawScope.box(color: Color, l: Float, t: Float, r: Float, b: Float, radius: Float = 0f) =
    drawRoundRect(color, Offset(l, t), Size(r - l, b - t), CornerRadius(radius))

private fun DrawScope.stick(color: Color, a: Offset, b: Offset, width: Float) = drawLine(color, a, b, width, StrokeCap.Round)

private fun wrap(v: Float): Float = v - floor(v)
