/**
 * The keepsake star of [arena]'s [stage]: when [earned], a gold-rimmed medallion with the keepsake on a disc in the
 * arena's colors, beside a level's three puzzle stars; otherwise an empty slot with a faint outline of it.
 */
@Composable
fun KeepsakeBadge(arena: Arena, stage: Int, earned: Boolean, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    Canvas(modifier.semantics { contentDescription = if (earned) "Keepsake star" else "No keepsake star yet" }) {
        drawKeepsakeBadge(arena, stage, earned, grade)
    }
}

/** Draws the [KeepsakeBadge] filling this scope. */
internal fun DrawScope.drawKeepsakeBadge(arena: Arena, stage: Int, earned: Boolean, grade: SceneGrade) {
    val r = size.minDimension / 2
    val c = center
    val disc = Path().apply { addOval(Rect(c, r * 0.78f)) }
    if (!earned) {
        drawCircle(Color.Black.copy(alpha = 0.1f), r * 0.86f, c)
        drawCircle(
            Color.Black.copy(alpha = 0.28f),
            r * 0.86f,
            c,
            style = Stroke(r * 0.12f, pathEffect = PathEffect.dashPathEffect(floatArrayOf(r * 0.28f, r * 0.2f))),
        )
        clipPath(disc) { silhouette(Color.Black.copy(alpha = 0.22f)) { keepsakeIn(arena, stage, c, r, grade) } }
        return
    }
    val colors = arenaColors(arena)
    drawCircle(Color.Black.copy(alpha = 0.22f), r * 0.98f, c + Offset(0f, r * 0.1f))
    drawCircle(Brush.verticalGradient(listOf(GoldTop, Gold, GoldDeep), c.y - r, c.y + r), r * 0.98f, c)
    drawCircle(GoldEdge, r * 0.98f, c, style = Stroke(r * 0.07f))
    drawCircle(Brush.verticalGradient(listOf(lerp(colors.light, Color.White, 0.55f), colors.light), c.y - r, c.y + r), r * 0.78f, c)
    clipPath(disc) { keepsakeIn(arena, stage, c, r, grade) }
    drawOval(Color.White.copy(alpha = 0.32f), Offset(c.x - r * 0.55f, c.y - r * 0.72f), Size(r * 1.1f, r * 0.5f))
    // A tiny star on the rim, so it reads as a star you earned.
    drawCircle(Color.White.copy(alpha = 0.9f), r * 0.1f, Offset(c.x + r * 0.62f, c.y - r * 0.62f))
}

/** The keepsake, still, standing in a badge of radius [r] around [c]. */
private fun DrawScope.keepsakeIn(arena: Arena, stage: Int, c: Offset, r: Float, grade: SceneGrade) {
    val unit = r * 1.5f / 100f
    translate(c.x - 50f * unit, c.y + r * 0.62f - 96f * unit) {
        scale(unit, unit, Offset.Zero) { drawKeepsake(arena, stage, 0f, grade) }
    }
}

/** Draws [art] as a flat shape in [color], for a silhouette of something not found yet. */
internal inline fun DrawScope.silhouette(color: Color, art: DrawScope.() -> Unit) {
    drawIntoCanvas { canvas ->
        canvas.saveLayer(Rect(Offset.Zero, size), Paint().apply { colorFilter = ColorFilter.tint(color, BlendMode.SrcIn) })
        art()
        canvas.restore()
    }
}

// The gold of the puzzle stars (see StarArt.kt), so the keepsake star sits with them.
internal val GoldTop = Color(0xFFFFF2A0)
internal val Gold = Color(0xFFFFC52E)
internal val GoldDeep = Color(0xFFE88A12)
internal val GoldEdge = Color(0xFFB2600A)
