package io.colorsand.ui.arena

import androidx.compose.foundation.layout.Spacer
import androidx.compose.runtime.Composable
import androidx.compose.runtime.State
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.drawWithCache
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.PathEffect
import androidx.compose.ui.graphics.PathMeasure
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.rotate
import androidx.compose.ui.graphics.drawscope.scale
import androidx.compose.ui.graphics.drawscope.translate
import androidx.compose.ui.graphics.lerp
import kotlin.math.cos
import kotlin.math.max
import kotlin.math.min
import kotlin.math.sin

/**
 * The Beach: a late-afternoon seaside. A warm sky glowing toward the horizon, a low sun over a turquoise sea
 * with glints on the water, a far headland with a lighthouse, waves rolling in with foam onto wet sand, shells
 * on the beach, palm fronds framing the top corners and a gull gliding by.
 */
@Composable
internal fun BeachScene(grade: SceneGrade, modifier: Modifier = Modifier) {
    val clock = rememberSceneClock()
    Spacer(
        modifier.drawWithCache {
            val art = BeachArt(size, grade)
            onDrawBehind { art.draw(this, clock) }
        },
    )
}

/** Everything the Beach draws, built once per size and grade; [draw] only moves it. */
private class BeachArt(size: Size, private val g: SceneGrade) {
    private val w = size.width
    private val h = size.height
    private val u = min(w, h * 0.6f)

    private val horizonY = h * 0.735f
    private val shoreY = h * 0.865f
    private val glow = Color(0xFFFFE3B3)
    private fun far(c: Long, amount: Float) = g(lerp(Color(c), glow, amount))

    private val sky = Brush.verticalGradient(
        0f to g(0xFF3C7FC4), 0.28f to g(0xFF78ACDA), 0.5f to g(0xFFC9C2CF), 0.64f to g(0xFFF6CDA8), 0.735f to g(glow),
        startY = 0f, endY = h,
    )

    private val sunCenter = Offset(w * 0.76f, h * 0.27f)
    private val sunCore = g(0xFFFFF4D6)
    private val sunHalo = g(0xFFFFD79A)

    // Long thin clouds lit pink from below.
    private class Cloud(val path: Path, val y: Float, val width: Float, val start: Float, val laps: Int)

    private val clouds = SceneRandom(13).let { r ->
        listOf(
            Cloud(cloudPath(u * 0.5f, 7, r), h * 0.2f, u * 0.5f, 0.1f, 1),
            Cloud(cloudPath(u * 0.34f, 6, r), h * 0.13f, u * 0.34f, 0.55f, 1),
            Cloud(cloudPath(u * 0.6f, 8, r), h * 0.075f, u * 0.6f, 0.8f, 2),
        )
    }
    private val cloudTop = g(0xFFFFF6F0)
    private val cloudPink = g(0xFFF4C3C0)

    // The far headland with a lighthouse.
    private val headland = Path().apply {
        moveTo(-1f, horizonY)
        lineTo(-1f, horizonY - u * 0.05f)
        cubicTo(w * 0.08f, horizonY - u * 0.07f, w * 0.16f, horizonY - u * 0.055f, w * 0.22f, horizonY - u * 0.03f)
        cubicTo(w * 0.27f, horizonY - u * 0.015f, w * 0.3f, horizonY - u * 0.01f, w * 0.36f, horizonY)
        close()
    }
    private val headlandColor = far(0xFF6F86B8, 0.38f)
    private val lighthouseX = w * 0.12f
    private val lighthouseBase = horizonY - u * 0.062f
    private val lighthouseWhite = far(0xFFF4F1EA, 0.25f)
    private val lighthouseRed = far(0xFFD25C4E, 0.3f)

    private val sea = Brush.verticalGradient(
        0f to far(0xFF3E8DB3, 0.25f), 0.35f to g(0xFF2AA9BC), 1f to g(0xFF5CD3C9), startY = horizonY, endY = shoreY,
    )
    private val sunPath = Brush.radialGradient(
        0f to g(Color(0x88FFE7B0)), 1f to Color.Transparent,
        center = Offset(sunCenter.x, horizonY + (shoreY - horizonY) * 0.15f), radius = u * 0.5f,
    )

    // Swell lines, finer and slower far away. Each slides one dash pattern (four waves) per lap, so the loop is seamless.
    private class Swell(val path: Path, val length: Float, val laps: Int, val stroke: Stroke, val alpha: Float)

    private val swells = listOf(0.12f, 0.32f, 0.55f, 0.8f).mapIndexed { i, f ->
        val y = horizonY + (shoreY - horizonY) * f
        val length = u * (0.07f + 0.09f * f)
        val amp = u * (0.002f + 0.005f * f)
        fun Path.wave(x: Float) {
            quadraticTo(x + length / 4, y - amp, x + length / 2, y)
            quadraticTo(x + length * 3 / 4, y + amp, x + length, y)
        }
        val path = Path().apply {
            var x = -length * (SWELL_WAVES + 1)
            moveTo(x, y)
            while (x < w + length) {
                wave(x)
                x += length
            }
        }
        // Broken into crests of uneven length, so the sea doesn't look ruled. The pattern spans exactly
        // SWELL_WAVES waves along the line, so sliding the line by that many waves looks the same.
        val arc = PathMeasure().apply { setPath(Path().apply { moveTo(0f, y); wave(0f) }, false) }.length
        val dashes = PathEffect.dashPathEffect(floatArrayOf(arc * 1.5f, arc * 0.7f, arc * 0.8f, arc * 1.0f), arc * i * 0.37f)
        Swell(path, length, i + 1, Stroke(u * (0.002f + 0.004f * f), cap = StrokeCap.Round, pathEffect = dashes), 0.3f + 0.3f * f)
    }

    private val swellColor = g(0xFFE8FFFB)

    // Glints on the water under the sun.
    private class Glint(val at: Offset, val length: Float, val cycles: Int, val phase: Float)

    private val glints = SceneRandom(29).let { r ->
        List(26) {
            val f = r.next()
            val y = horizonY + (shoreY - horizonY) * (0.03f + 0.75f * f * f)
            val spread = u * (0.05f + 0.35f * (y - horizonY) / (shoreY - horizonY))
            Glint(Offset(sunCenter.x + r.next(-1f, 1f) * spread, y), u * r.next(0.012f, 0.03f), 40 + (r.next() * 50).toInt(), r.next())
        }
    }
    private val glintColor = g(0xFFFFF7DE)

    // Sand: wet band at the water's edge, dry sand below.
    private val sand = Brush.verticalGradient(
        0f to g(0xFFE7C998), 0.25f to g(0xFFF4DEB2), 1f to g(0xFFEACD9C), startY = shoreY - u * 0.02f, endY = h,
    )
    private val wetSand = Brush.verticalGradient(
        0f to g(Color(0xFFC9A777)), 1f to g(Color(0x00C9A777)), startY = shoreY - u * 0.02f, endY = shoreY + u * 0.07f,
    )
    private val shallow = Brush.verticalGradient(
        0f to g(Color(0x0070DCD2)), 1f to g(Color(0x8878DED4)), startY = shoreY - u * 0.02f, endY = shoreY + u * 0.045f,
    )
    private val foam = g(0xFFFFFFFF)
    private val waterEdge = Path()
    private val foamLine = Path()

    private class Shell(val at: Offset, val size: Float, val turn: Float)

    private val shells = SceneRandom(31).let { r ->
        listOf(0.06f, 0.33f, 0.71f, 0.93f).map { Shell(Offset(w * it, h * r.next(0.93f, 0.985f)), u * r.next(0.018f, 0.026f), r.next(-30f, 30f)) }
    }
    private val shellPath = Path().apply {
        moveTo(0f, 0f)
        for (i in 0..8) {
            val a = PI_F * (1f + i / 8f)
            lineTo(cos(a), sin(a) * 0.85f)
        }
        close()
    }
    private val shellColor = g(0xFFF7D9CF)
    private val shellRidge = g(0xFFD9A79A)
    private val starfish = Path().apply {
        for (i in 0 until 10) {
            val a = PI_F * 2 * i / 10 - PI_F / 2
            val r = if (i % 2 == 0) 1f else 0.42f
            if (i == 0) moveTo(cos(a) * r, sin(a) * r) else lineTo(cos(a) * r, sin(a) * r)
        }
        close()
    }
    private val starfishColor = g(0xFFF2875A)
    private val starfishDots = g(0xFFFFC09A)
    private val ripples = Path().apply {
        val r = SceneRandom(37)
        repeat(9) {
            val x = w * r.next(-0.1f, 0.9f)
            val y = h * r.next(0.905f, 0.99f)
            moveTo(x, y)
            quadraticTo(x + u * 0.08f, y - u * 0.012f, x + u * r.next(0.14f, 0.24f), y)
        }
    }
    private val rippleColor = g(Color(0x33A9824F))

    // Palm fronds hanging into the top corners.
    private val frond = frondPath(u * 0.44f)
    private val frondLight = g(0xFF4E9E55)
    private val frondDark = g(0xFF2D6B3E)
    private val coconut = g(0xFF6B4A2E)
    private val frondAngles = floatArrayOf(16f, 38f, 60f, 82f, 104f)
    private val frondLengths = floatArrayOf(0.7f, 0.95f, 1f, 0.85f, 0.65f)

    private val gull = g(0xFF485062)
    private val gullFar = far(0xFF485062, 0.4f)

    private val shade = vignette(w, h, g(Color(0x3A3A2440)))

    fun draw(scope: DrawScope, clock: State<Float>) = with(scope) {
        val t = clock.value
        drawRect(sky)
        drawGlow(sunCenter, u * 1.1f, sunHalo.copy(alpha = 0.5f))
        drawGlow(sunCenter, u * 0.22f, sunCore)
        drawCircle(sunCore, u * 0.07f, sunCenter)

        for (c in clouds) {
            val x = -c.width + drift(t, c.laps, c.start) * (w + 2 * c.width)
            translate(x, c.y) {
                scale(1f, 0.62f, Offset.Zero) {
                    translate(0f, c.width * 0.05f) { drawPath(c.path, cloudPink, alpha = 0.8f) }
                    drawPath(c.path, cloudTop, alpha = 0.9f)
                }
            }
        }

        drawGull(t, laps = 1, start = 0.2f, y = h * 0.17f, s = u * 0.032f, color = gull)
        drawGull(t, laps = 1, start = 0.65f, y = h * 0.24f, s = u * 0.02f, color = gullFar)

        // Sea, from the hazy horizon to the shallows.
        drawRect(sea, Offset(0f, horizonY), Size(w, shoreY - horizonY + u * 0.02f))
        drawRect(sunPath, Offset(0f, horizonY), Size(w, shoreY - horizonY))
        drawRect(far(0xFFFFF0D0, 0.2f).copy(alpha = 0.7f), Offset(0f, horizonY - u * 0.0015f), Size(w, u * 0.003f))
        drawPath(headland, headlandColor)
        drawRect(lighthouseWhite, Offset(lighthouseX - u * 0.006f, lighthouseBase - u * 0.04f), Size(u * 0.012f, u * 0.04f))
        drawRect(lighthouseRed, Offset(lighthouseX - u * 0.006f, lighthouseBase - u * 0.027f), Size(u * 0.012f, u * 0.008f))
        drawRect(lighthouseRed, Offset(lighthouseX - u * 0.008f, lighthouseBase - u * 0.047f), Size(u * 0.016f, u * 0.008f))
        drawGlow(Offset(lighthouseX, lighthouseBase - u * 0.043f), u * 0.02f, glintColor.copy(alpha = 0.6f + 0.4f * swing(t, 24)))
        for (s in swells) {
            translate(drift(t, s.laps * 2) * s.length * SWELL_WAVES, 0f) {
                drawPath(s.path, swellColor, alpha = s.alpha, style = s.stroke)
            }
        }
        for (gl in glints) {
            val a = max(0f, swing(t, gl.cycles, gl.phase))
            if (a > 0.05f) drawLine(glintColor.copy(alpha = a * a), gl.at, gl.at + Offset(gl.length, 0f), u * 0.004f, StrokeCap.Round)
        }

        drawShore(t)
        drawFronds(t)
        drawRect(shade)
    }

    private fun DrawScope.drawShore(t: Float) {
        // The wave runs up the sand and slides back every ten seconds.
        val reach = 0.5f + 0.5f * swing(t, 12)
        val edge = shoreY + u * (0.005f + 0.035f * reach)
        drawRect(sand, Offset(0f, shoreY - u * 0.02f), Size(w, h - shoreY + u * 0.02f))
        drawRect(wetSand, Offset(0f, shoreY - u * 0.02f), Size(w, u * 0.09f))
        drawPath(ripples, rippleColor, style = Stroke(u * 0.003f, cap = StrokeCap.Round))
        waterEdge.reset()
        foamLine.reset()
        waterEdge.moveTo(-1f, shoreY - u * 0.02f)
        val steps = 32
        for (i in 0..steps) {
            val x = w * i / steps
            val y = edge + u * 0.008f * sin(TAU * (x / (u * 0.6f))) + u * 0.005f * swing(t, 20, x / w)
            waterEdge.lineTo(x, y)
            if (i == 0) foamLine.moveTo(x, y) else foamLine.lineTo(x, y)
        }
        waterEdge.lineTo(w + 1f, shoreY - u * 0.02f)
        waterEdge.close()
        drawPath(waterEdge, shallow)
        drawPath(foamLine, foam, alpha = 0.55f + 0.3f * reach, style = Stroke(u * 0.008f, cap = StrokeCap.Round))
        translate(0f, -u * 0.012f) { drawPath(foamLine, foam, alpha = 0.25f, style = Stroke(u * 0.004f, cap = StrokeCap.Round)) }
        for (s in shells) {
            rotate(s.turn, s.at) {
                translate(s.at.x, s.at.y) {
                    scale(s.size, s.size, Offset.Zero) {
                        drawPath(shellPath, shellColor)
                        drawPath(shellPath, shellRidge, style = Stroke(0.12f))
                    }
                }
            }
        }
        translate(w * 0.87f, h * 0.955f) {
            rotate(12f, Offset.Zero) {
                scale(u * 0.032f, u * 0.032f, Offset.Zero) {
                    drawPath(starfish, starfishColor)
                    drawCircle(starfishDots, 0.12f, Offset.Zero)
                }
            }
        }
    }

    private fun DrawScope.drawGull(t: Float, laps: Int, start: Float, y: Float, s: Float, color: Color) {
        val x = -s * 3 + drift(t, laps, start) * (w + s * 6)
        val flap = swing(t, 150, start)
        val tipY = -s * 0.35f * flap
        val bob = s * 0.3f * swing(t, 9, start)
        translate(x, y + bob) {
            val wings = Path().apply {
                moveTo(-s, tipY)
                quadraticTo(-s * 0.5f, -s * 0.45f, 0f, 0f)
                quadraticTo(s * 0.5f, -s * 0.45f, s, tipY)
            }
            drawPath(wings, color, style = Stroke(s * 0.14f, cap = StrokeCap.Round))
        }
    }

    private fun DrawScope.drawFronds(t: Float) {
        for (side in 0..1) {
            val anchor = Offset(-u * 0.05f, -u * 0.06f)
            scale(if (side == 0) 1f else -1f, 1f, Offset(w / 2, 0f)) {
                for (i in frondAngles.indices) {
                    val sway = swing(t, 9, i * 0.17f + side * 0.5f) * 2.2f
                    rotate(frondAngles[i] + sway, anchor) {
                        translate(anchor.x, anchor.y) {
                            scale(frondLengths[i], frondLengths[i], Offset.Zero) { drawFrond() }
                        }
                    }
                }
                drawCircle(coconut, u * 0.03f, anchor + Offset(u * 0.07f, u * 0.075f))
                drawCircle(coconut, u * 0.027f, anchor + Offset(u * 0.11f, u * 0.055f))
            }
        }
    }

    private fun DrawScope.drawFrond() {
        drawPath(frond.first, frondDark)
        drawPath(frond.second, frondLight)
    }
}

private const val PI_F = kotlin.math.PI.toFloat()

/**
 * A palm frond [length] long, growing along +x from the origin and drooping down: the leaflets under the
 * spine (first) and over it (second), so they can take a shade and a light green.
 */
private fun frondPath(length: Float): Pair<Path, Path> {
    val under = Path()
    val over = Path()
    val leaves = 16
    fun spine(s: Float): Offset {
        // A quadratic from (0, 0) through a raised middle to a drooping tip.
        val cx = length * 0.5f
        val cy = -length * 0.12f
        val ex = length
        val ey = length * 0.28f
        val b = 2 * (1 - s) * s
        return Offset(b * cx + s * s * ex, b * cy + s * s * ey)
    }
    for (i in 1..leaves) {
        val s = i / (leaves + 1f)
        val p = spine(s)
        val q = spine(s + 0.02f)
        val dx = q.x - p.x
        val dy = q.y - p.y
        val len = kotlin.math.sqrt(dx * dx + dy * dy)
        val tx = dx / len
        val ty = dy / len
        val leaf = length * 0.26f * sin(PI_F * (0.15f + 0.85f * s))
        val width = length * 0.018f
        for ((side, path) in listOf(1f to under, -1f to over)) {
            // Leaflets sweep back toward the tip and hang down a little.
            val nx = -ty * side
            val ny = tx * side
            val tip = Offset(p.x + (nx * 0.75f + tx * 0.55f) * leaf, p.y + (ny * 0.75f + ty * 0.55f) * leaf + leaf * 0.25f)
            path.moveTo(p.x - tx * width, p.y - ty * width)
            path.quadraticTo((p.x + tip.x) / 2 + nx * width * 2, (p.y + tip.y) / 2 + ny * width * 2, tip.x, tip.y)
            path.lineTo(p.x + tx * width * 2, p.y + ty * width * 2)
            path.close()
        }
    }
    // The spine itself, as a thin sliver.
    over.moveTo(0f, 0f)
    for (i in 1..20) spine(i / 20f).let { over.lineTo(it.x, it.y) }
    for (i in 20 downTo 0) spine(i / 20f).let { over.lineTo(it.x, it.y + length * 0.012f * (1 - i / 20f)) }
    over.close()
    return under to over
}

/** How many waves one swell line's dash pattern spans: 1.5 + 0.7 + 0.8 + 1.0. */
private const val SWELL_WAVES = 4
